-- ============================================================
-- Qazax4c (3/3): Günə-özəl push bildirişlərinin Qazax (kk) tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL Qazax1.sql (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('602f2986-8e86-421e-ab71-94038d048ccf'::uuid, 'Заңгер сияқты сөйлейді 🗣️', 'Енді сөзбен Сізді көндіруге тырыса ма? «Тағы біраз ойнайын, сосын ұйықтаймын» дей ме? Сөйлеу қабілеті керемет дамып келеді, бірақ өз шекараңызды сақтауды ұмытпаңыз.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'Пазл және логика 🧩', '5-6 бөліктен тұратын пазлдарды құрастыруға тырыса ма? Ол геометрия мен логиканы үйреніп жатыр. Оның қайталана беретін, бірақ үйретері мол әрекеттеріне кедергі жасамаңыз.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'Әкенің қолдауы 🫂', 'Түнде бөпе оянғанда міндетті түрде кезектесіңіздер. Кейде қараңғыда әкесінің ырғақты сипауы мен таныс иісі ғана баланы бірден тыныштандырады.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'Көк алма талабы 🍏', 'Көзін аша сала айқайлап, Сізден көк алма сұрайды. Табиғатта мұндай нәрсе жоқ екенін түсіндіріп, физика/биологиядан дәріс оқымаңыз. «Көк алмалар әлі ұйықтап жатыр, жүр, қызыл алманы оятайық» деп, оның қисынсыз логикасына дәл сондай қисынсыз, бірақ тиімді жауап беріңіз.'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'Көрпеге қатысты қыңырлық 🛏️', 'Ұйықтап бара жатып, кенеттен «Көрпе сол аяғыма тиіп тұр!» деп жылай бастайды. 3 жарым жастағы баланың ұйықтамау үшін ойлап тапқан осы жаңа қыңырлығына іштей жымиыңыз. Ештеңе айтпай, көрпесін түзеп, бөлменің жарығын нық қимылмен толық өшіріңіз.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'Күдік тудыратын тыныштықтың өтеуі 💄', 'Үйде кенет орнаған 10 минуттық тыныштықтың соңы: бөлмеге кірсеңіз, ол Сіздің ең сүйікті ерін далабыңызбен өз бетін де, айнаны да бояп тастаған. Ашулануға кеш.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', 'Маған қара! деген қырсықтық 👀', 'Сіз телефонға немесе басқа нәрсеге қарап отырғанда, бөпеңіз келіп бетіңізді өзіне бұра ма? Ол бар назарыңыздың өзінде болғанын қалайды. Көзіне қарап, оны тыңдап отырғаныңызды сездіріңіз.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'Әкесінің кезегі 👨‍🍼', 'Түнде бөпеңіз оянған сайын бәрін жалғыз атқармаңыз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'Не пісірсем екен? 🍲', 'Қосымша тағам мәзіріне қатысты идеяларыңыз таусылды ма? Интернеттен іздеп әуре болмаңыз, «Пайдалы рецепттер» бөлімінен жаңа дәмдер табыңыз.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'Арнайы ертегі 🪄', 'Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз: сиқырлы қайшысымен әлемге түрлі түс сыйлайтын батыл балақай.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'Саған көмектесейін! 🧹', 'Сіз киімдерді бүктеп жатқанда, оларды қолыңыздан алуға тырыса ма? Ол өзін ересек сезіне бастады. Оған кішкентай сүлгі беріп, көмектесуіне мүмкіндік беріңіз.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'Саған бір құпия айтамын 🤫', 'Төсекке жатып, көзі ілініп бара жатқанда кенеттен «Анашым, саған бір құпия айтамын» деп, ұйқыны қашыруға тырысады. Ұйықтау уақытын созу өнерінен докторлық қорғап жүргендей. Жымиып, «Құпияңды түсіңде айтарсың» деңіз де, жарықты нық қимылмен өшіріңіз.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'Печеньенің тек кремі 🍪', 'Дөңгелек печеньенің ортасындағы кремін жалап, құрғақ бөліктерін үстелдің шетіне тізіп қойды ма? Құттықтаймыз, Сіз 3.5 жастағы баланың тағам философиясымен ресми түрде таныстыңыз. «Пайдалы рецепттер» бөлімінен оның назарын аударатын, пайдалы әрі көңілді тіскебасарларды табыңыз.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'Сен ән айтпа! деген тыйым 🛑', 'Фонда ойнап тұрған балалар әніне қосылып ыңылдап едіңіз, ол бірден: «Сен ән айтпа!» деп айқайлады. Бөлмедегі жалғыз әнші — өзі, ал Сіздің ән айтуға талпынысыңыз оның сахнасына кедергі келтіреді. Ренжімеңіз, сахнаны осы кішкентай өзімшілге қалдырыңыз.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'Ертегідегі әртүрлі дауыс реңктері 🪄', 'Бүгін кешке Ақылды ертегілерді қосыңыз, бірақ мәтінді әртүрлі дауыспен оқыңыз. Аюдың дауысын жуан, құстың дауысын жіңішке етіп салып, бөлмеде шағын театр ұйымдастырыңыз. Бұл бірсарынды көңіл күйді сейілтіп, баланың назарын бірден ертегіге, одан әрі ұйқыға жетелейді.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'Қараңғыдағы сыбырлы сырласу 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды немесе оның мінезіндегі өзіңізге ең ұнайтын қасиетті өте бәсең дауыспен құлағына сыбырлап айтыңыз. Сыбырлау — миды ұйқыға дайындап, айналадағы шуды ұмыттыратын ең тылсым тәсіл.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'Үй ішіндегі қолшатыр ☂️', 'Далада күн ашық, ал ол үйдің ішінде ашық қолшатырмен жүргісі келеді. Оның қиялы нақты ортаның шектеулерін қабылдамайды. Үйде бос орын болса, сол қолшатырдың астына өзіне шағын күрке құруына рұқсат етіңіз. Балалардың ойлау жүйесін қоғамның қалыптарына салып тұншықтырмаңыз.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'Дүкендегі «Жоқ» сынағы 🛒', 'Дүкеннің қақ ортасында кәмпит сұрады, Сіз «Жоқ» дедіңіз, ал ол жылай бастады. Айналадағылардың сынай қарағанына қарамастан, шешіміңізден таймадыңыз. Сіз керемет анасыз! Ал ештеңені ұмытпау үшін тезірек шығып кетуге көмектесетін Сатып алу тізімін назарда ұстаңыз.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'Еш себепсіз «Неге менің атымды атадың?» 😤', 'Сіз жай ғана «Кел, тамақ дайын» дедіңіз, ал ол ашуланып, «Неге менің атымды атадың?» деп жылай бастады. Бұл жаста эмоциялар соншалықты күрделі болғандықтан, кейде балалар еш себепсіз де ренжиді. Ештеңе түсіндірмеңіз, 2 минуттан кейін өзі тамаққа жүгіріп келеді.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'Жасанды интеллект және оғаш фобиялар 🤖', 'Үнемі ойнап жүрген қызыл көлігінен кенет қорқа бастады ма? Түсініксіз фобиялар Сізді алаңдатса, интернеттегі үрейлі форумдарды жабыңыз. Anacan AI-дан 3.5 жастағы баланың қиялына тән ерекшеліктер туралы ғылыми негізделген әрі сабырға шақыратын жауап алыңыз.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'Жұп болып фильм көру... 🎬', 'Бала ұйықтап қалды! Ақыры жұбайыңызбен фильм көру үшін диванға жайғастыңыздар, бірақ 10-минутта екеуіңіз де қатты ұйықтап қалдыңыздар. Бұл — Сіздің шынайы өміріңіз. Бір-біріңізге сүйеніп ұйықтап қалған сол шаршаңқы көрініс — нағыз командалық жұмыстың белгісі.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'Төсектегі қиқымдар 🍞', 'Таңертең көзіңізді ашсаңыз, төсектің іші крекер қиқымдарына толып жатыр. Сөйтсе, таңсәріден өзіне таңғы ас дайындап алыпты. Айқайлаудың орнына, оның мәселені өз бетінше шешу қабілетін Даму бақылаушысына күлкілі естелік ретінде жазып қойыңыз.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'Сөздер ремиксі 🗣️', '«Су» мен «сүт» сөздерін біріктіріп, «сүтсу» сияқты мүлде жаңа сөздер ойлап табады да, күледі. Ол сөздік қорынан ремикс жасап жүр! Оның осы тілдік ойындарына қосылып, бірге күліңіз. Бөпеңіздің миы тілдің шекараларын дәл осындай тәжірибелер арқылы танып-біледі.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'Кенеттен келген махаббат тасқыны 🫂', 'Таңертең Сізге «Кетші» деген балаңыз төсекке жатқанда мойныңыздан тас қылып құшақтап, «Мен сені дүниедегінің бәрінен де қатты жақсы көремін» дейді. Аналықтың парадоксы деген осы! Оның жылы демін сезініп, бір күндік шаршауыңыздың түгел сейілуіне мүмкіндік беріңіз.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'Анашым, кетші! 💔', 'Қалағаны орындалмай қалса, Сізге қарап: «Сені қаламаймын, кетші!» дейді. Бұған көңіліңіз түспесін. Ол әлі ашуын қалай басқару керектігін білмейді. Мұны өзіңізге қабылдамаңыз. «Мен осындамын, сен тынышталған соң сөйлесеміз» деп, оған сезімдерін еркін өткеруге мүмкіндік беріңіз.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'Дүкендегі кішкентай заңгер 🛒', 'Дүкенде кәмпит үшін жерге жата қалып жылаудың орнына: «Мынаны алсақ, үйде сорпамды ішемін», — деп саудаласады. Құттықтаймыз, кішкентай заңгеріңіз өсіп келеді! Ал ештеңені ұмытып кетпеу үшін сауда тізімін ашық ұстаңыз. Сонда онымен пікірталасып жүріп, негізгі мақсатыңыздан ауытқымайсыз.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'Ваннадағы цунами 🌊', 'Ваннаға түсу енді жай ғана жуыну емес, кішкентай цунами жасау ойынына айналды. Су жан-жаққа шашыла берсін. Судың бойдағы энергияны өзіне тартатын тылсым әсері күні бойы жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып әкетеді.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'Ананың жалқаулыққа құқығы 🍕', 'Бүгін бәріне айқайлағыңыз келіп тұр ма? Үйдің астаң-кестеңі шықты ма? Тазалықты қоя тұрыңыз, пешті де жақпаңыз. Сырттан пиццаға немесе дайындауы ең оңай кез келген тағамға тапсырыс беріңіз. Мінсіз ана болу елесін бұзыңыз: психологиялық саулығыңыз үй тағамынан әлдеқайда маңызды.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'Суды өзі құюға деген қырсықтығы 💧', 'Ол суды үлкен құмырадан кішкентай стақанға міндетті түрде өзі құйғысы келеді. Су үстелге, одан әрі еденге төгіледі. Бірақ шүберекті алып, төгілген суды сүртуге тырысқан кішкентай қолдарына қараңызшы. Ол қателесу арқылы жауапкершілікті үйреніп жүр. Бұл ретсіздік — дамудың нақ өзі.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'Кішкентай қайшымен танысу ✂️', 'Балаларға арналған қауіпсіз пластик қайшымен қағаз қиып көруге тырысып жүр ме? Бұл ұсақ моторикаға арналған тамаша жаттығу! Мұны даму трекеріне міндетті түрде белгілеңіз.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'Әкенің сиқырлы қолдары ✈️', 'Күні бойы көтеріп жүруден қолыңыз талып қалды, ал оның әлі де энергиясы тасып, ұйықтағысы келмейді. Әкесін көмекке шақырыңыз. Ол баланы әуеге көтеріп, ұшақ болып ойнағанда, бөлме шат күлкіге толып, жиналған сарқылмас энергия әп-сәтте таусылады.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'Жиекпен жүру сынағы 🧱', 'Саябаққа бара жатқанда ол тегіс жолмен емес, арқан үстіндегі акробаттай тротуардың ең тар әрі биік жиегімен жүргісі келеді. Осылайша ірі моторикасы мен тепе-теңдік сақтау қабілеті дамиды! Қолынан ұстап, қауіпсіздігін қамтамасыз етіңіз де, өзі үшін аса маңызды осы кішкентай шыңды бағындыруына мүмкіндік беріңіз.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'Көрінбейтін итпен серуен 🐕', 'Бөлменің ортасында қолын төмен созып, көрінбейтін итті сипап, онымен сөйлесіп жүр. Бұл — қиялдың ең пәк кезеңі. «Иттің аты кім?» деп сұрап, бөлменің бір бұрышына қиялдағы су құятын ыдыс қойыңыз да, осы ғажайып театрдың қосалқы рөлдегі актеріне айналыңыз.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'Киімге қатысты бүлік 🕶️', 'Таңғы асқа күннен қорғайтын көзілдірік пен қысқы бас киім киіп келіп, оларды шешуден үзілді-кесілді бас тартады. Сыртқы үйлесім мен «жұрт не дейді» дегенді қоя тұрыңыз. Өз бетінше шешім қабылдап, оны қорғау еркіндігі — киімнің үйлесімділігінен әлдеқайда маңызды психологиялық негіз.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'Тыныштықтың цифрлық өлшемі 🤫', 'Үйдегі шудан құлағыңыз шыңылдап кетті. Ол ақыры ұйықтап қалғанда, Дыбыс өлшегіш құралын қосыңыз. Экрандағы көрсеткіштің 0-10 децибелге дейін төмендеп, цифрлық тыныштық орнағанын бақылау — шаршаған ананың миына жасалған ең жағымды әрі көрнекі тыныштандыратын массаж.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'Құмырсқаны құтқарушы 🐜', 'Саябақта жердегі құмырсқаны біреу басып кетпесін деп, жылап тұрып жолын бөгеді ме? Оның кішкентай жүрегіндегі осыншалық зор мейірім мен жанашырлыққа сүйсініңіз.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'Ақылды ертегідегі мен 🪄', 'Классикалық кітаптарды оқи беруден дауыс желбезегіңіз шаршады. Ақылды ертегілерді қосыңыз. Басты кейіпкерді балаңыз етіп, фонға тыныштандыратын орман дыбыстарын таңдап, еш күш жұмсамай-ақ ерекше әрі ұйқыға жетелейтін гипноздық сеанс жасаңыз.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'Қауымдастықтың үнсіз жұбанышы 💬', '«Мен енді ешқашан бұрынғы еркін, алаңсыз қалпыма оралмаймын» деген ой кенеттен жаныңызды қыса ма? Anacan қауымдастығына кіріңіз. Басқа аналардың да осындай ауыр, бірақ өте табиғи сезімдерді бастан өткеріп жатқанын және бұл ана болудың бір кезеңі екенін оқып, жұбаныш табыңыз.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'Ананың қабырғамен көз арбасуы 🛋️', 'Бөлме іші у-шу, ол ойыншықтарын бір-біріне соғып отыр, ал Сіз бос қабырғаға қарап, ойыңыздан ажырап қалғансыз (zoned out). Бұл — миыңыздың қорғаныс механизмі. Сол 5 минуттық қатып қалу сәті үшін өзіңізді кінәламаңыз, ол өмірге қайта оралуыңыз үшін қажет.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'Қоғамдық жерде қойылатын есеңгіретер сұрақтар 😳', 'Автобуста немесе дүкенде қатты дауыстап «Мына тәтенің мұрны неге сонша үлкен?» деп сұрады ма? Жер жарылып, ішіне кіріп кеткіңіз келетін сол бір сәт! Баланы тыйып, ұялтудың орнына, назарын бірден басқа түсті затқа аударып, жағдайдан дипломатиялық жолмен шығып кетіңіз.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'Әкенің логикаға сыймайтын шарттары 🎲', 'Кешке пижама кимеу үшін үй ішінде қашып жүр. Әкесі «Қане, осы пижаманы көзіңді жұмып кие аласың ба?» деп, тосын ойын ұсынады. Бум! Бала байқамай-ақ пижамасын киіп алады. Әкелердің логикаға сыймайтын, бірақ нәтижелі осындай ойындарына сырттай қол соғу ғана қалады.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', '«Мен бөпемін!» деген сағыныш 🍼', 'Кенет бөпе сияқты еңбектеп, жылап, «Мен бөпемін, мені құшақташы» дей бастады ма? Өсу кейде оларды да қорқытады, сондықтан бұрынғы қауіпсіз бөпе кезіне оралғысы келеді. Оны бірнеше минутқа сол кездегідей құшақтап, еркелетіңіз.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'Балшықтан жасалған сорпа 🍲', 'Саябақта су мен топырақты араластырып, «Анашым, Сізге сорпа пісірдім» деп, балшықты ұсынады. Жиіркенуге болмайды! Сол сорпаны қиялыңызда ең дәмді тағамдай сүйсініп ішіңіз.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'Тыныштықтың цифрлық рақаты 🤫', 'Үйдегі аласапыран ақыры басылып, ол ұйықтап қалды. Дыбыс өлшегішті қосып, бөлмедегі тыныштық деңгейін (0-10 desibel) экраннан бақылаңыз. Нөлге жуық сандарды көру шаршаған ананың миына әлемдегі ең қымбат спа-сеанс сияқты әсер етеді.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'Банандағы сызат 🍌', 'Бананның қабығын аршығанда, бетіндегі кішкентай ғана миллиметрлік сызатты көріп, «Бұл бұзылып кеткен!» деп айқайлай ма? Балалардың мінсіз көрініске деген талабы кейде шектен шығады. Сол жерін пышақпен кесіп алып, «Құтқардым!» деп осы шағын драманы аяқтаңыз.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'Есікті құлыптау миссиясы 🚪', 'Үйдегі барлық бөлменің есігін ішінен жауып, Сізді сыртта қалдырудан ерекше ләззат алады. Жеке кеңістік туралы түсінігі нағыз төңкеріс жасап жатыр. Саусақтары қысылып қалмауы үшін қауіпсіздік шараларын қолданыңыз, бірақ оның өз аумағын жариялау ойынына қатты кедергі келтірмеңіз.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'Әкеден иық массажы 💆‍♂️', 'Бүгін көп уақыт тік тұрып, оның артынан жүгіремін, жердегі ойыншықтарды жинаймын деп беліңіз талып кетті. Бөпе ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — отбасының тірегісіз, ал тірек міндетті түрде демалып, күшін қалпына келтіруі керек.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'Өзім істеймін! 🛑', 'Ол аяқкиімінің бауын міндетті түрде өзі байлағысы келеді, бірақ қолынан келмей, ашуланады әрі Сіздің көмегіңізден де ызаланып бас тартады. Терең тыныс алыңыз. Бұзылған уақыт кестесінен гөрі, баланың өзіндік «меніне» нұқсан келмеуі оның болашағы үшін маңыздырақ. Күте тұрыңыз.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', '«Ол маған қарады!» трагедиясы 👀', 'Саябақта басқа бір бала оған жай ғана қарағаны үшін өксіп жылай бастады ма? Әлеуметтік шекараларын енді танып келе жатқан бала үшін өзгенің көзқарасының өзі жеке кеңістігіне қол сұғу болып көрінуі мүмкін. Оны құшақтап, «Ол сенің әдемі жейдеңе ғана қарап тұр» деп назарын басқаға аударыңыз.'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'Ақылды ертегілермен тыныштандыру 🪄', 'Ол бөлмеде жүгіріп жүр және төсекке жатудан бас тартады. Жарықты бәсеңдетіңіз. Ақылды ертегілерде қызықты оқиға құрастырып, оқып беріңіз.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'Ойыншықтарды қатарға тізу 🚗', 'Ол барлық мәшинесін бөлменің бір шетінен екінші шетіне дейін миллиметрлік дәлдікпен тізіп қойып, тіпті біреуінің орнын өзгертуге рұқсат бермейді. Бұл — көзге көрінетін тәртіпке деген қажеттілік. Осы кішкентай сәулетшінің жұмысын сырттай үнсіз тамашалаңыз және ретін бұзбаңыз.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'Қауымдастықта үнсіз оқырман болу 💬', 'Сіз қатты шаршадыңыз және ешкімге ештеңе түсіндіргіңіз де, ішіңіздегіні бөліскіңіз де келмейді. Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың дәл осындай қисынсыз дағдарыстарды қалай еңсеріп жүргенін көру — ең әсерлі үнсіз терапия.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'Қасық өлшемі дұрыс емес деген дағдарыс 🥄', 'Сорпаны үлкен қасықпен бергеніңіз үшін үйде төңкеріс бола жаздады. «Мен кішкентай қасықты қаладым!» Тағам бірдей болса да, оның түсінігінде қасықтың өлшемі астың дәмін өзгертеді. Дауласпаңыз, қасықты жай ғана ауыстырып, күшіңізді үнемдеңіз.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', '«Мені жап!» әуресі 🛏️', 'Ұйықтап бара жатқанда көрпенің шеті ашылып қалса, «Мені жап!» деп айқайлайды. Көрпе жиектерінің міндетті түрде түзу жатуы ол үшін өмірлік маңызы бар мәселе. Көрпені үтіктелгендей етіп тегістеп қойыңыз да, осы күлкілі ұйықтау рәсімдеріне іштей жымиыңыз.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'Пластырға деген махаббат 🩹', 'Бөпеңіз денесінен көзге көрінбейтін бір жара тауып алып, сол жерге пластырь жапсыруыңызды қ insistently сұрайды. Бұл физикалық ауырсыну емес, жай ғана анасының назары мен мейіріміне деген қажеттілік. Кішкентай пластырьді жапсырып, сол жерден сүйіп қойыңыз — сеніңіз, күніңіз сәтті өтеді.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'Тыныштықтың көз қуантар рақаты 🤫', 'Үйдегі қарбалас ақыры басылып, бөпеңіз ұйықтап қалды. Ыдыс жууға асықпаңыз! Дыбыс өлшегішті қосып, бөлмедегі мүлгіген тыныштыққа (0-10 децибел) қарап, 15 минут ішінде миыңыздың қалай тынығып, осы көзге көрінетін тыныштықтың жаныңызға қалай шипа сыйлайтынын сезініңіз.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'Құм сәулеті 🏰', 'Саябақтағы құмсалғышты қазып, қазына іздеп жүргендей терең шұңқыр жасап жатыр. Үсті-басы балшық. Бірақ оның жаңалық ашқан осы сәтін бұзбаңыз. Ауа райына сай әрі кірлеуге болатын киімді алдын ала таңдап қойсаңыз, бұл көріністі күйзелмей тамашалай аласыз.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'Кешкі жаттығу — әкесінің үстінде секіру 🤸‍♂️', 'Бөпеңіз энергиясын жұмсай алмай, төсекке жатқысы келмейді. Әкесін диванға жатқызып, баланың оның үстінде секіруіне рұқсат етіңіз. Әкесінің күлкілі дыбыстары бөлмені шат күлкіге толтырады, ал артық энергия санаулы секундта таусылады.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'Ананың өзіне қамқорлығы 🥗', 'Оны тойдыру үшін 3 түрлі мәзір ойластырдыңыз, ал өзіңіз тағы да аш қалдыңыз ба? Тамақтану жоспары бөлімінен балаларға ғана емес, аналарға да арналған, 10 минутта дайындалатын, темір мен кальцийге бай әрі қуат беретін түскі асты таңдап, өзіңізге де көңіл бөліңіз.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', '«Сен кімсің?» ойыны 🎭', 'Таңертең Сізге өте салмақты кейіппен қарап: «Сен кімсің? Менің анам қайда?» — дейді. Қиял дамуының нағыз шарықтау шегі! Ойынға қосылыңыз: «Мен көрші апаймын, анаң қазір келеді», — деп, дауыс ырғағыңызды өзгертіп, осы тамаша қойылымды жалғастырыңыз.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'Дәретхана қағазынан өнер жасау 🧻', 'Бірнеше минуттық тыныштық... Бөлмеге кірсеңіз, дәретхана қағазы түгел тарқатылып, бүкіл үйге жайылып жатыр! Ашуланудың орнына қағаздарды жинап, бірге аққала немесе доп жасаңыз. Бейберекетті айқаймен емес, шығармашылықпен жеңіңіз.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'Құлаққа сыбырланған махаббат сөздері 💖', 'Ол күні бойы Сізді әбден шаршатып, бәріне қырсықты. Ал қазір төсегінде сондай пәк кейіппен ұйықтап жатыр... Жанына жатып, оны қаншалықты жақсы көретініңізді және бүгін жасаған жақсы істерін құлағына сыбырлап айтыңыз. Балалар ұйықтап жатса да, анасының мейірімге толы дауысын сезеді.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'Кір жуғыш машинаның қызығы 🧺', 'Кір жуғыш машинаның алдында отырып, айналып жатқан киімдерге мультфильм көргендей қадала қарайды. Бұл — мүлде тегін әрі ойды тыныштандыратын ойын-сауық. Оған кедергі жасамаңыз, өзіңіз де осы мүмкіндікті пайдаланып, демалып алыңыз.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'Ертегіден қашу әрекеттері 🏃‍♂️', 'Ертегі оқып жатқанда, «ойыншығымды әкелейін» деп сылтау тауып, төсектен қайта-қайта атып тұрады. Ұйқыға берілгісі келмейді. Даусыңызды кенет қатты бәсеңдетіп, сыбырлап оқи бастаңыз. Сізді есту үшін ол амалсыз төсегіне оралып, мұқият тыңдайды да, ұйықтап қалады.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'Мен өстім, кофе ішемін! ☕', 'Сіздің кесеңізге қолын созып, «Мен өстім, мен де кофе ішемін» деп нық айтады. Ол жай ғана Сіздің әлеміңізге қосылғысы келеді. Оның кішкентай кесесіне аздап сүт пен какао құйып, «Міне, бұл — сенің балаларға арналған кофең» деңіз де, бірге кесе соғыстырыңыз.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'Ауа райы және қабаттап киіндіру тәсілі ⛅', 'Көктемге қарай ауа райы құбылмалы болады: таңертең салқын, түсте жылы. Ауа райы мен киім құралы Сізге бөпеңізді «пияз қағидасымен», яғни қабаттап киіндіруді еске салады. Саябақта күн жылынған сайын киімнің бір қабатын шешіп, оның терлеуіне де, өзіңіздің алаңдауыңызға да жол бермеңіз.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', '«Мұрныңды ұрлап алдым» ойыны 👃', '«Мұрныңды алып қойдым!» деп бас бармағыңызды көрсетесіз, ал ол бұған шынымен сеніп, жылай бастайды! 3.5 жастағы баланың қиялы кейде шындық пен елесті ажырата алмайды. Бірден «Міне, орнына қойдым» деп, мұрнынан сүйіп, осы кішкентай жағымсыз әсерді күлкіге айналдырыңыз.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'Жұбайыңызбен үнсіз ұғынысу 🥂', 'Бала ақыры ұйықтады. Сіз бен жұбайыңыз диванда қатар отырсыздар, тіпті сөйлесуге де күштеріңіз жоқ. Тек үнсіз бір-біріңізге қарап, жымиясыздар. Бұл үнсіз көзқарас — «Біз осы бейберекетті керемет еңсеріп жүрміз» деудің ең әдемі жолы.'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'Жасанды интеллект және аяқ астынан қырсығу 🤖', 'Кеше ғана сабырлы болған бала бүгін бәріне ашумен жауап бере ме? Интернеттен қорқынышты себептер іздемеңіз. Anacan AI-дан осы даму секірісінің (менталдық секіріс) психологиялық себептерін сұрап, педиатрлар мақұлдаған жауап арқылы уайымыңызды басыңыз.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', '«Мұны мен таптым» — меншіктенгіш бүлдіршін 🔑', 'Үйдегі пультті немесе әкесінің кілтін жерден көтеріп алып, «Мұны мен таптым, демек, бұл менікі!» дейді. Ол үшін бір нәрсені табу — оны иелену деген сөз. Қолынан күштеп тартып алмаңыз. «Мен үшін тауып бергеніңе рақмет» деп, назарын басқа ойыншыққа аударыңыз да, затты қайтарып алыңыз.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'Таңғы жасырынбақ 🙈', 'Сіз жұмысқа немесе балабақшаға кешігіп барасыз, ал ол перденің артына тығылып алып: «Мені тап!» дейді. Жүйкеңіз жұқарса да, айқайлау бұл процесті одан әрі созады. «Менің сүйкімді балам қайда екен?» деп, ойынға 2 минутқа қосылыңыз да, оны тауып алып шығыңыз.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'Тамақты түсіне қарай бөлу 🍅', 'Тәрелкедегі тағамдарды түсі мен пішініне қарай бөліп, жасылдарын шетке ысырып қояды. Тамақтану жоспарына кіріңіз. Көкөністерді көзге түспейтін езбе жасап, дәмді тұздықтардың ішіне жасыру жолдарын үйреніп, бұл ойында білдіртпей жеңіске жетіңіз.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'Әкенің ойдан шығарған хикаялары 📖', 'Бүгін кешке бөлмеде Сіздің емес, әкесінің даусы естілсін. Ертегі кітабын әкесіне беріп, оқиғаны әдейі шатастырып, күлкілі әрі қисынсыз етіп айтып беруіне мүмкіндік беріңіз. Балаңыздың оны түзеткеннен қалай рақаттанып, әкесіне қалай қарқылдап күлетінін сырттай тамашалаңыз.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'Көңіл күй күнделігіне ашуды төгу 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай ма? Көңіл күй күнделігі — Сіздің ең үнсіз сырласыңыз. Бүгін жаныңызға тиген барлық ұсақ-түйекті сонда жазып, ойыңыздың қалай жеңілдегенін және уайымдарыңыздың қалай сейілгенін экраннан көріңіз.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'Үйде бас киіммен жүру 🧢', 'Ол қыстық бас киімін үйде киіп жүргісі келеді. Қасарысып, шешпей қояды. Қоғамдық қалыптарды ұмыта тұрыңыз. Оның шығармашылығы мен шешім қабылдау еркіндігін шектемеу үшін күнін сол ерекше, күлкілі кейіпте өткізуіне рұқсат етіңіз. Бөлме температурасы қалыпты болса, кие берсін.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', '«Сен мені тыңдамайсың!» деген соққы 😠', 'Сіз телефонға қарап немесе тамақ араластырып тұрғанда, ол келіп бетіңізді өзіне бұрады: «Маған қара!» Оның айтқаны дұрыс. Оған Сіздің жай ғана жанында болғаныңыз емес, бар назарыңыз қажет. Ісіңізді тоқтатып, небәрі 3 минут бойы көзіне қарап, мұқият тыңдаңыз.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'Саябақта танысуға талпыныс 🤝', 'Саябақта бейтаныс баланың жанына барып: «Менің атым...» деп өзін таныстырады. Әлеуметтік дағдылары таңғаларлық жылдамдықпен қалыптасып келеді. Даму трекерінде оның қарым-қатынас орнатуға бағытталған осындай батыл қадамдарын тұлғалық дамуының мақтан тұтарлық жетістігі ретінде сақтаңыз.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'Қырсық «Жоқ!» кезеңі 🛑', '«Су ішесің бе?» — «Жоқ!» Бірақ 5 секундтан кейін су сұрап жылайды. Бұл — шешімдерінің салдарын сынап көретін кезең. Олар шын мәнінде қалаған нәрселеріне де «жоқ» дейді. Суды үстелге қойып, мәжбүрлемеңіз. Ішкі тартысын аяқтаған соң өзі-ақ ішеді.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'Ақылды ертегілермен оңай ұйықтау 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкері балаңыз, ал бағындыратын жері оның бөлмесі болатындай етіп құрастырыңыз. Еш күш жұмсамай-ақ ерекше аудио ұйқы сеансын жасап, өзіңіз де демалыңыз.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'Қараңғы бөлмедегі көлеңкелер театры 🐰', 'Қараңғыдан қорқатынын сылтауратып, төсектен қашады. Бөлмедегі барлық жарықты өшіріп, қолшамды жағыңыз да, қабырғаға қолыңызбен құс пен иттің көлеңкесін түсіріңіз. Ол қорқатын қараңғылық санаулы секундта театрға айналады.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'Дыбыс өлшегішпен тыныштықты сақтау 🤫', 'Үйдегі у-шудан құлағыңыз тұнады. Ол ақыры ұйықтағанда, Дыбыс өлшегіш құралын іске қосыңыз. Экрандағы нөлге жуық сандарды, цифрлық тыныштықты бақылау — шаршаған ананың миына арналған ең керемет визуалды массаж.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', '«Сен отырма!» диктатурасы 🪑', 'Сіз диванға отырғыңыз келеді, ал ол жүгіріп келіп: «Ол жерде қонжығым отырады, сен тұр!» — дейді. Үйді өзі басқаруға тырысады. Оның ерік-жігерін бірден басып тастамай, «Қонжығың осында отырсын, мен де оның жанына отырайын» деп, тепе-теңдік пен бөлмедегі тыныштықты сақтаңыз.'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: Балалар неге өтірік айтады? 🤥', '«Суды мен төккен жоқпын, ойыншық төкті», — деді. Ол өтірік айтып тұр ма, әлде қиялын қолданып жүр ме? Интернеттен қорқынышты жауаптар іздемеңіз. Anacan AI-дан 3.5 жастағы баланың мұндай қиялдары дамудың қалыпты кезеңі екенін біліп, көңіліңізді тыныштандырыңыз.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'Жұбайыңызбен күлкіге қарық болу 🥂', 'Бала ақыры ұйықтады. Күні бойы жүйкеңізді жұқартқан сол бір қисынсыз жағдайды жұбайыңызға айтып отырғанда, кенет екеуіңіз де қарқылдап күле бастайсыздар. Иә, мұндай күлкі — ата-ана болудың ең тәтті сыйы.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'Ойыншықтарды ваннаға апару 🛀', 'Шомылғысы келмейді, бірақ барлық мәшинесі мен пластик қонжықтарын ваннаға жинағаннан кейін ғана суға түсуге келіседі. Кедергі жасамаңыз. Ваннадағы сол ойыншықтар оған судың тыныштандыратын әсеріне бой алдыруға көмектесетін ең жақсы құралдар.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'Макаронға деген махаббат 🍝', 'Кеше ғана жақсы көрген етінен бүгін бас тартады, тек күні бойы макарон жегісі келеді. Оның қалауымен күреспеңіз. Пайдалы рецепттерде макаронға ақуыздар мен көкөністерді көзге көрінбейтін тұздық ретінде қосуды үйреніп, жеңіске жетіңіз.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'Жуынатын бөлмедегі шағын SPA 🛀', 'Бүгін кешке ваннаға бөпеңізді ғана емес, өзіңіз де түсіңіз. Бөпе ұйықтағаннан кейін жылы суға аздап көбік қосып, жуынатын бөлмеде бір ғана шам жағыңыз. Есікті құлыптап, небәрі 15 минутқа ана рөлінен шығып, қайтадан өзіңіз болыңыз.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'Шаштараз болуға талпыныс ✂️', 'Бөлмеге кіргенде, оның қолына қайшы ұстап, қуыршағының шашын қиюға тырысып жатқанын көресіз. Мұндай сәт — әр ананың қорқынышты түсі. Ашуланбай, қайшыны қолынан алыңыз да, осы шаштараздық талпынысын Бөпе фотосессиясына түсіріп, күлкілі естелік ретінде сақтап қойыңыз.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'Әнді артқа қайтар! 🎶', 'Радиода ойнап біткен әнді қайта қосуды сұрайды. Сіз оның тікелей эфирде болғанын және аяқталғанын түсіндіресіз. Бірақ ол Артқа қайтар! деп жылайды. Баланың миы тікелей эфирдің қалай жұмыс істейтінін әлі түсінбейді. Назарын басқаға аудару үшін әнді өзіңіз өзгеше, күлкілі дауыспен айтып бастаңыз.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'Сатып алу тізіміндегі қажетсіз дүниелер 🛒', 'Дүкенге бармас бұрын Сатып алу тізімін ашсаңыз, артыңыздан келіп, телефон экранын басып, тізімге түсініксіз әріптер мен шоколадты бірінен соң бірін қосып қойғанын көрдіңіз. Иә, олар цифрлық әлемді өте жылдам меңгереді!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'Тыныштықта ішілген шай ☕', 'Бөлменің ортасында ойыншықтарын қатарға тізіп, өз бетімен ойнап отыр. Айналайын, сол сәтті үй сыпыруға жұмсамаңыз! Диванға жайғасып, кофеңізді немесе шайыңызды суытпай ішіңіз де, 10 минут бойы ештеңе ойламай, осы тыныштықтан ләззат алыңыз.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'Ұйқы таймерінің тәсілі ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен шөлдеп, дәретханаға барғысы келе ме немесе қабырғамен қоштаса бастай ма? Таймер орнатыңыз. Қоңырау соғылғанда бәрі ұйықтайды деген ережені енгізіп, осы шексіз қоштасу мен шебер айладан еш дауласпай құтылыңыз.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'Нағыз суретші қабырғаны таңдайды 🖍️', 'Бірнеше секундтық тыныштықтың соңы қауіпті жағдайға ұласты. Бөлмеге кіріп, оның қабырғаға фломастермен өнер туындысын салып жатқанын көрдіңіз. Терең тыныс алыңыз. Ұсақ моторикасы дамып жатыр, ал қабырғаны бәрібір тазалауға болады. Болашақта күлу үшін бұл жауһарды міндетті түрде суретке түсіріп алыңыз.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Anacan қауымдастығының күші 💬', 'Менің балам неге сонша қырсық? деген ой мазаңызды алады. Anacan қауымдастығына кіріңіз. Басқа аналардың үйінде болатын осыған ұқсас қисынсыз дағдарыстар туралы оқығанда, жалғыз емес екеніңізді және басыңыздан өтіп жатқандардың бәрі қалыпты екенін түсінесіз.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'Суық кофенің шындығы ☕', 'Кофені демдеп қойып, 3 сағаттан кейін мұздай күйінде ішу — ана болудың жазылмаған заңы. Бірақ бүгін өзгеше әрекет етіңіз! Бөпеңізді сүйікті мультфильмімен оңаша қалдырып, кофеңізді ыстық күйінде ішіңіз. Сіз робот емессіз, демалуға құқығыңыз бар.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'Дыбыс өлшегіштегі цифрлық тыныштық 🤫', 'Ол ақыры ұйықтап қалды! Үйді жайлаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз да, миыңыздың біртіндеп қалай тынығып жатқанын көзбен көріп сезініңіз.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'Мен сенің анаңмын! 👩‍👧', 'Рөл ауыстыру ойыны басталды! Ол Сізге Бері кел, төсекке жат, жылама деп бұйрық береді. Оның көшбасшы болу тәжірибесін қуана қабылдап, үндемей оның баласының рөлін ойнаңыз — бұл эмпатияны дамытады.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'Жасырын дәрумендер операциясы 🥣', 'Кеше ғана сүйіп жеген асын бүгін аузына да салғыза алмай жүрсіз. Оның еркімен күреспеңіз. Пайдалы рецепттердегі ақуыздарды өзгеше, түрлі түсті әрі қызықты пішінге келтіретін тіскебасарлар дайындап, жағдайды өз пайдаңызға шешіңіз.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'Ойыншығым ауырып қалды 🩺', 'Ол ойыншық стетоскопын алып, қонжығын мұқият тексеріп, оған жараға арналған жапсырма жапсырып жатыр. Символдық ойындар арқылы бөпеңіз жанашырлықты үйреніп, қоршаған ортаны түсіне бастайды. Сіз де ауруханадағы пациент рөліне еніп, ойынға қосылыңыз.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'Ақылды ертегілермен арманға қанат бітіру 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкерді балаңыз, ал бағындыратын мекенді оның бөлмесі етіп құрастырыңыз да, ерекше әрі еш күш жұмсауды қажет етпейтін дыбыстық ұйқы сеансын жасаңыз.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'Көңіл күй күнделігіндегі сырлар 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай ма? Көңіл күй күнделігі — ең үнсіз сырласыңыз. Бүгін Сізді ашуландырған барлық жайтты сонда жазып, экранға қарай отырып, ойыңыздың қалай жеңілдеп, уайымыңыздың қалай сейілгенін көріңіз.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'Ауа райы және оның тосын өзгерістері ⛅', 'Сырттағы ауа райы құбылмалы ма: күн шығып тұрса да, жел соғып тұр ма? Ауа райы мен киім таңдау құралы терезеден байқалмайтын желдің жылдамдығы мен дұрыс киім үйлесімін бірден көрсетсін. Есік алдында ойланып, уақыт жоғалтпай серуенге шығыңыз.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'Айна алдындағы билер 🪞', 'Ол айна алдына тұрып, ән айтып, түрлі би қимылдарын жасап көреді. Осылайша өз денесінің ырғағын және қимылдарының қалай көрінетінін байқап жүр! Даму трекерінде оның денесін сезінуі мен ырғақты қабылдау қабілетін қуана атап өтіңіз.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'Сыбырлы ұйқы дуэті 🌙', 'Ол төсекте тыным таппай, ұйықтай алмай жүр. Даусыңызды көтерудің орнына, бірден бәсеңдетіп, оның сүйікті әнін сыбырлап айта бастаңыз. Бөпе Сізді есту үшін зейін қойған кезде, миы біртіндеп тынышталып, ұйқы режиміне ауысады.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'Шаш тарау — нағыз жау 🪮', 'Тарақты көре сала айқайлап, бөлмеден қашып кетеді. Онымен арпалысуды доғарыңыз. Алдымен тарақты қолына беріп, Сіздің немесе қуыршағының шашын тарауына мүмкіндік беріңіз. Жағдайды өзі басқарып тұрғанын сезінген соң, кезекті Сізге беруге келіседі.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'Anacan қауымдастығындағы қолдау 💬', '«Мен енді ешқашан бұрынғы еркін қалпыма орала алмаймын» деген ой кейде Сізді тұншықтырып жібере ме? Осы өткінші болғанымен, өте ауыр әрі терең сезімді Anacan қауымдастығындағы аналармен бөлісіңіз. Олардың да осындай кезеңнен өткенін біліп, жұбаныш пен қолдау табыңыз.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'Су терапиясы 🌊', 'Кейде ештеңе көмектеспей, ол бәріне жылай береді. Оны жылы су толтырылған ваннаға отырғызып, аздап көбік қосыңыз. Судың бойды босатып, ширығуды басатын ғажайып әсері бүкіл бөлмеге тыныштық орнатып, оның жүйке жүйесін де бірден жайландырады.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'Әкенің массаж уақыты 💆‍♂️', 'Бүгін аяғыңыздан тік тұрып, оның артынан жүгіріп, жердегі ойыншықтарды жинаймын деп беліңіз ауырып кетті. Бөпе ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — үйдің тірегісіз, ал тірек міндетті түрде тынығып, күшін қалпына келтіруі керек.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'Теріс киілген жейденің мақтанышы 👕', 'Ол жейдесін теріс киіп алып, әлемді бағындырғандай мақтанышпен көрсетіп жүр. Жұрт алдына киімін теріс киіп шығатын бала — өз шешімін қорғай алатын бала. Тіпті болмашы араласпаңыз, оның осындай өзіне деген сенімділігіне сүйсініңіз.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'Дүкендегі сынақтар 🛒', 'Кассаға жақындағанда, сауда арбасынан Сіз таңдамаған 3 түрлі шоколад шықты. Ол Сіздің шекараңызды тексеріп жүр. Шұғыл әрекет етіп, сол заттарды орындарына қайтарыңыз. Ал бірдеңені ұмытып кетпеу үшін қолданбадағы Сатып алу тізімін үнемі қарап жүріңіз.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'Себепсіз көз жасы ☀️', '«Күн көзіме қарап тұр» деп өксіп жылады ма? Бұл жерден қисын іздемеңіз. Ол үшін бұл шынымен де үлкен қайғы, өйткені ол әлемді басқара алмайтынына ашуланады. Пердені жауып жатып: «Күнді жасырып қойдым», — деп, оның сезімін қабылдағаныңызды көрсетіңіз.'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'Жалғыздықты аңсау 🚪', 'У-шу миыңызды тесіп жіберердей болып, бәріне айқайлағыңыз келе ме? Оны қауіпсіз жерге қалдырып, дәретханаға кіріңіз де, есікті жабыңыз. Бар болғаны 5 минут қабырғаға қарап, ештеңе істемей отырыңыз. Осы қысқа үзіліс Сізге ана рөліне қайта оралуға күш береді.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'Жалаңаяқ жүру заңы 👣', 'Ол жалаңаяқ жүріп, кілемді, бөлмедегі тастарды немесе салқын кафельді басқаннан ләззат алады. Табандағы жүйке ұштарының белсенді болуы оның тепе-теңдігі мен неврологиялық дамуы үшін өте маңызды. Тоңбаса, шұлықсыз жүруіне еш кедергі жасамаңыз.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'Әкенің оғаш дыбыстары 🤡', 'Сіздің барлық амалдарыңыз әсер етпей қалғанда, әкесінің жануарларға еліктеп шығарған оғаш дыбыстары мен күлкілі қылықтары жағдайды бірден құтқарады. Кешкі дағдарыс кезінде тізгінді бірден оған беріп, өзіңіз шетте тынығып, бақылаңыз.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'Бүгін мен пісіремін 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол міндетті түрде жаныңызға орындық қойып, іске араласа ма? Шын мәнінде, ол көмектескісі келмейді, тек үдерістің дәл ортасында болғысы келеді. Оған кішкентай бір түйір қамыр беріңіз. Асүй астаң-кестең болады, есесіне оның өзіне деген сенімі мен шығармашылығы арта түседі.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'Жаңа сөздерді тіркеу 📈', 'Ол заттарға өзі ойлап тапқан, ешбір тілде жоқ жаңа атаулар береді. Әрі Сізден де сол сөзді қолдануды қасарысып талап етеді! Даму трекерін ашып, болашақта оқып күлу үшін оның осы күлкілі сөздерін міндетті түрде сақтап қойыңыз.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'Қараңғылықпен достасу 🌙', 'Оның тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин қараңғы әрі технологиясыз ортада жылдам бөлініп, ұйқыға кетуді жеңілдетеді.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'Жарықты өшіріп, тыныштықты тыңдаңыз 🤫', 'Ол ақыры ұйықтап қалды. Енді үйдегі ең кішкентай дыбыстың өзі Сізді алаңдатады. Жарықты бәсеңдетіп, теледидарды өшіріңіз де, қараңғылық құшағындағы сол бір сирек тыныштықтың тәтті ләззатына бөленіңіз. Күні бойғы шаршау осылай басылады.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'Себепсіз өкпелеу 😤', 'Сіз жай ғана «Кел, тамақ дайын» дедіңіз, ал ол қолын кеудесіне айқастырып, қабырғаға қарап, Сізге өкпелеп қалды. Бұл жаста эмоциялар қатты шатасып жатады, сондықтан кейде еш себепсіз де өкпелейді. Ештеңе түсіндірмей-ақ қойыңыз, 2 минуттан кейін өзі тамаққа жүгіріп келеді.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: Балалық қорқыныштар 🤖', 'Кенеттен үнемі ойнап жүрген қызыл мәшинесінен қорқа бастады ма? Түсініксіз фобиялар Сізді алаңдатса, интернеттегі үрей туғызатын форумдарды жабыңыз. Anacan AI-дан 3.5 жастағы баланың қиялындағы оғаштықтар туралы ғылыми негізделген әрі көңіліңізді тыныштандыратын жауап алыңыз.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'Сыбырдың гипнозы 🌙', 'Төсекте жатып, аяқтарын жоғары көтереді де, ұйықтағысы мүлде келмейді. Айқайлаудың орнына даусыңызды кенет бәсеңдетіп, онымен тек сыбырлап сөйлесіңіз. Бала Сізді есту үшін бар зейінін салғанда, миы автоматты түрде тынышталып, ұйқы режиміне ауысады.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'Anacan қауымдастығында тынығу 💬', 'Қатты шаршадыңыз және ешкімге ештеңе түсіндіргіңіз келмейді. Anacan қауымдастығына кіріп, ештеңе жазбай, тек оқыңыз. Басқа аналардың да осылай шаршайтынын көру «мен жалғыз емеспін» деген сезім сыйлап, ең жақсы демеуге айналады.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'Сұрақ жауыны — Неге? 🌪️', '«Балықтар неге жүрмейді?», «Күн қайда кетті?» Таң атқаннан-ақ оның миы сағатына 100 сұрақ жылдамдығымен өмірдің мәнін іздейді. Шаршасаңыз да, қысқаша жауап беріңіз. Ол ғаламның құпияларын Сіздің дауыс ырғағыңыз арқылы танып-біледі.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'Ол менікі! — Бәрін меншіктеу 🧸', 'Үйдегі кез келген затты құшақтап алып, «Бұл менікі!» деп айқайлайды да, ешкімге бермейді. Ол меншік шекараларын танып-біліп жүр. Оны өзімшіл деп айыптамаңыз, назарын басқа ойынға аударып, затты қайтарып алыңыз.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'Ананың өз үлесі 🥗', 'Оны тойдыру үшін 3 түрлі мәзір ойластырдыңыз, ал өзіңіз тағы да аш қалдыңыз ба? Тамақтану жоспары бөлімінен балаларға ғана емес, аналарға да арналған, 10 минутта дайындалатын, темір мен кальцийге бай әрі қуат беретін түскі ас таңдап, өзіңізге қамқорлық жасаңыз.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'Екеуіңізге арналған шампан 🥂', 'Қиын күннен кейін стақандарға қарапайым ыстық шай құйыңыз. Жұбайыңызбен диванда бір-біріңізге қарап отырып, «Бүгінгі бейберекет күннен де аман өттік» деп стақандарыңызды соғыстырыңыз. Сіздер — осы үйдің әрі қолбасшылары, әрі біртұтас командасысыздар.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', '«Маған қарашы!» кезеңі 👀', 'Диваннан секіріп, бір қимылды тура 50 рет қайталайды да, әр жолы: «Анашым, маған қарашы!» — дейді. Телефоннан назарыңызды аударыңыз. Ол қимылдың өзі үшін емес, Сіздің көзіңізден мақұлдағаныңызды көру үшін секіреді. Оған бар назарыңызды бөліп, үзіліссіз 5 минут беріңіз.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', 'Дыбыс өлшегіштегі 0 децибел 🤫', 'Ақыры ұйықтап қалды! Үй ішін жайлаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз. Миыңыздың біртіндеп тынығып, осы көзге көрінетін тыныштықтың өзіңізге қалай жайлы әсер етіп жатқанын сезініңіз.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'Еркін би 🎶', 'Естіген алғашқы ырғаққа-ақ, ол жарнаманың әуені болсын, көліктің сигналы болсын, билей бастайды. Өмірге ол сияқты көңілді қараңыз! Бөлмеде оған қосылып, бірнеше минут еркін билеп алыңыз — бүкіл күйзелісіңіз сейіліп кетеді.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'Даму трекері — жетістіктерге мақтаныш 📈', 'Ол енді бөпе емес! Өз шешімдері, тосын сұрақтары және алып жүрегі бар жеке тұлға. Сіз бәрін керемет атқарып жүрсіз!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'Кілемдегі шекара сызықтары 🗺️', 'Ол бөлмеден асүйге тек кілемдегі қызыл сызықтарды басып өту керек деген ереже шығарды. Бұл кезде ірі моторика мен зейін қатар жұмыс істейді. Осы қисынсыз ережені бұзбаңыз, өзіңіз де оған қосылып, сызықтардың үстімен билеп, таңғы жаттығуыңызды жасап алыңыз.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'Жастық астындағы театр 🎪', 'Төсекке жатса да, басын жастықтың астына тығып алып, өзімен-өзі сөйлесіп жатыр. Бөлмені толық қараңғылаңыз. Сол қараңғы әрі қауіпсіз панасында өз оқиғаларын құрастырып, біртіндеп ұйқы әлеміне ене берсін. Араласпаңыз.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'Қалтадағы макарон сынағы 🍝', 'Кір жуғыш машинаға салғалы жатқан шалбардың қалтасынан кеуіп қалған макарон шықты ма? Сіз үшін бұл қоқыс, ал ол үшін «жолда қарным ашса» деп сақтаған азық болуы мүмкін. Оны сөкпеңіз, жоспарлау қабілетінің осы алғашқы нышанын Даму трекеріне күлкілі естелік ретінде жазып қойыңыз.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', '«Суды құрғат!» деген талап 💧', 'Стақандағы суды ішудің орнына: «Бұл тым су екен, құрғатып бер!» — деп айқайлайды. 3.5 жастың қисынсыз әлеміне қош келдіңіз. Түсіндіруге тырысу бар күшіңізді тауысады. «Жақсы, басқа құрғақ су әкелемін», — деп, дәл сол суды түсі басқа стақанға құйып беріңіз.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'Өзі құюға деген қырсықтығы 💧', 'Суды үлкен құманнан кішкентай стақанға міндетті түрде өзі құйғысы келеді. Су үстелге, одан еденге төгіледі. Бірақ оның шүберекті алып, төгілген жерді тазалауға тырысқан кішкентай қолдарына қараңызшы. Ол қателесе жүріп жауапкершілікті үйренеді, ашуланбаңыз.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'Ваннадағы мұхит 🌊', 'Ваннаға түсу енді жай ғана жуыну емес, толқын жасайтын ойынға айналды. Су жан-жаққа шашырай берсін. Судың сол бір сиқырлы әсері күні бойы бойына жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып жібереді.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'Сатып алу тізімі — ұмыт қалғандар 🛒', 'Дүкенге барғанда ең қажетті затты ұмытып кетесіз бе? Сатып алу тізімі қосымшада Сізді күтіп тұр. Қажетті заттарды сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келсін. Ал Сіз миыңызды артық ақпаратпен жүктемеңіз.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'Саябақтағы сәулет өнері 🏰', 'Саябақтағы құм алаңында қазына іздегендей терең шұңқыр қазып жатыр. Үсті-басы батпақ. Бірақ оның жаңалық ашқан осы сәтін бұзбаңыз. Ауа райына сай, былғанса да өкінбейтін киімді алдын ала таңдап қойсаңыз, бұл көріністі еш алаңсыз тамашалай аласыз.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'Жансыз заттармен ерекше достық 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа бар байыппен бірдеңелер айтып, тіпті ұрсып жатады. Символдық ойындар арқылы ол қоршаған әлемді түсініп, қабылдауды үйренеді. Даму трекеріне оның осындай ерекше сценарийлерін міндетті түрде белгілеп қойыңыз.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'Ақылды ертегідегі Мен 🪄', 'Бүгін кешке Ақылды ертегілердегі кейіпкерді балаңыздың атымен атаңыз. Ертегі кейіпкерінің де бөлмесін жинап, содан кейін тыныш ұйықтағанын айтып беріңіз. Осылайша ережелерді айқайлап емес, жанама түрде үйрете аласыз.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'Көңіл күй күнделігі — ішіңізді босатар сәт 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желіде өзгенің өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, балаңыздың бүгінгі ең күлкілі қылығын болашаққа естелік ретінде жазып қойыңыз. Мұндай цифрлық терапия Сізге де демалуға көмектеседі.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'Әкесінің арқасындағы ат жарысы 🐴', 'Ол әлі бар энергиясын шығарып үлгермеді, сондықтан ұйықтағысы келмей қырсығып жүр. Әкесін көмекке шақырыңыз. Әкесі баланы арқасына мінгізіп, ат болып шапқанда, бөлме шат күлкіге толады. Жиналған бүкіл дене ширығуы мен сарқылмайтын энергиясы санаулы секундта термен бірге ғайып болады.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'Әкенің құпия парасы 🤫', 'Тісін тазалағысы келмейді. Әкесі білдіртпей жанына келіп: «Тісіңді тазаласаң, қалтамдағы сиқырлы тасты көрсетемін», — дейді. Кейде аналық қағидаларды әкелердің осындай айлакер, бірақ бірден нәтиже беретін ерекше ойындары үшін бұзуға тура келеді.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'Балконнан қоғамды бақылау 👀', 'Балконға шығып, көшеден өткен әр адамға дауыстап, қол бұлғайды да, жауап болмаса, ренжіп қалады. Қарым-қатынасқа деген қажеттілігі шегіне жеткен. Оны ішке қарай тарта бермеңіз. «Олар тым алыста, бәлкім, естімеген шығар», — деп, жанашырлық сезіміне нұқсан келтірмей қолдау көрсетіңіз.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'Кітапты үнсіз оқу сәті 📖', 'Бүгін кешке ешкім сөйлемейді. Танымдық ертегілерді ашып, мәтінді дауыстап оқудың орнына, құрылғыдан естілетін баяу табиғат дыбыстарының сүйемелдеуімен суреттерді үнсіз тамашалаңыз. Көріп есте сақтау үдерісі оны шаршатып, біртіндеп ұйқыға жетелейді.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'Жұмыртқаның дұрыс емес жағы 🍳', 'Піскен жұмыртқаны ортасынан кесіп қойғаныңыз үшін үлкен жанжал шықты. «Мен бүтінін қаладым!» Тағамның сыртқы көрінісі — олардың ең осал тұсы. Пайдалы рецепттерді қарап, тағамды дұрыс пішінде әрі қызықты етіп кесіп ұсынуды үйреніңіз.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'Табиғаттағы детектив 🔍', 'Саябақта құмырсқалардың илеуін бақылау үшін ғана 20 минут тапжылмай отырды. Асықтырмаңыз. Ауа райы мен киім көмекшісінің кеңесіне сүйеніп, ауа райына сай, табаны қалың аяқ киім кигізген болсаңыз, бұл кішкентай биологқа әлемді зерттеуге мүмкіндік беріңіз.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'Ваннадағы шағын зертхана 🛀', 'Суға түрлі түсті сабындар қосып, сиқырлы сусын дайындап жатыр. Иә, жуынатын бөлме былғанады. Бірақ ол еріткіштер мен заттардың араласуын зерттеп жүр. Бұл ғылыми ізденіс кешкі шаршауын басып, оны тыныш ұйқыға дайындайтын ең жақсы тәсілдердің бірі.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'Киім шкафындағы қоғамнан оқшаулану 🚪', 'Үй ішіндегі шу кенет тыйылды. Сіз оны киім шкафының ішінен, қараңғыда жалғыз ойнап отырған жерінен таптыңыз. Бұл депрессия емес, жай ғана эмоциялық қайта жүктелу сәті. Есікті ақырын жауып, оған оңаша кеңістікте болу мүмкіндігін беріңіз.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'Жанасуға қарсылық 🔋', 'Күні бойы үстіңізге өрмелеп, шашыңызды тартқан баладан физикалық тұрғыда әбден қажыдыңыз. Оны дереу қауіпсіз жерге қалдырып, басқа бөлмеге өтіңіз. Көңіл күй күнделігіне «Денем өзіме тиесілі емес» деп жазып, жанасудан қажу синдромының психологиялық ауыртпалығын жеңілдетіңіз.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'Дыбыс өлшегішпен жан тыныштығы 🤫', 'Ол ақыры ұйықтап қалды. Ал құлағыңыздағы ызың әлі басылар емес. Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 децибел жазуына қарап, бөлмедегі тыныштықтың санаңызға қалай сіңіп, өзіңізді қалай қалпына келтіріп жатқанын сезініңіз.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'Телефон ұрысы 📱', 'Өзіңізге шай құйып жатқанда телефоныңыздың жоғалып кеткенін, ал оның диванның артында Сізге еліктеп Алло деп тұрғанын байқадыңыз. Ол Сіздің цифрлық әдеттеріңізді зерттеп жүр. Құрылғыны аларда Телефоным да сенімен сөйлескісі келіп тұр екен деп, ойынға айналдырып қайтарып алыңыз.'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'Өзің киін! саясаты 👖', 'Аяғын көкке көтеріп, Мен бөпемін, сен киіндір дейді. Балалар дербестік пен тәуелділіктің арасында ауытқып жүреді. Күштеп киіндірмеңіз. Киімді жанына қойып, Бұл суперқаһарман шалбары өз иесін күтіп тұр деп, айламен қызықтырып көріңіз.'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'Сыбырдың тылсым күші 🌙', 'Төсекке жатпау үшін түрлі сылтау ойлап табады. Даусыңызды барынша бәсеңдетіп, тек сыбырлап сөйлеңіз. Сізді түсіну үшін ол бар зейінін жинауға мәжбүр болады, ал мұндай шоғырлану оның миын тыныштандырып, ұйқыға жетелейді.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'Anacan қауымдастығындағы жұбаныш 💬', 'Мен ешқашан мінсіз бола алмаймын деген сезім Сізді қысып жүр ме? Instagram-дағы мінсіз аналар туралы елесті ұмытыңыз. Anacan қауымдастығына кіріп, үйі астан-кестен болған, баласы қабырғаны шимайлаған аналардың шынайы әңгімелерін оқыңыз да, Менің жағдайым қалыпты деп айтыңыз.'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'Динозавр логикасы 🦖', 'Таңертең ешбір сұраққа жауап бермей, тек ақырады. Бүгін ол — T-Rex. Ал T-Rex-тер ботқа жей ме? деп, өзі ойлап тапқан кейіпке бейімделіңіз де, таңғы рәсімді ешбір көз жасынсыз аяқтаңыз.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'Әкенің қиялынан туған қаһармандар 🦸‍♂️', 'Бүгін кешке кітаптағы ертегілерді ұмыта тұрыңыз. Әкесі басты кейіпкері баланың өзі болатын қиял-ғажайып оқиғаны ойдан шығарып айтып берсін. Сөйтіп, ол қылышын суырып алып... тісін тазалады! деген сияқты сөйлемдер баланы күлкіге қарық қылып, ұйқыға дайындайды.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'Өз суретін сынау 🖍️', 'Салған қара шимайын көрсетіп, Бұл сен едің, бірақ жаман шықты дейді де, жыртып тастайды. Оның өзін-өзі сынау қабілеті қалыптасып келеді! Сезімін елемей қоймаңыз. Келесі суретте қызыл түсті де байқап көрерсің? деп, дамуына қолдау көрсетіңіз.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', 'Мұны маркеттен мен таптым 🛒', 'Кассаға жақындағанда арбадан Сіз салмаған бір қаптама печенье шыға келеді. Бөпеңіз оны білдіртпей тауып алған. Сатып алу тізімін ашып, Қарашы, бұл біздің тізімде жоқ, келесі жолы жазып қоямыз деп, ережені цифрлық беделді көмекшіге жүктеңіз.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'Екеуіңізге арналған шай рақаты 🥂', 'Қиын күннен кейін стақандарға кәдімгі ыстық шай құйыңыз. Жұбайыңызбен диванда бір-біріңізге қарап отырып, Бүгін де сол аласапыраннан аман өттік, біз керемет командамыз деп, стақандарыңызды соғыстырыңыздар. Сіздер — отбасының мызғымас тірегісіздер.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'Жасырын көкөністер операциясы 🥦', 'Сорпаның ішінен бір түйір күрішті немесе сәбізді тауып алып, Мен мұны жемеймін дейді. Тамақтану жоспарына кіріңіз. Ақуыздар мен көкөністерді түрлі түсті кекс түрінде ұсынуды үйреніп, осы қыңыр аспаздың айласын асырыңыз.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'Жиһазға өрмелеу олимпиадасы 🧗‍♂️', 'Диванның шетімен терезеге қарай өрмелеп барады. Үй Сіз үшін қауіпке толы, ал ол үшін спортзал іспетті. Абайла, құлап қаласың! деп дүрбелең туғызудың орнына, Қолыңды ана жерге қой деп, оның қимыл-қозғалысқа деген қажеттілігін дұрыс бағыттаңыз.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'Жасанды интеллект және сабыр 🤖', 'Балаңыздың кенеттен тұтыға бастауы немесе ашу ұстамалары Сізді интернеттен қорқынышты ауруларды іздеуге мәжбүр етті ме? Тоқтаңыз! Anacan AI-дан мұның 3 жастағы даму секірісіне байланысты болуы мүмкін бе деп сұрап, педиатрлар мақұлдаған көңілге медеу болатын жауап алыңыз.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'Бөлмедегі дыбыс әсерлері 🪄', 'Ақылды ертегілерді ашыңыз. Оқиғаны оқып отырып, есіктің сықырын, желдің гуілін және сыбдырды салып, бөлмеде дыбыс театрын ұйымдастырыңыз. Бұл ерекше дыбыс толқындары оның назарын бірден ертегі әлеміне, ал одан әрі терең ұйқыға жетелейді.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'Көлеңкеден қашу 👻', 'Көшеде келе жатып, кенет өз көлеңкесінен қорқып, артыңызға тығылды. Бұдан қисын іздемеңіз, 3.5 жастағы баланың қиялы осылай жұмыс істейді. Кел, көлеңкенің үстіне секірейік деп, ол қорыққан нәрсені бірден қимылды ойынға айналдырыңыз.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'Әкенің иыққа жасайтын массажы 💆‍♂️', 'Бүгін көп уақыт тік тұрып, оның артынан жүгіріп, еденнен ойыншық жинағаннан беліңіз үзіліп кетердей болды. Бала ұйықтаған бойда жұбайыңыздан 10 минут иығыңызға массаж жасап беруін сұраңыз. Сіз — үйдің қозғалтқышысыз, ал қозғалтқыш міндетті түрде демалып, қалпына келуі керек.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'Денеңіздің дабылы 🩸', 'Себепсіз ашушаңдық пен шаршауға бой алдырмаңыз. Етеккір күнтізбесіне қараңыз — денеңіз белгі беріп тұр. Өзіңізді кінәлаудың орнына, Пайдалы рецептілер бөліміндегі магнийге бай тіскебасармен демалып алыңыз.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'Таңғы философия 🤔', 'Құстар неге құлап қалмайды?, Ағаш неге жасыл? Таңсәріден ғылыми конференция басталды. Нақты жауап беруден шаршасаңыз, Сеніңше, неге? деп сұрақты өзіне қайтарыңыз да, оның таңғажайып қиялынан туған жауаптарын тыңдаңыз.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'Ұйқы таймері туралы келісім ⏱️', 'Ұйықтайтын уақыт келгенде кенет шөлдейді, дәретханаға барғысы келеді немесе қабырғамен қоштаса бастайды. Таймер орнатыңыз. Қоңырау соғылғанда бәрі жарықты өшіреді деген ережені қолданып, осы бітпейтін қоштасу мен шебер айладан сабырмен құтылыңыз.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'Дүкендегі Аламын дағдарысы 🛒', 'Касса алдында тәтті сұрап айқайлай ма? Айналадағылардың жаман бала дегендей қарағанына мүлде мән бермеңіз. Сабырмен көзіне қарап, ережені түсіндіріңіз және шешіміңізден таймаңыз. Тізіміңізде жоқ болса, сатып алынбайды.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'Сен кімсің? ойыны 🎭', 'Сізге өте байсалды кейіппен қарап, Сен кімсің? Менің анам қайда? дейді. Ол Сізбен рөлдік ойын ойнап жүр! Мен көрші апаймын, анаң қазір келеді деп, дауыс ырғағыңызды өзгертіп, осы тамаша қойылымды жалғастырыңыз.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'Кенеттен айтылған Сені жақсы көремін 💖', 'Бөлменің ортасында ойнап жүріп, кенет Сізге қарайды да, жүгіріп келіп мойныңыздан құшақтайды. Барлық ұйқысыз түндер мен шаршауға татитын сәт! Осы сәт сыйлаған терең әрі қайталанбас тыныштықтан ләззат алыңыз — бүкіл бейберекетті бірден ұмытып кетесіз.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'Қоқыс емес, өнер 🎨', 'Ол бөлменің ортасына ұсақ қағаз қиындылары мен кесілген жіптерден үлкен өнер туындысын жасап, оны тастауға рұқсат бермей отыр. Тазалыққа деген шектен тыс құмарлықты қоя тұрыңыз. Ол жасаған бейберекетті құрметтеңіз, жинауды ертеңге де қалдыруға болады.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'Тыныштық рақаты 🤫', 'Ол ақыры ұйықтап қалды! Үйді жайлаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз да, миыңыздың біртіндеп тынығып, осы көзге көрінетін тыныштықтың Сізді қалай әлдилеп жатқанын сезініңіз.'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', '«Сен жаман анасың!» деді ме? 💔', 'Қалаған көлігін алып бермегеніңіз үшін ол осылай деді. Жүрегіңіз ауырып кетті. Бірақ оның әлі де сезімдерін дұрыс жеткізе алмайтынын біліңіз: шын мәнінде ол «Менің көңілім қалды» дегісі келеді. Оны жай ғана құшақтап, сезімін қабылдаңыз.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'Сән туралы түсінігі 👗', 'Қыстық шұлықтың үстінен жазғы сандал киіп, саябаққа барғысы келеді. Қайта-қайта талап етіп, шешпей қояды. Қоғамның қалыптасқан қағидаларын ұмытыңыз. Шығармашылығын шектемеу үшін сол күнді өзгеше, күлкілі кейіпте өткізуіне рұқсат етіңіз — осылайша ол еркін болуды үйренеді.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'Айнадағы қарсылас 🪞', 'Айна алдында тұрып, өзіне-өзі қабағын түйеді, ашулы әрі оғаш қимылдар жасайды. Ол эмоциялардың жүзінде қалай көрінетінін зерттеп жүр. Сырттай дыбыс шығармай, осы кішкентай театр әртісінің жаттығуын сүйсіне тамашалаңыз.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'Ананың оңаша қалатын сәті 🚪', 'У-шу басыңызды тесіп бара жатқандай, бәріне айқайлағыңыз келеді. Оны қауіпсіз жерге қалдырып, дәретханаға кіріп, есікті жабыңыз. Көңіл күй күнделігін ашыңыз. Бойыңыздағы бүкіл қажуды еркін түрде жазып шығыңыз. Бұл қысқа терапия өзіңізді қайта қалпына келтіруге көмектеседі.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'Қараңғылықпен достасу 🐰', 'Қараңғыдан қорқатынын сылтауратып, төсегінен қашады. Бөлмедегі барлық жарықты өшіріп, қолшамды жағыңыз да, қабырғаға қолыңызбен құс пен иттің көлеңкесін түсіріңіз. Ол қорқатын қараңғылық санаулы секундта театрға айналады.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'Ауа райын барлау тәсілі ⛅', 'Далада күн ашық, бірақ жел соғып тұр. Терезеден қарап алданып қалмаңыз. Ауа райы мен киім құралы Сізге сезілетін температураны және киімдерді қалай дұрыс қабаттап кию керегін бірден көрсетсін. Есік алдында не киеріңізді шеше алмай уақыт жоғалтпай, денсаулыққа қауіпсіз серуенге шығыңыз.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'Бұл менің кінәм емес! 🤷‍♂️', 'Суды әдейі еденге төкті де, кінәні ойыншығына аударып: «Ол итерді», — деді. Бұл өтірік емес, бала миының қорғаныс механизмі. Қырсықпаңыз, оның орнына: «Кел, ойыншыққа да қалай тазалау керегін үйретейік», — деп, назарын басқаға бұрыңыз.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'Ваннадағы мұхит дауылы 🌊', 'Ваннада шомылу енді тазалану емес, шағын цунами жасау ойынына айналды. Су жан-жаққа шашыла берсін. Судың тылсым әрі бойдағы энергияны өзіне сіңіретін әсері күні бойы жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып әкетеді.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'Аяқталмаған сөйлемдерді толықтырыңыз 🗣️', 'Бір сөзді ұмытып қалса, қолымен ымдап, қабағын түйіп, Сіздің тауып айтуыңызды күтеді. Сөздік қоры көбейіп келеді, тек миы тілінен жылдамырақ жұмыс істейді. Оның сөйлемін асықпай толықтырған кезде жүзінен «иә, дәл осыны айтқым келген» деген жеңілдікті байқаңыз.'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'Әкенің арқасындағы ойын 🐴', 'Ол бар энергиясын шығара алмай, ұйықтауға қарсылық танытып жүр. Әкесін көмекке шақырыңыз. Әкесі баланы арқасына мінгізіп, ат болып шапқанда, бөлме күлкіге толады да, жиналған физикалық ширығу мен сарқылмас энергия бірнеше секунд ішінде термен бірге жоғалады.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'Ананың энергия батончигі 🥑', 'Оны тамақтандыру үшін мәзірді 4 түрлі етіп дайындадыңыз, ал өзіңіз не жедіңіз? Пайдалы рецептілердің ішінен 5 минутта дайын болатын, кальцийге бай арнайы тіскебасар таңдап, түрегеп тұрсаңыз да рақаттанып жеп алыңыз. Сіз — осы үйдің қозғалтқышысыз, сондықтан қуат жинауыңыз керек.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'Мысық болып ояну 🐾', 'Бүгін таңертең ол адам емес. Төрт аяқтап жүр, аяғыңызға үйкеліп, тек «мияу» деп сөйлеседі. Бұл — бала қиялының ең сүйкімді шағы. Ереже орнатудың орнына, Сіз де оған қиялдағы сүт құйылған ыдысты ұсынып, осы ойыннан ләззат алыңыз.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'Музыкалық гипноз 🎶', 'Кешкісін себепсіз мазасызданып, жылау ұстамалары басталды ма? Теледидарды өшіріп, жарықты бәсеңдетіңіз де, бөлмеге өте баяу классикалық музыка қосыңыз. Музыканың терең әуені көңіл күйді сиқырлы түрде өзгертіп, бөлмеге тыныштық сыйлайды.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'Бөліскісі келмейтін таңғы ас 🍳', 'Өз тәрелкесіндегі тамақты Сізге мүлде бермейді, бірақ Сіздің тәрелкеңіздегі жұмыртқадан жегісі келіп, қасыңыздан шықпайды. Балалар ата-анасының таңдауына әрдайым толық сенеді. Қарсыласпай-ақ, бір үзіміңізді оған сүйіспеншілікпен беріп, жымиыңыз.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'Жансыз заттармен сөйлесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа барынша байыппен бірдеңе айтып, тіпті ұрсып тұрады. Символдық ойындар арқылы ол қоршаған ортаны түсініп, ой елегінен өткізеді. Даму трекеріне оның осындай ерекше сценарийлерін міндетті түрде белгілеп қойыңыз — бұл жоғары шығармашылық қабілеттің белгісі!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'Көңіл күй күнделігіндегі сыр 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желідегі басқалардың мінсіз өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгін жасаған ең күлкілі, Сізді ерекше күлдірген сәтін болашаққа естелік ретінде жазып қойыңыз. Онда ойыңызды жазу — ең таза терапия.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', 'Сен ән айтпа! деген тыйым 🛑', 'Фонда ойнап тұрған балалар әніне ыңылдап қосылып едіңіз, ол бірден: «Сен ән айтпа!» — деп айқайлады. Бөлмедегі жалғыз әнші — өзі, ал Сіздің ән айтуға талпынысыңыз оның сахнасын тарылтып тұр. Ренжімеңіз, сахнаны осы кішкентай өзімшілге бере тұрыңыз.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'Ақылды ертегідегі Мен 🪄', 'Бүгін кешке Ақылды ертегілердегі басты кейіпкерге балаңыздың атын беріңіз. Ертегідегі кейіпкер де бөлмесін жинап, содан кейін тыныш ұйықтағанын айтып, ережелерді айқаймен емес, жанама түрде үйретіңіз.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'Күн тәртібі бұзылып жүр ме? ⏱️', 'Кешке ұйықтау тым ұзаққа созыла ма? Ұйқы таймерінің кестесін қараңыз. Бәлкім, күндізгі ұйқыны толығымен тоқтатып, кешкі ұйқыны ертерек бастайтын уақыт келген шығар.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'Мультфильм сыншысы 📺', 'Көрген мультфильмін өзінше сөйлеп, кімнің қайда барғанын байыппен түсіндіріп бере ме? Оны мұқият әрі таңғалғандай болып тыңдаңыз. Қиялына қанат бітсін, өзін әлемдегі ең ақылды баладай сезінсін.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'Қауымдастықтың үнсіз қолдауы 💬', 'Қатты шаршадыңыз, ешкімге ештеңе түсіндіргіңіз де, ішіңіздегіні айтқыңыз да келмейді. Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың дәл осындай қисынсыз қыңырлық ұстамаларын қалай еңсеріп жүргенін көру — ең күшті үнсіз жұбаныш.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'Төсектен қашу 🏃‍♂️', 'Су бер, ойыншығымды тауып бер... Ұйықтамау үшін 3 жастағы баланың сылтауы таусылмайды. Ұйқы таймерін қосып, шекараны нық сақтаңыз және Ақ шумен бөлмені тыныштандырыңыз.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'Қисса құрастыратын кішкентай 🗣️', 'Сөздерді біріктіріп, қиялынан оқиғалар мен фантастикалық сценарийлер құрастырып жүр ме? Тілінің осындай керемет қарқынмен дамыған сәтін өткізіп алмай, дауысын бірден жазып алып, Бөпе альбомында мәңгілікке сақтаңыз.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'Кальций қалқаны 🦴', 'Қарқынды өсіп жатқан сүйектерге кальций қажет. Сүт ішпей ме? Тамақтануды бақылау құралы арқылы бүгін жеген ірімшік, йогурт немесе брокколи мөлшерін міндетті түрде есептеңіз.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', '«Менікі!» кезеңі 🧸', 'Ойыншығын ешкімге бермей ме? Бұл өзімшілдік емес, баланың дамуындағы қалыпты құбылыс. Бөлісуді талап етпей, кезекпен ойнауды үйрету жолдарын Блогтардан оқып, қолданып көріңіз.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'Таңғы төңкеріс 🛑', 'Кеше сүйіп жеген тамағын бүгін үзілді-кесілді қабылдамай ма? Бұл тәбеттің жоғалуы емес, жай ғана жағдайды бақылауға деген талпыныс. Қиын сәттерде сабыр сақтаудың жолын Anacan AI-мен ақылдасып, терең тыныс алыңыз және дастарқан басында ешқашан тартыспаңыз.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'Әкенің кезегі 👨‍👧', 'Ана болу — тәулік бойы жалғасатын кезекшілік емес. Серігіңізді іске қосыңыз! Бүгін бөпенің сарқылмас энергиясын әкесі саябақта шығарсын, ал Сіз үйде мүлгіген тыныштықтан ләззат алыңыз.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'Анаға арналған үзіліс ☕', 'Баламен үздіксіз сөйлесіп, сұрақтарына жауап беру шаршатады. Анаға жайлы орындардан балалар бұрышы бар кафе тауып, ыстық кофеңізді ішіңіз, басқа аналармен сырласып, аздап тынығып алыңыз.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'Ертегі оқитын әкенің кезегі 📚', 'Бүгін кешкі ұйқы рәсімі толығымен әкенің мойнында. Ертегіні әкесі оқысын, ал Сіз есіктің ар жағында мүлгіген тыныштықтан ләззат алыңыз.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'Өзім істеймін! 🛑', 'Барлық іске араласып, киіну уақытын 3 есе ұзарта ма? Шашылған заттарға емес, артып келе жатқан өзіне деген сеніміне назар аударыңыз. Шыдамыңыз таусылғанда, қиын сәттерді ойын арқылы шешу жолдарын Блогтардан оқып, терең тыныс алыңыз.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтады. Үй шаруасын ұмытыңыз, бәрі күте алады. Пайдалы рецепттерден ерекше сусын дайындап, өзіңізбен оңаша қалудың рақатын сезініңіз.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'Таңғы жасырынбақ 🙈', 'Сіз жұмысқа немесе балабақшаға кешігіп барасыз, ал ол перденің артына тығылып: «Мені тап!» — дейді. Жүйкеңіз жұқарса да, айқайлау бәрін одан әрі созады. «Менің сүйкімді балам қайда екен?» — деп, ойынға 2 минутқа қосылыңыз да, оны тауып алып, әрі қарай жиналыңыз.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'Тамақты түсіне қарай бөлу 🍅', 'Бөпеңіз тәрелкедегі тағамдарды түсі мен пішініне қарай бөліп, жасылдарын шетке ысырады. Тамақтану жоспарына кіріңіз. Көкөністерді байқалмайтын етіп езіп, дәмді тұздықтарға жасыру жолдарын біліп, бұл ойында білдіртпей жеңіске жетіңіз.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'Тыныштыққа деген қажеттілік 🤫', 'Ақыры ұйықтап қалды! Үйде орнаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз: миыңыздың біртіндеп тынығып, осы көзге көрінетін тыныштықтың Сізді қалай босаңсытып жатқанын сезініңіз.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'Қалтадан шыққан қазыналар 🪨', 'Шалбарын жумақ болғанда, қалтасынан 2 тас, бір кепкен жапырақ пен жарты таяқша шықты ма? Сіз үшін қоқыс саналатын бұл заттар — оның әлемді зерттеу кезінде жинаған құнды топтамасы. Оларды тастамай, кішкентай қазына қорабына жинаңыз.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'Есікті құлыптау миссиясы 🚪', 'Үйдегі барлық бөлменің есігін ішінен жауып, Сізді сыртта қалдырғанды ерекше ұнатады. Оның жеке кеңістік туралы түсінігі жаңа деңгейге көтерілуде. Саусақтары қысылып қалмауы үшін қауіпсіздік шараларын жасаңыз, бірақ өз аумағын белгілеу ойынына қатты кедергі келтірмеңіз.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'Дәретхана қағазынан өнер жасау 🧻', 'Бірнеше минуттық тыныштық... Бөлмеге кірсеңіз, дәретхана қағазы түгел тарқатылып, үйге жайылып жатыр! Ашуланудың орнына қағаздарды жинап, бірге аққала немесе доп жасаңыз. Бейберекетті айқаймен емес, шығармашылықпен жеңіңіз.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'Кір жуғыш машинаны зерттеу 🧺', 'Кір жуғыш машинаның алдында отырып, айналып жатқан киімдерге мультфильм көргендей қадала қарап отыр. Бұл — мүлде тегін әрі сананы тыныштандыратын ермек. Оған кедергі жасамаңыз, өзіңіз де мүмкіндікті пайдаланып демалып алыңыз: бейберекет тіршілік аз уақытқа үзіліс алды.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'Құлағына сыбырланған махаббат сөздері 💖', 'Күні бойы Сізді әбден шаршатып, бәріне қырсықты. Ал қазір төсекте сондай бейкүнә болып ұйықтап жатыр... Жанына жатып, оны қаншалықты жақсы көретініңізді және бүгін жасаған жақсы істерін құлағына сыбырлап айтыңыз. Балалар ұйықтап жатса да, анасының махаббатқа толы дауысын сезеді.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', '«Сен мені тыңдамайсың!» деген соққы 😠', 'Сіз телефонға қарап немесе тамақ араластырып тұрғанда, жаныңызға келіп, жүзіңізді өзіне бұрады: «Маған қара!» Оның айтқаны дұрыс. Оған Сіздің қасында болғаныңыз ғана емес, бар назарыңыз қажет. Ісіңізді тоқтатып, небәрі 3 минут бойы көзіне қарап, бар зейініңізбен тыңдаңыз.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'Ертегіден қашу әрекеттері 🏃‍♂️', 'Ертегі оқып отырғанда, сылтау табылған сайын төсектен атып тұрып, ойыншығын әкелуге жүгіре жөнеледі. Ұйқыға берілгісі келмейді. Даусыңызды кенеттен қатты бәсеңдетіп, сыбырлап оқи бастаңыз. Сізді есту үшін ол амалсыз төсегіне қайта оралып, мұқият тыңдайтын болады.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'Ауа райы және қабаттап киіндіру тәсілі ⛅', 'Көктем жақындаған сайын ауа райы құбылмалы болады: таңертең салқын, түсте жылы. Ауа райы мен киім құралы Сізге баланы пияз қағидасымен, яғни бірнеше қабат етіп киіндіруді еске салады. Саябақта күн жылынған сайын бір қабатын шешіп, оның терлеуіне де, өзіңіздің алаңдауыңызға да жол бермеңіз.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'Жасанды интеллект және кенеттен қырсығу 🤖', 'Кеше ғана сабырлы болған бала бүгін бәріне ашумен жауап бере ме? Интернеттен қорқынышты себептер іздемеңіз. Anacan AI-дан осы даму секірісінің (mental leap) психологиялық себептерін сұрап, педиатр мақұлдаған жауап арқылы уайымыңызды басыңыз.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'Ұрланған мұрын ойыны 👃', 'Мұрныңды алып қойдым! деп бас бармағыңызды көрсеткенде, ол бұған шынымен сеніп, жылай бастайды! 3.5 жаста баланың қиялы кейде шындық пен елесті ажырата алмайды. Бірден Ә, міне, орнына қойдым деп, мұрнынан сүйіп, осы кішкентай қорқынышты күлкіге айналдырыңыз.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'Жұбайыңызбен үнсіз көз түйістіру 🥂', 'Бала ақыры ұйықтады. Сіз бен жұбайыңыз диванда қатар отырсыздар, тіпті сөйлесуге де шамаларыңыз жоқ. Тек үнсіз бір-біріңізге қарап, жымиып қоясыздар. Бұл үнсіз көзқарас біз осы қарбаласты керемет еңсеріп жүрміз деудің ең әдемі жолы.'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', 'Мұны мен таптым - Меншіктегіш бүлдіршін 🔑', 'Үйдегі теледидар пультін немесе әкесінің кілтін еденнен көтеріп алып, Мұны мен таптым, енді менікі! деп иемденеді. Ол үшін тауып алу иелік ету дегенді білдіреді. Қолынан күштеп алмаңыз, Мен үшін тауып бергеніңе рақмет деп, назарын басқа ойыншыққа аударыңыз да, затты қайтарып алыңыз.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'Асүйдегі концерт 🥄', 'Кәстрөлдер мен ағаш қасықтарды шығарып алып, асүйдің ортасында концерт қояды. Басыңыз ауырса да, бұл оның ырғақ сезімі мен шығармашылығының дамуына ықпал етеді. Бірден араласпай, бірнеше минут бойы сол тентек энергияның дыбыс толқындарымен бөлмеге таралуына мүмкіндік беріңіз.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'Жуынатын бөлмедегі шағын спа 🛀', 'Бүгін кешке ваннаны тек оған емес, өзіңізге де дайындаңыз. Бала ұйықтағаннан кейін жылы су, аздап көбік және жуынатын бөлмеде жанып тұрған жалғыз шам. Есікті құлыптап, бар болғаны 15 минутқа ана рөлінен шығып, қайтадан өзіңіз болыңыз, Сіз бұған лайықсыз.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'Табиғатқа міндетті түрде шығыңыз ⛅', 'Төрт қабырғада жиналған энергиясы агрессияға айналып, әр сөйлемі «жоқ» деп басталады. Ауа райы мен киімге қарамастан, лайықты киіндіріп, оны міндетті түрде далаға алып шығыңыз. Жермен жанасу оның жүйке жүйесін бірден тыныштандырады.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'Бұл менікі! — Бәрін иемдену 🧸', 'Үйдегі кез келген затты құшақтап алып, «Бұл менікі!» деп айқайлайды және ешкімге бермейді. Ол жеке меншік шекараларын танып-біліп жүр. Оны өзімшіл деп айыптамаңыз, назарын басқа ойынға аударып, затты қайтарып алыңыз.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'Қоқыс емес, өнер 🎨', 'Бөлменің ортасында ұсақ қағаз қиындылары мен кесілген жіптерден үлкен өнер туындысын жасап, оны тастауға рұқсат бермейді. Мінсіз тазалыққа деген әуестікті бір сәтке қоя тұрыңыз. Ол жасаған шығармашылық ретсіздікке құрметпен қараңыз, үй жинауды ертеңге де қалдыруға болады.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'Әкенің арқасында атқа міну 🐴', 'Энергиясын толық шығара алмай, төсекке баруға қарсылық танытады. Әкесін көмекке шақырыңыз. Әкесі баланы арқасына мінгізіп, ат болып шапқанда, бөлме күлкіге толады, ал жиналған бүкіл физикалық ширығу мен сарқылмас энергия бірнеше секундта термен бірге жоғалады.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'Ертегілер әлемі 🪄', 'Классикалық ертегілерді бір шетке қоя тұрыңыз. Ақылды ертегілерді қосыңыз. Арнайы ертегі құрастырыңыз.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'Қауымдастықтың қолдауы 💬', 'Сіз қатты шаршадыңыз және ешкімге ештеңе түсіндіргіңіз де, ішіңіздегіні айтқыңыз да келмейді. Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың дәл осындай қисынсыз дағдарыстарды қалай еңсеріп жүргенін көру — үнсіз жұбаныштың ең әсерлі түрі.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'Таңғы диктатор іске кірісті 👑', '«Ол жерге сен отырма, қонжығым отырады!» Таңғы ас кезінде бүкіл үстелге өзі басшылық етеді. Оның ерік-жігерін күрт баспай, «Жақсы, қонжығың сол жерде отырсын, ал мен мұнда отырайын» деп, тепе-теңдік пен бөлмедегі тыныштықты сақтаңыз.'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'Күндізгі ұйқыға қарсылық 🥱', 'Төсекке барғысы келмей, жылай ма? Мәжбүрлемеңіз. Бөлмедегі жарықты бәсеңдетіп, «Кітапты үнсіз парақтау сағатын» жариялаңыз. Екеуіңізге де демалуға көмектесетін жаңа әдет қалыптастырыңыз, сонда Сіз де, ол да әрқайсыңыз өзіңізге ыңғайлы түрде тынығасыз.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'Көңіл күй күнделігіндегі сыр', 'Телефоныңызды қолға алыңыз. Әлеуметтік желіде басқалардың өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгінгі ең күлкілі қылығын болашаққа естелік ретінде жазып қойыңыз. Мұндай цифрлық терапия Сізді де тыныштандырады — экранға қарап отырып, уайымдарыңыздың қалай сейілетінін байқаңыз.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'Әнді кері қайтар! 🎶', 'Радиода ойнап біткен әнді қайта қосуды сұрайды. Сіз оның тікелей эфир болғанын және әннің аяқталғанын түсіндіресіз. Бірақ ол «Кері қайтар!» деп жылайды. Баланың миы тікелей эфирдің қалай жұмыс істейтінін әлі түсінбейді. Назарын басқаға аудару үшін әнді өзіңіз өзгеше, күлкілі дауыспен айтып көріңіз.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'Тыныштықтағы шай ☕', 'Бөлменің ортасында ойыншықтарын қатарға тізіп, өз бетімен ойнап отыр. Осы сәтті үй жинауға жұмсай көрмеңіз! Диванға жайғасып, кофе не шайыңызды суытпай ішіңіз де, 10 минут бойы ештеңе ойламай, тыныштықтан ләззат алыңыз.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'Ұйқы таймерінің тәсілі ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен шөлдеп, дәретханаға барғысы келе ме немесе қабырғамен қоштаса бастай ма? Таймер орнатыңыз. «Қоңырау соғылғанда, бәрі ұйықтайды» деген ережені енгізіп, осы бітпейтін қоштасу мен шебер айладан еш даусыз құтылыңыз.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Anacan қауымдастығының күші 💬', '«Менің балам неге сонша қырсық?» деген ой мазаңызды ала ма? Anacan қауымдастығына кіріңіз. Басқа аналардың үйлерінде де болатын осындай қисынсыз дағдарыстар туралы оқығанда, жалғыз емес екеніңізді және бәрі қалыпты екенін түсінесіз.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'Нағыз суретші қабырғаны таңдайды 🖍️', 'Бірнеше секундтық тыныштықтың соңы тосын жағдайға ұласты. Бөлмеге кірсеңіз, ол қабырғаға фломастермен өнер туындысын салып қойыпты. Терең тыныс алыңыз. Оның ұсақ моторикасы дамып жатыр, ал қабырғаны бәрібір тазалауға болады. Болашақта бірге күлу үшін бұл жауһарды міндетті түрде суретке түсіріп алыңыз.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'Қараңғылыққа шақыру 🌙', 'Жатын бөлмедегі жарық сөнгенде мазасыздана ма? Бөлменің бір бұрышына жылы түсті (қызғылт сары немесе қызыл) кішкентай түнгі шам қойыңыз. Ал бөлменің қалған бөлігі мелатонин бөлінуі және терең ұйқы үшін толық қараңғы болуы керек.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'Шаштараз болуға талпыныс ✂️', 'Бөлмеге кіргенде, оның қолына қайшы ұстап, қуыршағының шашын қиюға тырысып жатқанын көресіз. Мұндай сәт — әр ананың қорқынышты түсі. Ашуланбай, қайшыны қолынан алыңыз да, шаштараз болуға жасаған бұл талпынысын Бөпе фотосессиясында күлкілі естелік ретінде сақтап қойыңыз.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'Әкесімен диванда күресу 🤼‍♂️', 'Төсекке жатпау үшін қашып, тығылып қалды ма? Кезекті әкесіне беріңіз. Екеуі диванда өтірік күресе тұрсын. Сол шулы, терлететін әкелі-балалы ойын бөпеңіздің бойындағы соңғы тентек энергияны да сарқып, оны ұйқыға жеңдіреді.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'Интернеттегі аналардан шаршадыңыз ба? 📵', 'Instagram-ды ашқан сайын жұрттың мінсіз балаларын көріп, еңсеңіз түспесін! Қолданбаны жауып, Anacan қауымдастығына кіріңіз. Басқалардың да үйі Сіздікіндей астан-кестен, балалары у-шу екенін көріп, терең тыныстаңыз — Сіз жалғыз емессіз!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'Мұны мен пісіремін! 🍳', 'Жұмыртқаны міндетті түрде өзі жарғысы келіп, ыдыстағының жартысын үстелге төгіп алды ма? Мақтаныштан бал-бұл жанған кішкентай аспаздың түріне сүйсіне қараңыз. Асүй бәрібір жуылады, ал оның қалыптасып келе жатқан өзіне деген сенімі мен дербестігіне кедергі жасамаңыз.'),
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c', 'Макаронның құпия қоры 🍝', 'Шалбарын жуып жатқанда қалтасынан кеуіп қалған макарон шықты ма? Бұл қомағайлық емес, балалық жоспарлау. Оны байсалды кейіппен қоқысқа тастаңыз, бірақ іштей осы кішкентай зерттеуші әрі қамданғыш балаға күлімсіреңіз. Өсіп келеді!'),
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc', 'Экрандағы тыныштық көрсеткіші 🤫', 'Ақыры ұйықтады. Үйдің іші құлағыңыз шыңылдайтындай жым-жырт болып қалды ма? Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 desibel деген жазуға қарау — шаршаған, шудан қажыған миыңызға жасалатын әлемдегі ең жақсы визуалды массаж.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'Көйлектің жапсырмасы батады! 🏷️', 'Артындағы кішкентай жапсырма инедей батып тұрғандықтан, киімін кимей қойды ма? 3.5 жастағы баланың сенсорлық сезімталдығы адамды әбден шаршатады. Мүлде дауласпай-ақ, қайшыны алып, жапсырманы түбінен қиып тастаңыз да, осы шағын дағдарысты әп-сәтте тоқтатыңыз.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'Ол тас менікі еді! 🪨', 'Саябақтан әкелген кір тасын лақтырып жібергеніңіз үшін өксіп жылап жатыр ма? Сөйтсе, ол ең жақын досы болған екен. Дереу басқа бір жылтыраған зат тауып, «Қарашы, тас саған мұны естелікке жіберіпті» деп, ойдан шығарылған оқиғамен жағдайды шебер құтқарыңыз.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'Менің ертегім, менің ережем 📖', 'Ертегі оқып отырып бір сөзді қате айтқаныңызда, ол Сізді бірден түзетті ме? Демек, жаттап алған! Кітапты жауып, «Онда бүгін кешке сен маған оқып бер» деңіз. Оның қиялы жұмыс істесін, ал Сіз жай ғана жатып, дауысын тыңдаңыз.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'Сценарийді өзі жазсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар, ал бөлменің іші көңілсіз болып кетті. Ақылды ертегілерді ашып, бүгін кешке сюжетті оның басқаруына беріңіз. «Енді мына ұшатын көлік қайда барсын?» деп сұраңыз да, қиялында талай жерді бағындырып, ұйықтап қалсын.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'Айнадағы қарсылас 🪞', 'Айна алдында тұрып, өзіне-өзі қабағын түйіп, ашулы әрі оғаш қимылдар жасап жүр ме? Ол эмоциялардың бет әлпетінде қалай көрінетінін тексеріп жатыр. Сырттай дыбыс шығармай, осы кішкентай театр әртісінің дайындығын сүйсіне тамашалаңыз.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'Қабырғамен сыбырласу 🤫', 'Төсекке жатып, бетін қабырғаға бұрып алып, біреумен сыбырлап сырласып жатыр ма? Неткен сүйкімді! Жарықты өшіріп, сол сыбырлардың біртіндеп ұйқыға ұласқанын тыңдап, демалыңыз.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'Дұрыс емес стақан үшін айқас па? 🥤', 'Суды сары стақанға құйып бергеніңіз үшін бөлмеде айқай-шу басталды ма? Оған қатты мән бермеңіз, ол бүгін таңертең шекараларын тексеріп жүр. Суды дереу көк стақанға құйып, бөлмеде тыныштық орнатыңыз да, күшіңізді күннің қалған бөлігіне сақтаңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5'::uuid, 'Шаңсорғышпен жауласу 🌪️', 'Үй жинап жүргеніңізде «Менің шаңдарымды сорып алма!» деп жылап, жолыңызды бөгей ме? Меншіктеу сезімі шектен шығып барады. Шаңсорғышты өшіріп, 5 минут бойы шаңдармен қоштасу рәсімін өткізіңіз. Сеніңіз, бұл бейберекеттікті осылай тезірек тоқтатасыз.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'Киімдер тағы да үйлеспеді 🧥', 'Далаға шыққалы жатырсыздар, бірақ ол резеңке етік пен қысқа жеңді киім кигісі келе ме? Дауласпаңыз. «Ауа райы және киім» бөлімін ашып, телефонның бұған рұқсат бермейтінін көрсетіңіз. Ережені цифрлық экранға жүктеп, өзіңіз шетке шығыңыз — ол жейдесін тыныш қана киіп алады.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'Бір кесе шай туралы арман ☕', 'Қатты шаршағаныңыз сонша, ол ойнап отырған кезде асүйге білдіртпей қашып кіріп, есікті жауып алдыңыз ба? Сіздікі дұрыс. Көңіл күй күнделігін ашып, екі-ақ ауыз сөз жазыңыз: «Бүгін аман қалдым». Кейде анаға сол 5 минуттық үзіліс қана қажет.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'Бұлтты ұстап қал, кетпесін! ☁️', 'Терезеден қарап, бұлттың алыстап бара жатқанына жылап тұр ма? Желді ғылыми тұрғыда түсіндіруге уақыт жоғалтпаңыз. «Ол қазір басқа балаларға сәлем беруге кетті» деңіз. Оның осы бір ерекше пайымын әзілмен және шағын қиял-ғажайып оқиғалармен толықтырып, күнді құтқарып қалыңыз.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'Сорпа детективі іске кірісті 🥕', 'Қасығын сорпаға салып, ішінен жалғыз пиязды тауып алып, шетке қойды ма? Зергердей дәлдік! Дереу Пайдалы рецептерді қарап шығыңыз: ертеңнен бастап көкөністерді блендерден өткізіп, тұздықтарға жасыруды үйреніп, білдіртпей жеңіске жетіңіз.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'Жұп болып үнсіз отыру 🥂', 'Бала ұйықтады, үй жиналды. Жұбайыңызбен диванға қатар жайғасыңыз да, тіпті теледидарды қоспаңыз. Бір-біріңізге Біз мұны да еңсердік, аман қалдық деген көзқараспен қараңыздар. Сеніңіз, ата-ана болудың ең романтикалық әрі шынайы сәті — дәл осы.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'Неге менімен сөйлестіңіз? 😤', 'Тек Қайырлы таң дегеніңіз үшін ашуланды ма? Себепсіз өкпелеу кезеңі қызу жүріп жатыр. Қазбалай бермей, шайыңызды құйып ішіңіз. Сеніңіз, 2 минуттан кейін өзі келіп, тізеңізді құшақтайды. Оның сезімдері әбден шатасып жатыр!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'Төрт аяқтап жүрген бала 🐾', 'Бүгін таңертең ол төсектен бала сияқты емес, күшікше еңбектеп түсті ме? Ереже айтып, ашуланбаңыз. Менің ақылды Бобиім, жарайсың деп, таңғы асын беріңіз. Рөлдік ойынға қосылу қырсықтасқаннан әлдеқайда аз күш жұмсатады.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'Түн ортасындағы кенет айқай 😭', 'Түнде көзі жұмулы күйде жылап оянып, Сізді естімей жатыр ма? Жылауын бағамдап көріңіз: бұл — түнгі қорқыныш ұстамасы. Оятуға тырыспаңыз, тек жанында болып, қолынан ұстап, сипаңыз. Ол өздігінен тынышталып, қайтадан терең ұйқыға кетеді.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'Денем өзіме тиесілі емес 🔋', 'Күні бойы аяғыңызға жармасып, құшаққа сұрана ма? Сіз физикалық тұрғыдан әбден қажыдыңыз. Жанасудан шаршауды (touched out) сезініп жүрсіз. Оны ойыншықтарымен бөлмеде қалдырып, 5 минутқа жуынатын бөлмеге кіріп кетіңіз де, жалғыздықтың тыныштығын сезініңіз. Бұған Сіздің толық құқығыңыз бар.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'Есікті мен ашамын! 🚪', 'Үйден шығарда есікті Сіз ашып қойғаныңыз үшін жылап, оны қайта жапқызды ма? Бұл жаста бәрін өзі бақылап отырғанын сезіну — ең маңызды психологиялық қажеттілік. Оған 1 минутыңызды қиюға мүмкіндік беріңіз: есесіне көшедегі 30 минуттық дағдарыстың алдын алып, өзіне деген сенімін нығайтасыз.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'Телефон ұрысы 📱', 'Өзіңізге шай құйып жатқанда телефоныңыздың жоғалып кеткенін байқадыңыз, ал диванның артында біреу Сіз сияқты «Алло» деп отыр. Ол Сіздің цифрлық әдеттеріңізді зерттеп жүр.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', '«Өзің киін!» саясаты 👖', 'Аяғын көкке көтеріп: «Мен бөпемін, сен киіндір», — дейді. Балалар дербестік пен тәуелділіктің арасында алма-кезек ауытқып жүреді. Күштеп киіндірмеңіз. Киімді жанына қойып: «Бұл суперқаһарманның шалбары өз иесін күтіп тұр», — деп айла қолданыңыз.'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'Дыбыс өлшегішпен жан тыныштығын табу 🤫', 'Ол ақыры ұйықтады. Бірақ құлағыңыздағы шу әлі басылар емес. Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 desibel жазуына қарап, бөлмедегі тыныштықтың санаңызға қалай сіңіп, жаныңызды қалай тыныштандырып жатқанын көзбен көріп растаңыз.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'Anacan қауымдастығынан жұбаныш 💬', '«Мен ешқашан мінсіз бола алмаймын» деген ой Сізді тұншықтырып жүр ме? Instagram-дағы мінсіз аналар туралы елесті ұмытыңыз. Anacan қауымдастығына кіріп, үйі астаң-кестең болған, баласы қабырғаға сурет салып тастаған аналардың шынайы сырларын оқыңыз да: «Менің жағдайым қалыпты», — деңіз.'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'Сыбырдың тылсым күші 🌙', 'Төсекке жатпау үшін түрлі сылтау ойлап табады. Даусыңызды барынша бәсеңдетіп, тек сыбырлап сөйлеңіз. Сізді түсіну үшін ол бар зейінін аударуға мәжбүр болады, ал мұндай шоғырлану оның миын тыныштандырып, ұйықтатып жібереді.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'Динозавр логикасы 🦖', 'Таңертең ешбір сұраққа жауап бермей, тек ақырады. Бүгін ол — T-Rex. «Ал T-Rex ботқа жей ме?» — деп, оның өзі ойлап тапқан кейіпке бейімделіңіз де, таңғы рәсімді көз жасынсыз аяқтаңыз.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'Әкенің ойдан шығарған қаһармандары 🦸‍♂️', 'Бүгін кешке кітаптағы ертегілерді ұмытыңыз. Әкесі басты кейіпкері баланың өзі болатын қиял-ғажайып оқиғаны ойдан шығарып айтып берсін. «Сөйтіп, ол қылышын суырып алды да... тісін тазалады!» деген сияқты сөйлемдер баланы күлкіге қарық қылып, ұйқыға дайындайды.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'Өз суретін сынау 🖍️', 'Салған қара шимайын көрсетіп: «Бұл сен едің, бірақ дұрыс шықпады», — дейді де, жыртып тастайды. Оның өзін-өзі сынау қабілеті қалыптасып келеді! Сезімдерін елемей қоймаңыз. «Келесі суретте қызыл түсті де қолданып көрерсің?» — деп, дамуына қолдау көрсетіңіз.'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', 'Мұны дүкеннен мен таптым 🛒', 'Кассаға жақындағанда арбадан Сіз салмаған бір қаптама печенье шыға келеді. Ол білдіртпей барлау жүргізіп үлгерген. Сатып алу тізімін ашып, «Қарашы, бұл біздің тізімде жоқ, келесі жолы жазамыз» деп, ережені цифрлық беделді дереккөзге жүктеңіз.'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'Жиһазға өрмелеу олимпиадасы 🧗‍♂️', 'Диванның шетімен терезеге қарай өрмелеп барады. Үй Сіз үшін қауіпке толы болса, ол үшін спортзал. «Абайла, құлап қаласың!» деп дүрліккенше, «Қолыңды мына жерге қой» деп, оның қимыл-қозғалысқа деген қажеттілігін дұрыс бағыттаңыз.'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'Жасырын көкөністер операциясы 🥦', 'Сорпаның ішінен жалғыз күріш түйірін немесе сәбізді тауып алып, «Мен мұны жемеймін» дейді. Тамақтану жоспарына кіріңіз. Ақуыздар мен көкөністерді түрлі-түсті кекс пішініне келтіруді үйреніп, осы қырсық аспаздың миын алдап көріңіз.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'Екеуіңізге арналған шай 🥂', 'Қиын күннен кейін стақандарға кәдімгі ыстық шай құйыңыз. Жұбайыңызбен диванда бір-біріңізге қарап отырып, «Бүгін де сол бейберекет күннен аман өттік, біз керемет командамыз» деп стақандарыңызды түйістіріңіз. Сіздер — отбасының мызғымас тірегісіздер.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'Көлеңкеден қорқу 👻', 'Көшеде келе жатып, кенет өз көлеңкесінен қорқып, Сіздің артыңызға тығылды. Бұдан қисын іздемеңіз, 3.5 жастағы баланың қиялы осылай жұмыс істейді. «Кел, көлеңкенің үстіне секірейік» деп, оны қорқытқан нәрсені бірден қимылды ойынға айналдырыңыз.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'Жасанды интеллект және тыныштық 🤖', 'Балаңыздың кенеттен тұтыға бастауы немесе ашу ұстамалары Сізді интернеттен қауіпті ауруларды іздеуге итермеледі ме? Тоқтаңыз! Anacan AI-дан мұның 3 жастағы даму секірісіне байланысты болуы мүмкін бе деп сұрап, педиатрлар мақұлдаған көңіліңізді тыныштандыратын жауап алыңыз.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'Бөлмедегі дыбыс әсерлері 🪄', 'Ақылды ертегілерді қосыңыз. Оқиғаны оқып отырып, есіктің сықырын, желдің дыбысын және сыбырды салып, бөлмеде дыбыс театрын ұйымдастырыңыз. Бұл ерекше дыбыс толқындары оның назарын бірден ертегі әлеміне, ал одан әрі терең ұйқыға жетелейді.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'Нанның ортасы менікі! 🍞', 'Бір тілім нанның тек ортасын жеп, қабығын Сізге ұстата ма? Нан қабығы үшін дауласпаңыз. Ертеңнен бастап нанды металл печенье қалыптарымен (жануар пішінінде) кесіңіз. Әдемі пішін бұл тағамға қатысты мәселені бірден шешеді.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'Ваннадағы су тасқыны 🌊', 'Шомылу жай ғана сылтау болып, ол ваннада нағыз мұхит жасап, толқындармен ойнап жүр ме? Ойнай берсін. Судың сол шуы мен шашырауы оның бойындағы сарқылмас, тентек энергияны басады. Кешке еш қарсылықсыз төсегіне жатады.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'Қызық сұрақтарға AI жауабы 🤖', '«Анашым, менің көлеңкем түнде қайда кетеді?» деген сұраққа не айтарыңызды білмей қалдыңыз ба? Ештеңе ойдан шығармаңыз. Anacan AI-ын ашып, 3.5 жастағы балаға арналған ең ертегіге ұқсас, сүйкімді ғылыми жауапты алып, оған оқып беріңіз. Өзіңізді ұлы философ әрі бәрін білетін анадай сезінесіз.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'Теріс киілген киімнің мақтанышы 👕', 'Жейдесін теріс киіп алып, түзетуге үзілді-кесілді жол бермей ме? Өз еркі! Оның «Менің қолымнан келді!» деген жанарындағы сенімділік киімді дұрыс киюден әлдеқайда маңызды. Күні бойы солай мақтанышпен жүре берсін, бұл — оның таңдауы.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'Сыбырмен ұйықтату 🤫', 'Төсегінен тұрып, бөлмеде жүгіріп жүр, ұйықтағысы келмей ме? Айқайламаңыз. Кенеттен өте баяу, сыбырлап сөйлей бастаңыз. Сізді түсіну үшін бар зейінін жинауға тура келеді, содан миы шаршап, автоматты түрде ұйқы режиміне көшеді. Байқап көріңіз!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'Мінсіз тыныштық сәті 🛋️', 'Пазлдарымен беріліп ойнағаны сонша, үй іші кенеттен тып-тыныш болып қалды ма? Күдіктенбеңіз, бірден өзіңізге кофе құйып алыңыз. Сол сирек әрі алтынға бергісіз минуттарды үй жинауға немесе кір жууға емес, жаныңызды тынықтыруға жұмсаңыз. Сіз робот емессіз.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'Ваннадағы шағын зертхана 🛀', 'Суға түрлі түсті сабындарды қосып, сиқырлы қоспа жасап жатыр. Иә, жуынатын бөлме былғанады. Бірақ ол еріткіштер мен заттардың араласуын зерттеп жүр. Бұл ғылыми ізденіс оның кешкі шаршауын басып, тыныш ұйқыға дайындайтын ең жақсы тәсіл.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'Жанасудан қажу төңкерісі 🔋', 'Күні бойы үстіңізге өрмелеп, шашыңызды тартқан баладан физикалық тұрғыда әбден қажыдыңыз. Оны дереу қауіпсіз жерге қалдырып, басқа бөлмеге өтіңіз. Көңіл күй күнделігіне «Денем маған тиесілі емес» деп жазып, жанасудан қажу — touched out синдромының психологиялық жүгінен арылыңыз.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'Киім шкафындағы оңашалану 🚪', 'Үйдің ортасындағы шу кенеттен тыйылды. Балаңызды киім шкафының ішінде, қараңғыда жалғыз ойнап отырған жерінен таптыңыз. Бұл депрессия емес, жай ғана эмоциялық қайта жүктелу сәті. Есікті ақырын жауып, оған жеке кеңістікте болу рақатын сыйлаңыз.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'Тек иісін терең жұтыңыз 🫂', 'Бүгін Сізді әбден есіңізден тандырып, бар күшіңізді сарқып қойды ма? Бірақ төсекте сондай пәк күйде ұйықтап жатыр... Жарықты өшіріңіз, ертегі оқымай-ақ қойыңыз. Жанына жатып, баланың жұпар иісін терең жұтыңыз да, осы күнге де шүкір етіңіз.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'Үйден шыққым келмейді деген әңгіме ⛅', 'Төрт қабырға Сізді тұншықтырып барады, ал ол диванда жылап, далаға шыққысы келмей отыр ма? Ауа райы мен киім бөлімін ашып, дұрыс үйлесімді таңдаңыз да, қарсылық білдірсе де, саябаққа алып барыңыз. Таза ауа бетіне тиген бойда бүкіл ашу-ызасы басылады. Сіздің қолыңыздан келетініне сенеміз!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'Бір-біріне тимейтін тағамдар заңы 🚫', 'Таңғы ас кезінде қызанақ қиярға тиіп кеткені үшін төңкеріс басталды ма? 3.5 жастың ресми тағам философиясына қош келдіңіз. Бұдан қисын іздемеңіз. Пайдалы рецепттер бөлімінен тәрелкені қызықты әрі бір-бірінен оқшауланған аймақтарға бөлуді үйреніп, осы қисынсыз дағдарысты бейбіт жолмен шешіңіз.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'Ұйқы алдындағы дипломатиялық келіссөз 🤝', 'Төсекке жатпау үшін Сізбен кәдімгідей саудаласады: Екі ұрттам су ішейін, бір рет құшақташы, сосын ұйықтаймын. Бұл шебер айласына күлімсірей қараңыз. Шартын қабылдап, жарықты нық қимылмен өшіріңіз де, келісімді сол сәтте бекітіңіз.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'Едендегі лава ойыны 🌋', 'Еден — лава, диванға шығыңыз! Қиялы үйді ну орманға айналдырды. Шаруаңызды бір сәтке қоя тұрып, небәрі 2 минут болса да, лавадан қашып, оның әлеміне еніңіз. Кейде баланың ережесіне бағыну — күйзелістен арылудың ең жақсы тәсілі.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'Қоқыс жәшігіндегі құпиялар 🗑️', 'Дүкеннен сатып алған ойыншықты емес, оның қаптамасындағы көпіршікті үлдірді құшақтап, күні бойы сонымен ойнай ма? Баланың миы дайын сценарийлерді емес, еркіндікті жақсы көреді. Даму бақылағышына оның осындай ерекше шығармашылық сәттерін мақтанышпен белгілеп қойыңыз.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'Кешкі тыныштық сәттері 🛀', 'Күні бойы «неге?» деген сұрақтардан басыңыз қатып кетті. Оны жылы су толтырылған ваннаға отырғызып, аздап көбік қосыңыз. Ал өзіңіз қасында отырып, судың дыбысына ғана зейін қойыңыз. Судың сиқырлы әсері баланың қырсықтығын шайып қана қоймай, Сіздің де жүйкеңізді тыныштандырады.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'Сіз мені тыңдамайсыз! 😤', '«Мені тыңдашы!» деп, бетіңізді қолымен өзіне қарай бұрады. Оған Сіздің тек қасында болғаныңыз емес, бүкіл назарыңыздың 100% өзінде болғаны қажет. Телефонды немесе қолыңыздағы істі небәрі 3 минутқа қоя тұрып, көзіне тіке қарап тыңдаңыз. Бұл бірнеше сағатқа созылатын қыңқылды болдырмайды.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'Әкенің ұшақ режимі ✈️', 'Үйде энергиясын шығара алмай, ұйықтағысы келмей жүр. Әкесін диванға шақырыңыз. Ол баланы әуеге көтеріп, ұшақ болып ойнағанда, бөлмені кернеген шат күлкі жиналған бүкіл физикалық ширығуды санаулы секундта басады. Ендігі кезек әкеде.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'Жаңа тіл ойлап табу 🗣️', '«Ойыншығым мұңайды», «Аспан жылады» дегендей, заттарға сезім дарытып, өзі ойлап тапқан поэтикалық сөйлемдер құрайды. Оның сөздік қоры мен эмоциялық зердесі қарқынды дамып келеді. Бөпе фотосессиясының бейне режимін қосып, оның осы сүйкімді ой-толғамдарын бірден мұрағатқа сақтап қойыңыз.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'Асүй басшысы іске кірісті 🧑‍🍳', 'Сіз кекс пісіргенде, ол міндетті түрде жаныңызға орындық қойып, ұнды өзі салғысы келеді. Рұқсат етсеңіз, асүйдің астан-кестені шығуы мүмкін. Оған бос ыдыс, су мен аздап ұн беріп, «Өз кексіңнің қамырын өзің иле» деңіз. Айнала шашылады, есесіне ол өзін нағыз шебер сезінеді.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', '«Өзің же!» бүлігі 🥣', 'Өзі жей алса да, қасарысып Сіздің тамақтандыруыңызды талап етеді, артынша қасықты итеріп жіберіп, жылайды. Бұл — қайшылықтарға толы кезең. Оны тамақтандыруға тырыспаңыз да, аш қалады деп қорықпаңыз да. Тәрелкені алдына қойып, «Қарның ашқанда жерсің» деңіз де, үстелден тұрыңыз. Өзі-ақ жейді.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'Ананың қоректік қоры 🥗', 'Оны тойдыру үшін түрлі мәзір ойлап таптыңыз, ал өзіңіз тағы да жүре-жүре құрғақ тамақ жеп қойдыңыз ба? Пайдалы рецепттерден балаларға ғана емес, аналарға да арналған, 10 минутта дайындалатын, темір мен кальцийге бай әрі қуат беретін түскі ас таңдап, өзіңізге де көңіл бөліңіз.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', '«Ойыншығым ауырып қалды» ойыны 🩺', 'Ойыншық стетоскопын алып, қонжығын байыппен тексеріп, оған жараға арналған жапсырма жапсырады. Символдық ойындар арқылы ол жанашырлық пен қамқорлықты түсініп, бойына сіңіреді. Сіз де науқастың рөліне кіріп, жата қалыңыз да, оған Сізді 5 минут бойы үнсіз тексеруге мүмкіндік беріңіз.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'Ақылды ертегілермен тәтті ұйқы 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкері балаңыз, ал бағындыратын мекені оның бөлмесі болатын ерекше әрі еш күш салуды қажет етпейтін ұйқы алдындағы хикаяны құрастырыңыз.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойынның, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, жұпар иісін терең жұтыңыз да, қараңғыда оған қаншалықты қымбат екенін және оны қалай жақсы көретініңізді сыбырлап айтыңыз.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'Түн ортасындағы философия 🦉', 'Төсекке енді жатқанда, «Анашым, бұлттар неге төмен құлап кетпейді?» деген сияқты терең сұрақтар қоя ма? Оның мақсаты ғылымды үйрену емес, Сізбен сөйлесіп, ұйықтайтын уақытын созу. «Өйткені олар жоғарыда ұйықтайды» дегендей қысқа, ойдан шығарылған жауап беріп, «Ақылды ертегілердегі» баяу әуенді қосыңыз да, ұйқы алдындағы тыныштықты нық орнатыңыз.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'Дүкендегі әлгі ыңғайсыз сұрақ 😳', 'Кассада кезекте тұрғанда, «Мына апайдың шашы неге мұндай?» деп дауыстап сұрады ма? Оны ұялтып, аузын жаптыруға тырыспаңыз. Назарын бірден қолданбадағы «Сатып алу тізіміне» аударып: «Қарашы, біз алма алдық па?» — деп, жағдайдан сыпайы шығып кетіңіз.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'Ол жейде неге жуылды?! 👕', 'Сүйікті, әбден оңып кеткен жейдесін кір жуғыш машинаға салғаныңыз үшін үйде қаралы күн жарияланды ма? Балалардың заттарға бауыр басуы кейде қисынға бағынбайды. Дауласпай-ақ, бірден «Бөпенің фотосессиясын» ашып, оның ашулы кейпін суретке түсіріп, күлкіге айналдырыңыз. «Кел, экраннан қаншалық ашулы көрінетініңді қарайық» деген айла назарын бірден басқаға аударады — байқап көріңіз!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'Жарықты өшіріңіз, көлеңкелер театры басталсын 🐰', 'Қараңғыдан қорқып, дәлізге жалғыз шыққысы келмей ме? Бөлменің жарығын толық өшіріп, шағын қолшамды жағыңыз. Қолыңызбен қабырғаға ит пен құстың көлеңкесін түсіріп, қараңғылықты қорқынышты жерден ойын алаңына айналдырыңыз. Оның ұйықтап кетуі әп-сәтте болады.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'Сізге де offline режимі қажет ☕', 'Бөлмеде ойыншықтарымен беріліп ойнап, үй іші кенеттен тып-тыныш болып қалды ма? Айналайын, сол сәтті үй сыпыруға немесе киім бүктеуге жұмсамаңыз! Диванға жатып, «Көңіл күй күнделігіне» «небәрі 5 минут тыныштық» деп жазыңыз да, кофеңізді суытпай ішіңіз. Сіз де осы үйде тұратын адамсыз.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'Мен шашқан жоқпын, қонжығым шашты! 🧸', 'Суды әдейі жерге төгіп, кінәні ойыншығына арта ма? Ол өтірік айтып тұрған жоқ, тек 3.5 жастағы қорғану механизмін ашты. Қасарыспай-ақ: «Онда қонжығыңа қалай тазалау керегін үйретейік», — деп, қолына сүлгі ұстатыңыз. Осылайша ол жауапкершілікті де үйренеді, намысына да тимейді.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'Физикаға бағынбайтын қырсықтық 💧', 'Суды үстелге төгіп алып, енді Сізден оны қайтадан стақанға құюды жылап талап етіп жатыр ма? Иә, бұл бөлмеде қазір қисын жоқ, тек түзетуге келмейтін қателіктен туған өкініш бар. Түсіндіруге тырыспаңыз. Қолына сүлгі беріп: «Кел, мына суды жоқ қылайық», — деп, бәрін ойынға айналдырыңыз.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'Анаға арналған Offline баспана 🚪', 'У-шудан құлағыңыз шыңылдап кетті. Оны қауіпсіз жерге (немесе әкесіне) қалдырып, дәретханаға кіріңіз де, есікті жабыңыз. Небәрі 5 минут қабырғаға қарап отырыңыз, ештеңе істемеңіз, тіпті телефонды да ашпаңыз. Осы қысқа тыныштық — Сізді аналық рөліңізге қайта оралтатын ең қуатты құрал.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'Жансыз заттармен әңгіме 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа асқан байыппен бірдеңелер айтып, тіпті оларға ұрсады. Символдық ойындар арқылы ол қоршаған әлемді танып-біледі.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'Таңғы жасырынбақ 🙈', 'Сіз жұмысқа немесе балабақшаға кешігіп бара жатсыз, ал ол перденің артына тығылып алып: Мені тап! дейді. Жүйкеңіз жұқарса да, айқайлау бәрін одан әрі созып жібереді. Менің сүйкімді балам қайда екен? деп, ойынға 2 минутқа қосылыңыз да, оны тауып алып, жасырынған жерінен шығарыңыз.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'Саябақтағы саясат 🤝', 'Сырғанақта басқа баланы итеріп жіберіп, өзі сырғанағысы келе ме? Бөлісу ол үшін әлі толық қалыптаспаған, күрделі ұғым. Ұялтудың немесе жазалаудың орнына: Қазір оның кезегі деп, ойын тәртібін жай ғана еске салыңыз.'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'Күн неге маған қарап тұр?! ☀️', 'Таңертең көзін аша сала: Күн неге тура көзіме қарап тұр? деп өксіп жылай ма? Бұдан қисын іздеп, табиғи құбылыстарды түсіндіруге тырыспаңыз. Ол жай ғана әлемді басқара алмайтынына ашуланып тұр. Пердені жауып: Күнді сен үшін жасырып қойдым деңіз де, осы қисынсыз мәселені әп-сәтте шешіңіз.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'Менің мәшинем әлі ұйықтаған жоқ! 🚗', 'Төсекке жатпау үшін: Мәшинемнің ұйқысы келмейді деп қасарыса ма? Балалар көбіне ұйықтағысы келмейтінін және қарсылығын ойыншықтарына телиді. Дауласпаңыз, Ақылды ертегілерді қосып, мәшинелер туралы ертегі құрастырыңыз. Мәшине ұйықтаған бойда, ол да өздігінен көзін жұмады. Байқап көріңіз!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'Нанның шетін кесіп тастаңыз! 🍞', 'Тосттың тек жұмсақ ортасын жеп, шеттерінен үзілді-кесілді бас тарта ма? Бұл жаста балалардың тағамның сыртқы көрінісіне қатысты өз талғамы болады. Нанды сүйкімді жануарлардың пішініне келтіріп кесуді үйреніңіз. Әдемі безендіру бұл дауды бірден тоқтатады.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'Үнсіз көзқарастың ләззаты 🥂', 'Бала ұйықтады, үй жиналды. Жұбайыңызбен диванда қатар отырыңыз, тіпті теледидарды да қоспаңыз. Бір-біріңізге жай ғана бүгін де аман қалдық деген көзқараспен қараңыз. Сеніңіз, шаршаған ата-ана өміріндегі ең романтикалық әрі шынайы сәт — дәл осы.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'Көрінбейтін дақтың машақаты 👕', 'Жейдесінен тек микроскоппен көруге болатын дақты тауып алып, оны киюден бас тартты ма? Дақты дымқыл майлықпен өтірік сүртіп: Сиқырмен жоғалтып жібердім деңіз. Бала анасының сиқырына әрдайым сенеді, байқап көріңіз.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'Әкесімен диванда күресу 🤼‍♂️', 'Ұйықтамау үшін қашып, тығылып қалды ма? Оны әкесіне тапсырыңыз. Диванда өтірік күресе тұрсын. Осы шулы әрі терлететін ойын баланың бойындағы соңғы тентек энергиясын да шығарып, ұйқыға оңай кетуіне көмектеседі.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'Музыкалық гипноз әсері 🎶', 'Кешке қарай себепсіз басталатын мазасыздықты баяу классикалық музыкамен басып көріңіз. Теледидарды өшіріңіз. Көбіне осы қарапайым әдіс айналадағы шуды бәсеңдетіп, бөлмеге ғажайып тыныштық орнатады.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'Өзі ойлап тапқан сөздер 🗣️', 'Аспан жылады, Көлік ренжіді деген сияқты қызық сөйлемдер құрайды. Сөздік қоры құйын секілді қарқынды өсіп, ол сөздермен ойнай бастайды. Даму трекерін ашып, оның осы сүйкімді поэтикалық ойларын мұрағатқа қосыңыз — бірнеше жылдан кейін оқып, бірге мәз болып күлесіздер.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'Экран үшін өзіңізді кінәламаңыз 📺', 'Бүгін шаруаңыз көп болып, балаңыз теледидар алдында ұзақ отырды ма? Енді өзіңізді кінәлі сезініп жүрсіз бе? Күн сайын мінсіз болу мүмкін емес. Кейде экран бізді үлкен әбігерден құтқаратын ең зиянсыз күтушіге айналады. Өзіңізді жазғырмаңыз.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'Біртүрлі қорқыныштардың басталуы 🤖', 'Кенеттен ваннадағы су ағатын тесіктен қорқа бастады ма? Интернеттен ауру іздемеңіз. Anacan AI-дан сұраңыз: бұл осы жастағы қиялдан туындайтын, мүлде қалыпты әрі уақытша фобия екенін біліп, алаңдауыңызды басыңыз.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'Өзім жеймін! 🥣', 'Өзі жей алса да, қасарысып Сіздің тамақтандыруыңызды талап етеді, ал қасықты ұсынсаңыз, итеріп жіберіп жылайды. Не қалайтынын өзі де білмейді. Тәрелкені алдына қойып, Қарның ашқанда жерсің деңіз де, үстелден тұрыңыз. Қарны ашқанда өзі жейді.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'Өзіңізге де аздап уақыт бөліңіз 💆‍♂️', 'Бала ұйықтағаннан кейін жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Күні бойы тынымсыз жүріп, мойныңыз құрысып қалды. Сіздер бір үйде тұратын ата-ана ғана емес, бір-біріңізге ең жақын психологиялық тірексіздер.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Инстаграмдағы аналар және шынайы өмір 📱', 'Инстаграмды аша сала жұрттың мінсіз балаларын көріп, көңіліңізді түсірмеңіз! Қолданбаны жауып, Anacan қауымдастығына кіріңіз. Басқалардың да үйі Сіздікіндей астан-кестен, балалары у-шу екенін көріп, мен мүлде қалыптымын деңіз!'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'Қараңғы бөлмедегі көлеңке театры 🐰', 'Қараңғыдан қорқып, ұйықтауға бармай жүр ме? Бөлменің жарығын толық өшіріп, шағын қолшамды жағыңыз. Қабырғаға қолыңызбен иттің, құстың көлеңкесін түсіріңіз. Қорқынышты қараңғылықты ол үшін ойын алаңына айналдырсаңыз, әп-сәтте ұйықтап қалады.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'Динозаврлар ботқа жемейді! 🦖', 'Таңертең ешбір сұраққа жауап бермей, тек ақырып жүр ме? Бүгін ол — T-Rex. «Ал T-Rex таңғы ас іше ме?» деп, оның өзі ойлап тапқан кейіпке қосылыңыз. Сонда ол дастарқанға көз жасынсыз-ақ отырады.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'Бүгін менің күшім таусылды 🛑', 'Бәрі бір мезетте үйіліп, даусыңызды көтеріп жібердіңіз. Енді өзіңізді кінәлі сезініп отырсыз. Сіз робот емессіз. Көңіл күй күнделігін ашып, «Бүгін шынымен қатты шаршадым» деп жазыңыз. Өзіңізді жасанды жымиюға мәжбүрлегеннен гөрі, мұны мойындау Сізге көбірек көмектеседі.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', '«Сен кімсің?» ойыны 🎭', 'Таңертең Сізге бөтен адамдай қарап: «Сен кімсің? Менің анам қайда?» — деді ме? Бұл — жаңа рөлдік ойын. «Мен көрші апаймын, анаң қазір келеді», — деңіз. Таңнан бөлме күлкіге толсын: бұл қырсықтасқаннан әлдеқайда аз күш алады.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'Ертегі оқымай-ақ ұйықтату 🪄', 'Бүгін кешке ертегі оқуға шамаңыз жоқ па? Ақылды ертегілерді қосыңыз. Фонға тек сыбдырлаған орман мен желдің дыбыстарын қойыңыз. Қараңғыда бөпеңізбен бірге табиғат үнін тыңдап, күндізгі қарбаластан тынығыңыз. Көздің шаршауы да бірден басылады.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'Кір жуғыштан табылған қазына 🍝', 'Шалбарын жуып жатқанда қалтасынан кеуіп қалған макарон немесе тас шықты ма? Бұл ашкөздік емес, балалық зерттеушілік. Оны байсалды кейіппен қоқысқа тастаңыз, бірақ іштей осы қор жинағыш балаға күлімсіреңіз. Даму трекеріне мұны күлкілі сәт ретінде белгілеп қойыңыз.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'Суды басқа стақанға құйыңыз! 🥤', 'Суды сары стақанға бергеніңіз үшін бөлмеде айқай-шу басталды ма? Мәселені ушықтырмаңыз, ол тек өз шекарасын тексеріп жүр. Суды дереу өзі қалаған стақанға құйып беріңіз де, үйдегі тыныштықты қалпына келтіріп, күшіңізді күннің қалған бөлігіне сақтаңыз.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'Саябақтан қайтуға арналған жарыс тәсілі 🌳', 'Саябақтан қайтатын уақыт келіп, жылау басталды ма? Оны сүйреп әкету көмектеспейді. «Кәне, көлікке дейін кім пингвин сияқты тезірек жетеді?» — деп, назарын бірден көңілді жарысқа аударыңыз. Ол міндетті түрде жеңгісі келеді.'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'Қоңырау соғылғанда ұйықтаймыз ⏱️', 'Ұйықтайтын уақыт созылған үстіне созыла береді. Су, дәретхана, қабырғамен қоштасу... Телефонның таймерін орнатыңыз. Қоңырау үнін естігенде бәрі жарықты өшіреді деген ереже қойыңыз. Сол дыбысты естігенде еш қарсылықсыз төсегіне жатады.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'Төрт аяқтап жүрген бала 🐾', 'Бүгін таңертең ол төсектен бала сияқты емес, күшік сияқты төрт аяқтап шықты ма? Ереже айтып, ашуланбаңыз. «Менің ақылды күшігім қандай керемет!» деп, таңғы асын беріңіз. Рөлдік ойынға қосылу қырсықтасудан әлдеқайда аз күш жұмсатады.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'Денем өзіме тиесілі емес 🔋', 'Күні бойы аяғыңызға жабысып, құшақтауыңызды сұрай ма? Сіз физикалық тұрғыдан әбден қажыдыңыз. Жанасудан шаршауды сезініп жүрсіз. Оны бөлмеде ойыншықтарымен қалдырып, 5 минутқа жуынатын бөлмеге кіріп, есікті жабыңыз. Аз ғана уақыт жалғыз қалудың рахатын сезініңіз.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'Түн ортасындағы кенет айқай 😭', 'Түнде көзі жұмулы күйде жылап оянып, Сізді естімей ме? Бұл — түнгі қорқыныш ұстамасы. Оятуға тырыспаңыз, тек жанында болып, қолынан ұстап, сипаңыз. Өзі тынышталып, қайтадан терең ұйқыға кетеді.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'Асүйдегі кішкентай көмекшінің әлегі 🧑‍🍳', 'Сіз қамыр жайып жатқанда, орындығын әкеліп қойып, ұнды міндетті түрде өзі төккісі келді ме? Рұқсат бермесеңіз, жылайды. Оған кішкентай пластик ыдыс пен аздап ұн беріңіз. Асүй шашылып қалады, бірақ оның байсалды аспаз кейпі сол тазалыққа тұрарлық.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'Есікті мен ашамын! 🚪', 'Үйден шығарда есікті Сіз ашқаныңыз үшін жылап, қайта жаптырып, өзі ашты ма? Осы жаста жағдайды бақылауда ұстау сезімі — ең маңызды психологиялық қажеттілік. Оған 1 минут жұмсаңыз, есесіне көшеде болатын 30 минуттық дағдарыстың алдын аласыз.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'Дүкен ортасында тұрып қалу 🛒', 'Дүкеннің ортасында тұрып: «Мен не алуға келіп едім?» деп ойланып қалдыңыз ба? Ананың миы шынымен де сан түрлі ойға толы. Қолданбадағы «Сатып алу тізімін» ашып, сол цифрлық жадқа сену Сізді мұндай әбігерден әрдайым құтқарады.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'Ваннадағы су тасқыны 🌊', 'Шомылу — жай ғана сылтау, ал ол ваннада нағыз мұхит жасап, толқындармен ойнап жүр ме? Ойнай берсін. Судың шуы мен шашыраған тамшылар бойындағы сарқылмас қырсық энергияны шайып әкетеді. Кешке еш қарсылықсыз төсегіне жатады.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'Қызық сұрақтарға AI жауабы 🤖', '«Анашым, менің көлеңкем түнде қайда кетеді?» деген сұраққа не айтарыңызды білмей қалдыңыз ба? Ештеңе ойдан шығармаңыз. Anacan AI-ды ашып, осы жасқа лайық ертегідей әрі сүйкімді ғылыми жауапты алып, оған оқып беріңіз. Өзіңізді ұлы философтай сезінесіз.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'Іштегі ашуды жазып шығару 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай, бұл ашуыңызды тудыра ма? Көңіл күй күнделігін ашыңыз. Бүгін Сізді ашуландырғанның бәрін сонда жазыңыз. Жалған күлімсірегеннен гөрі, эмоцияңызды қабылдап, жазып шығару көбірек көмектеседі.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'Жансыз заттармен ұзақ сөйлесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа бар ынтасымен әлдене айтып жүр ме? Ол ойын арқылы ережелерді түсініп, қоршаған әлемді танып жатыр.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'Бүгін кешке жай ғана құшақтасайық 🫂', 'Ешқандай ойынның да, дыбысы қатты кітаптың да қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, сәбиге тән жұпар иісін терең жұтыңыз да, қараңғыда оның қаншалықты қымбат екенін сыбырлап айтыңыз. Бұл екеуіңізге де жеткілікті болады.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'Ауа райын терезеге қарап болжай салмаңыз ⛅', 'Сыртта күн ашық, бірақ жел соғып тұр ма? Ауа райы мен киім құралы бөпеңізді қабаттап киіндіруге кеңес берсе, оған сеніңіз. Есік алдында не киеріңізді шеше алмай қиналғанша, дұрыс киім үйлесімін таңдап, алаңсыз серуенге шығыңыз.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'Өз тамағын Сізге бермейді 🍳', 'Өз тәрелкесіндегі тамақты Сізге бермейді, бірақ келіп, Сіздің тәрелкеңізден жегісі келіп тұрып ала ма? Балалар ата-анасының таңдауына әрдайым толық сенеді. Қарсыласпай-ақ, бір үзімін сүйіспеншілікпен ұсыныңыз да, осы күлкілі өзімшілдігіне жымиып қойыңыз.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'Менің ертегім, менің ережем 📖', 'Ертегі оқып отырып, бір сөзді қате айтқаныңызда, ол Сізді бірден түзетті ме? Демек, жаттап алған! Кітапты жауып: «Онда бүгін кешке маған сен оқып бер», — деңіз. Оның қиялына ерік беріңіз, ал өзіңіз жайғасып жатып, сүйкімді дауысын тыңдаңыз.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'Мұнара тұрғызып, кейін оны құлату 🧱', 'Текшелерден бар ынтасымен мұнара тұрғызып, кейін қарқылдап күліп, бір соққымен құлата ма? Сіз оның еңбегін аясаңыз да, ол физиканы және себеп-салдар байланысын үйреніп жатыр. Бұл қирандылар — оның миында қалыптасып жатқан жаңа байланыстар, сондықтан ашуланбаңыз.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'Мінсіз тыныштық сәті 🛋️', 'Пазлдарын құрауға беріліп кеткені сонша, үй іші кенет тып-тыныш болып қалды ма? Күмәнданбай-ақ, дереу өзіңізге кофе құйып алыңыз. Осындай сирек әрі алтынға тең минуттарды үй жинауға немесе кір жууға емес, жаныңызды тынықтырып, төбеге қарап жатуға арнаңыз. Сіз робот емессіз.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'Жейденің заттаңбасы батып тұр! 🏷️', 'Артындағы кішкентай заттаңба инедей батқандықтан, жейдені кимеймін деп тұр ма? Бұл жастағы сенсорлық сезімталдық адамды әбден шаршатады. Дауласпай-ақ, қайшыны алып, заттаңбаны түбінен қиып тастаңыз да, осы шағын дағдарысты бір сәтте шешіңіз.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'Сыбырлап ұйықтату 🤫', 'Төсектен тұрып алып, бөлмеде жүгіріп жүр, ұйықтағысы келмей ме? Айқайламаңыз. Кенет өте баяу, сыбырлап сөйлей бастаңыз. Сізді түсіну үшін бар зейінін салуға тура келеді, содан миы шаршап, автоматты түрде ұйқы режиміне ауысады. Байқап көріңіз!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', '«Ойыншығым төгіп алды!» деген өтірік 🤷‍♂️', 'Суды әдейі жерге төгіп алды да, ойыншық мәшинесін саусағымен көрсетіп, «Ол итерді» деді ме? Бұл өтірік айту емес, қорғану механизмі. «Кәне, осы мәшинеге де қалай тазалау керегін үйретейік» деп, оның назарын шебер бұрып жіберіңіз.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'Экрандағы тыныштық көрсеткіші 🤫', 'Ақыры ұйықтады. Үй іші құлағыңыз шыңылдайтындай тым-тырыс болып қалды ма? Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 desibel деген жазуға қарау шуылдан қажыған миыңыз үшін әлемдегі ең жақсы визуалды массаж болады.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'Көзге көрінбейтін көкөністер операциясы 🥦', 'Сорпаның ішінен жалғыз түйір сәбізді тауып алып, «Мұны жемеймін» деді ме? Таныс жағдай! Көкөністерді езбе жасап, тұздықтарға араластырыңыз, енді қалай табар екен! Оның аспаздық қырағылығын жеңіңіз.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'Теріс киілген жейдеге деген мақтаныш 👕', 'Жейдесін теріс киіп алып, түзетуге үзілді-кесілді келіспей ме? Өз еркі! Оның «Өзім кидім!» деген жанарындағы сенім жейдені дұрыс киюден әлдеқайда маңызды. Күні бойы солай мақтанып жүре берсін, бұл — оның еркін таңдауы.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'Сөзіңіз өтпегенде, әкесі көмекке келеді 🤡', 'Сөзіңізге енді құлақ аспай, қасарысып тұр ма? Әкесі келіп, жануарлардың оғаш дыбыстарын салып, күлкілі кейіп таныта бастағанда, бірден күліп жіберді ме? Кейде ер адамдардың осындай қисынсыз әзілі үйдегі жағдайды шынымен құтқарады. Сіз сырттай бақылап отырыңыз.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'Крекер сынды деген драма 🍪', 'Крекер екіге бөлінді деп ақырзаман орнады ма? Оны қайта жабыстыра алмайсыз. «Қарашы, енді екеу болды: біреуі маған, біреуі саған», — деп, математика мен бөлісуді көмекке шақырыңыз.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'Балмұздақ түсінде қалып қойды 🍦', 'Түсінде балмұздақ жеп жатқанда оятып жібергеніңіз үшін Сізге ашуланды ма? Түс пен шындық бір-бірімен араласып кеткен. Қабағын түйген күйінде құшақтап, күліңіз, шындыққа оралуына 2 минуттай уақыт керек.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'Су құтысының түсі 🚰', 'Түнде су сұрайды, бірақ қызыл стақаннан ішкісі келмей ме? Түн ортасында қисын іздеп, оған ақыл айтпаңыз. Стақанды бірден ауыстырып, күшіңізді таңға және тыныштыққа сақтаңыз.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', '«Аяқкиімімнің ішінде тас бар» әлегі 👟', 'Аяқкиімін 10 рет шешкізіп, тексертеді, бірақ ішінде тас жоқ! Таныс жағдай ма? Қолыңызға білдіртпей бір қара түйіршік алып, «Қарашы, таптым, енді бәрі жақсы», — деңіз де, серуенді жалғастырыңыз.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'Ботқа неге ыстық? 🥣', 'Ыстық болмаса жемейді, ал қазір ыстық деп жылап отыр ма? Нағыз тығырық! Ішіне әдейі түрлі түсті мұз кесегін салыңыз, ол бірден қызығып, тынышталады.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'Есіктің ар жағында жылау 🚪', 'Есікті жауып алып, бөлмесінде жалғыз жылап отыр және Сізді көргісі келмей ме? Күштеп құшақтауға тырыспаңыз. Кейде балалар да сезімдерін жалғыз өткергісі келеді, оған уақыт пен кеңістік беріңіз.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'Кітаптағы қасқырға ашулану 🐺', 'Кітаптағы қасқырдың суретін жұдырықтап, ұрсып жатыр ма? Қиялы керемет! Шындықты бұрмаламай, «Сен мені қорғадың, өте батылсың», — деп, өзіне деген сенімін арттырыңыз.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'Шұлығымды сен кигізбе! 🧦', 'Сіз жасағанның бәрінен үзілді-кесілді бас тарта ма? Керемет! Киімді диванға қойып, «Кім бірінші киінеді?» деген жарыс бастаңыз. Өзі-ақ санаулы секундта киініп алады.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'Менің түскі асым қайда? 🥗', 'Балаңызға көкөніс қосылған арнайы ас дайындап, өзіңіз нан кеміріп жүрсіз бе? Тоқтаңыз! Тамақтану жоспарындағы аналарға арналған 5 минутта жасалатын оңай салатты дайындап, осы үйдің негізгі қозғаушы күшіне (өзіңізге) қуат беруді ұмытпаңыз. Сіз маңыздысыз.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'Жарықты өшірейік, ұйқы келсін 🌙', 'Ұйықтауына 1 сағат қалғанда бөлмедегі барлық жарық шамдар мен теледидарды өшіріңіз. Бөлме қараңғыланған сайын ол өздігінен есіней бастайды. Осылайша мелатонинді (ұйқы гормонын) білдіртпей, табиғи жолмен іске қосып, өзіңізге жеңілдік жасаңыз.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'Мен білемін, Сізге де үйретейін ☝️', 'Өзіңіз білетін нәрсені балаңыз байсалды әрі ақылды кейіппен түсіндіріп жүр ме? Ол өз зердесін сынап жатыр. Күліп жібермеу үшін ерніңізді тістеп, оны өте мұқият тыңдаңыз да: «Шынымен бе? Көп рақмет», — деңіз.'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'Әкесінің ертегіні қате айтуы 📖', 'Бүгін кешке ертегіні Сіз айтпайсыз. Ертегі кітабын әкесіне беріңіз. Әкесі оқиғаны әдейі шатастырып, күлкілі әрі қисынсыз етіп айтып берсін. Балаңыздың оны түзеткеніне мәз болып, қарқылдап күлгенін сырттай сүйсіне тамашалаңыз.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'Тазалықты қоя тұрыңыз, ойыншықтар жата берсін 🎨', 'Бөлменің ортасында түрлі бөлшектерден үлкен туынды жасап, оны жинауға рұқсат бермей жүр ме? Тазалыққа деген құмарлығыңызды қоя тұрыңыз. Ол жасаған бейберекет дүниеге тимеңіз, жинауды ертеңге де қалдыруға болады. Үй мұражай емес.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'Мультфильмді Сізге айтып береді 📺', 'Көрген мультфильмін мүлде басқа қисынмен баяндап, кімнің қайда барғанын байыппен түсіндіріп жүр ме? Оны бәріне сенгендей мұқият тыңдаңыз. Өзін әлемдегі ең ақылды әрі ең мықты жан ретінде сезінсін.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'Дүкендегі әлгі қорқынышты «алып берші» 🛒', 'Кассаның дәл алдында шоколад сұрап, айқайлап жатыр ма? Артыңыздағы адамдардың көзқарасына қарамастан, беріле салмаңыз. Сатып алу тізімін ашып: «Бұл тізімде жоқ, касса оны өткізбейді», — деңіз. Сыртқы бір беделді себеп оларға әрдайым сенімдірек көрінеді.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'Бүкіл шаршауды сумен шайып жіберу 🛀', 'Кейде ештеңе көмектеспейді, ол кез келген нәрсеге жылай береді. Оны жылы су толтырылған ваннаға түсіріңіз. Судың сол бір тылсым, ширығуды басатын күші бүкіл бөлмеге тыныштық орнатып, оның жүйке жүйесін бірден жайландырады. Байқап көріңіз.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'Еденге төгілген тартылыс күші 🍝', 'Тамақты әдейі жерге тастап, соңынан қарап тұр ма? Айқайламаңыз, ол Сізді әдейі ашуландырғысы келмейді, тек тартылыс күшін тексеріп жүр. Тәрелкені алдынан жай ғана алып қойыңыз, тәрбиелеуді кейін жалғастырарсыз.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'Мені Бэтмен деп ата! 🦇', 'Таңертең оянып, өз есімінен бас тартып, басқа атпен атауды талап ете ме? Ойынға қосылыңыз! 5 минут бойы «Мә, Бэтмен, ботқаңды жей ғой» деп, бөлмедегі шиеленісті күлкіге айналдырыңыз.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'Пижаманың резеңкесі мазалайды 👖', 'Пижамасы қысып тұр деп айғайлай ма (шындығында, үстінен түсіп қала жаздайды)? Бұл — сенсорлық сезімталдықтың әсері. «Күте тұр, сиқырлы дұға оқысам, кеңейіп кетеді» деп, пижаманы өтірік созыңыз. Ол бұған сенеді!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'Көзімді жұмсам, жоғалып кетемін 👀', 'Көзін жыпылықтатпауға тырысып, жасаурағанша шыдап жүр ме? Баланың миы кейде түсініксіз қорқыныштарды ойлап табады. «Қарашы, мен көзімді жұмдым, әлі осындамын» деп, осы қисынсыз қорқынышты ойынға айналдырыңыз.'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'Маған тиіспе, ыстық болып кетеді 🛑', 'Кенеттен Сізді құшақтаудан бас тартты ма? Ренжімеңіз! Ол өзінің жеке шекарасын және денесінің тек өзіне тиесілі екенін тексеріп жүр. Бұл — дербестік белгісі, сырттай мақтанышпен бақылаңыз.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'Креслоның астындағы ұйқы 🛋️', 'Төсегіне жатудан бас тартып, креслоның астына бүрісіп ұйықтап қалды ма? Оны ол жерден күштеп шығарып, оятпаңыз. Ерекше әрі қауіпсіз жерде ұйықтаудың рақатын көрсін, Сіз де демалыңыз.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'Жастық түзу емес! 🛏️', 'Жастықты миллиметріне дейін түзету үшін жылап жүр ме? Бұл — мінсіздікке ұмтылу. Оның ережесіне бағынып, жастықты сызғышпен өлшегендей етіп түзетіңіз де, шамды нық қимылмен өшіріңіз.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'Үйдегі тыныштықтан туған үрей 🚪', 'Үй іші кенет тым-тырыс болып кетті ме? Іздеуге шықсаңыз, оны есіктің артында қиялға беріліп отырған жерінен табасыз. Қорықпаңыз, ол шудан алыстап, бойын қайта жинап жатыр. Оған осы уақытты беріңіз.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'Үстел астындағы философия 🤔', 'Үстелдің астына кіріп алып, сол жерден Сізге түрлі оқиғалар ойдан шығарып айтып отыр ма? Кішкентай философ өзінің қиял әлемінде қала берсін, ал Сіз осы уақытты пайдаланып, демалып алыңыз.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'Көрпенің даусы естіледі 🛌', 'Көрпенің сыбдырынан ұйықтай алмай жатыр екен! Біртүрлі сылтаулар шегіне жетті. Үстіне жеңіл көрпе жабыңыз, бәрінің амалын табатыныңызды көріп, ақыры көнеді.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'Шомылуға қарсылық 🛀', 'Суға түскісі келмей ме? Ваннаға түрлі түсті ыдыстарды, тіпті пластик асүй бұйымдарын салып қойыңыз. Сонда су бір сәтте қорқынышты жерден ойын-сауық орталығына айналады.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'Мен — әкемін 👔', 'Таңертең әкесінің үлкен аяқ киімін киіп, жұмысқа барғысы келе ме? Асықпаңыз! Есікке дейін шығарып салыңыз, лифтті көрген бойда күліп, кері қайтады.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', '0 децибелге деген махаббат 🤫', 'Ақыры ұйықтады! Қолданбадағы Дыбыс өлшегішті ашып, көрсеткіштің экранның ең төменгі шегіне түскенін және айналадағы абсолют тыныштықты тамашалаңыз. Бұл көзге көрінетін тыныштық шаршаған миыңызға нағыз спадағыдай әсер етеді.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'Ағаш жапырағын түсіріп алды 🍂', 'Жерде жатқан жапырақ үшін ағашқа ренжіп, оған ұрсып жатыр ма? Оның табиғатпен байланысы сондай пәк әрі күлкілі!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'Көлеңкем менен бұрын кетіп барады 👻', 'Көлеңкесі өзінен бұрын кетіп бара жатқанына көшеде жылап тұр ма? Құшағыңызға алып: «Қараңызшы, көлеңкелер қосылды», — деңіз. Физиканы түсіндірудің орнына, оған жай ғана сенімділік сыйлаңыз.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'Әкенің біртүрлі қалжыңдары 🤡', 'Ұйықтайтын кезде әкесі оны күлдіріп, ұйқысын ашып жіберді деп ашуланбаңыз. Сол көңілді күлкі баланың күні бойы жиналған күйзелісін толық басады, шулап ойнай берсін.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'Жұмыртқа жыламасын 🍳', 'Жұмыртқаны жарғанда оны аяп, жемей қойды ма? Оның жанашырлығында шек жоқ. «Ол енді сенің бұлшықеттеріңде өмір сүреді» деген сияқты сүйкімді қиялмен жағдайдан шығып көріңіз.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'Сыбырлап ойнау 🤫', 'Ұйықтағысы келмей, қашып жүр ме? Даусыңызды бірден бәсеңдетіп, сыбырлап сөйлеңіз. Сізді есту үшін бар зейінін салады да, миы шаршап, 5 минуттан кейін ұйқыға беріледі.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'Денеңіздің дабылы 🩸', 'Себепсіз ашушаңдық пен шаршауға бой алдырмаңыз. Етеккір бақылағышын тексеріңіз: денеңіз белгі беріп жатыр. Өзіңізді кінәлаудың орнына, Пайдалы рецептерден магнийге бай тіскебасар таңдап, демалыңыз.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'Тек қызыл тағамдар 🍅', 'Бүгін — ерекше қалау күні! Тек қызыл түсті тағамдарды сұрай ма? Тамақтану жоспарын қарап, бүгін оған қызыл қызанақ пен құлпынай беріңіз. Осы бір қызық қалауы орындалсын, қарсыласпаңыз.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'Ойыншығым ауырып қалды 🩺', 'Қонжығын ауруханаға жатқызды ма? Сіз де ауырып қалыңыз! Диванға жатып, Сізді де 10 минут өтірік тексеруіне мүмкіндік беріңіз. Осы сылтаумен арқаңыз да тынықсын.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', '«Менімен бірге жатшы» деген өтініш 🫂', 'Қасына жатып ұйықтауыңызды талап ете ме? Бір күнге ережені бұзып, иісін құшырлана жұтып, онымен бірге ұйықтаңыз. Бұл — екеуіңізге де махаббат терапиясы.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'Жасанды интеллект, маған көмектесші 🤖', 'Балаңыздың толассыз философиялық сұрақтары Сізді әбден шаршатты ма? Anacan AI-ға жазыңыз: ол Сіздің орныңызға 4 жасар балаға лайық ғылыми, байсалды әрі сүйкімді жауаптарды бірден дайындап береді.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'Айнадан өзімді танымай қалдым 🪞', 'Айнаға қарап, бет әлпетін өзгертіп, өз-өзіне ашуланып жүр ме? Оның өзіндік «Мені» мен эмоциялары қалыптасып келеді. Осы әртістігін сырттай үнсіз бақылаңыз.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'Жұрт маған не дейді? 💬', 'Бәрін дұрыс істемей жүрмін деп ойлайсыз ба? Anacan қауымдастығына кіріп, басқа аналардың тентек балалары туралы оқиғаларын оқыңыз, терең тыныс алыңыз да, өз балаңызға шүкір етіңіз!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'Бөлмені тас қараңғы етіңіз 🌙', 'Дәлізден түскен жарықтан ұйықтай алмай жүр ме? Демек, оған мінсіз қараңғылық керек. Есікті мықтап жауып, бөлмені толық қараңғылаңыз. Мелатонин табиғи жұмысын атқарып, оны ұйқыға батырсын.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'Көрінбейтін дақтың әлегі 👕', 'Шалбарынан дақ іздейді, бірақ онда ештеңе жоқ па? Бұл тағы да көзге көрінетін нәрселерге қатысты қырсықтығы. Дымқыл майлықпен өтірік сүртіп, «кетіп қалды» деңіз. Баланың миы мұндай иллюзияға тез сенеді.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'Сіз әрірек отырыңыз 🛑', 'Кереуетінің жанында емес, алыста, есік алдында отыруыңызды талап ете ме? Ренжімеңіз! Бұл — оның дербестікке қарай жасаған үлкен қадамы, іштей қуануыңыз керек.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'Терезедегі құс менікі 🐦', 'Ауладағы құсты үйге әкелгісі келіп, жылап жатыр ма? Табиғатқа деген сүйіспеншілігі арнасынан асып тұр. «Оны анасы үйінде күтіп отыр» деген оқиға бұл дағдарысты әп-сәтте тыныштыққа айналдырады.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'Түнгі қорқыныштар басталады 👻', 'Кереуеттің астындағы құбыжықтан қорқа ма? Бос бүріккіш бөтелкеге су құйып, бөлмеге құбыжықтарды қуатын сиқырлы спрей сияқты шашыңыз. Қорқынышы әп-сәтте ғайып болады.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'Тісімді саусағым тазаласын 🪥', 'Тіс щеткасынан бас тартып, тісін міндетті түрде саусағымен тазалағысы келе ме? Қарсы болмаңыз: аздап тіс пастасы жағылған таза саусақпен де тазалауға болады. Мұны үлкен мәселеге айналдырмаңыз.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'Жасырын жеген шоколадтың дәмі 🍫', 'Балаңыз теледидар көріп отырғанда, асүйде одан жасырынып шоколад жеп тұрсыз ба? Асыңыз дәмді болсын! Осыншама дағдарысқа төтеп беру үшін бұл — Сіздің ең табиғи қуат көзіңіз. Өзіңізді кінәламаңыз.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'Ертегідегі кейіпкер — мен! 🪄', 'Тәрбиелік ертегілердегі кейіпкердің атын балаңыздың атымен ауыстырыңыз. Ертегіде кейіпкердің тез әрі тілалғыш болып ұйықтайтынын естіген балаңыз да соған еліктеп, дәл солай жасауға ынталанады.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'Дүкеннің ортасында абдырап қалмаңыз 🛒', 'Дүкенге кіріп, не алатыныңызды ұмытып қалдыңыз ба? Сатып алатын заттардың тізімін электронды түрде жүргізбесеңіз, сол қарбаласта бәрін ұмытып кетуіңіз мүмкін. Цифрлық жадыңызға әрдайым сеніңіз.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'Түнде жұлдыз санау 🌟', 'Балаңыз жатын бөлменің төбесіне қарап, қиялындағы жұлдыздарды санай ма? Санай берсін. Сол қиялдағы жұлдыздардың саны 10-ға жеткенше-ақ көзі ілініп, терең ұйқыға кетеді.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'Қолым аяққа айналды 🤸‍♂️', 'Балаңыз қолымен жүруге тырысып, құлап қала ма? Бұл — қимыл-қозғалыс дағдылары мен шығармашылығының қарқынды дамып жатқанының белгісі! Үйдің қауіпсіз жерінде оған шағын кедергілер жолағын жасап беріңіз, энергиясын жұмсасын.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'Әкенің үнсіз келуі 👨‍🍼', 'Сіз ертегі оқып әбден шаршаған сәтте әкесі бөлмеге үнсіз кіріп, баланы сипап, Сізге барып демал деген ишара жасайды. Бұл — ата-ана болудағы нағыз командалық жұмыс сәті.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'Бананды дұрыс аршымадыңыз 🍌', 'Сылтаудың нағыз шебері! Бананды Сіз аршығаныңыз үшін балаңыз шу шығарды. Оған жаңа банан беріңіз де, қалағанынша, тіпті ортасынан сындырып болса да, өзі аршысын — дербестігіне нұқсан келмесін.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', '«Күн тым ыстық!» деген қарсылық 🧥', 'Балаңыз көшенің ортасында күртесін шешіп тастайды, ал Сіз оның тоңып қалуынан қорқасыз ба? Таласпаңыз: шынымен тоңса, өзі келіп күртесін сұрайды. Әрекетінің салдарын өзі сезініп көрсін.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'Мен орындықпын 🪑', 'Балаңыз өзін бір зат ретінде таныстырып, қимылсыз тұра ма? Үстіне ойыншықты жай ғана қойып, «Қандай әдемі орындық!» деңіз. Бұл қызық рөл оған қатты ұнайды әрі ол біраз уақыт тыныш тұрады.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'Теріс киілген жейде еркіндігі 👕', 'Жейдесін теріс киіп алып, мақтанышпен жүр ме? Түзетпеңіз! Оның өзіне деген сенімі соншалықты жоғары — сырттай қарап, еркін рухты болашақ көшбасшыңызды мақтан тұтыңыз.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'Үнсіз ұғынысу 🥂', 'Бала ұйықтады, ал Сіз жұбайыңызбен диванда үнсіз бір-біріңізге қарап отырсыздар. Ештеңе айтпайсыздар. Шын мәнінде, бұл үнсіздік — «мұны да еңсердік» деудің ең романтикалық жолы.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'Мені жел итерді 💨', 'Сырттағы желге ашуланып, оны ұрғысы келе ме? Ауа райы мен киім құралын алдын ала қарап қойсаңыз, бәлкім, үйден мүлде шықпас едіңіз. Ал қазір осы қызыққа күліп, үйге қарай жүгіріңіздер.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'Едендегі өнер 🎨', 'Бөлменің ортасында құрғақ макароннан сурет жасап, Сізге мақтанышпен қарап тұр ма? Жинауды қоя тұрып, оған күлімсіреңіз.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'Әкенің ұйықтататын ертегісі 📖', 'Даусыңыз шаршап, ертегі оқығыңыз келмей ме? Кезекті әкесіне беріңіз. Оның өзгеше жуан даусы мен ойдан шығаратын қисынсыз қызықтары баланы тезірек ұйықтатады.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'Шашым ауырып тұр 🪮', 'Шашын тарау өліммен тең бе? Су бүріккішпен сәл дымқылдап, назарын айна алдында жасап тұрған күлкілі бет қимылдарыңызға аударыңыз. Ойы бөлінген сәтте шашын тез тарап алыңыз.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'Денем өзімдікі емес 🔋', 'Күні бойы үстіңізге өрмелей бергеннен денеңіз жансызданып қалғандай ма? Баланы бөлмеде 5 минутқа жалғыз қалдырып, есікті жауып, көзіңізді жұмыңыз да, терең тыныс алыңыз. Сізге күш жинау керек.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'Мені бала демеңіз! 😤', '«Мен өстім» деп, бөлмеде Сізге өз ережелерін орнатып жүр ме? Ол енді есейгенін дәлелдеуге тырысып жүр. Оған «жақсы, жас ханым/мырза» деп, үлкен адамдай сөйлесіңіз әрі құрметіне ие болыңыз.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'Жаңбыр үнімен ертегі 🌧️', 'Даусыңыз шықпай, ертегі оқуға шамаңыз жоқ па? Ақылды ертегілерден тек жаңбыр мен орман дыбысын фон ретінде қосыңыз. Табиғаттың осындай тыныштығы кейде ең жақсы ертегіден де тез ұйықтатады.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'Қолымнан ұстама! 🚶‍♂️', 'Жолда қолыңызды жіберіп, өзі еркін жүргісі келе ме? Егер қауіпсіз жерде болсаңыздар, дербестігін байқап көрсін. Ал Сіз екі қадам артта жүріп, оны мақтанышпен бақылаңыз.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'Нанның шеті — жау 🍞', 'Ортасын жеп, шеттерін қасарыса алып тастай ма? Нанның қабығымен күреспеңіз. Жануар пішінді қалыптармен кесіп, қабықсыз бейнелер жасаңыз. Бөпеңіз тағамның қызықты безендірілуінен ләззат алсын.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'Үйден шыққысы келмейді ⛅', 'Төрт қабырға қысып барады, ал ол жылап, далаға шыққысы келмей ме? Ауа райы мен киім таңдау құралына сеніп, қарсылық танытса да, далаға алып шығыңыз. Таза ауамен тыныстаған бойда үйде жиналған ашу-ызасы әп-сәтте басылады.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'Әкесімен пижамалы күрес 🤼‍♂️', 'Ұйықтағысы келмей ме? Әкесі онымен ойнап, қабырға жанында әдейі жеңілген кейіп танытсын. Бөпеңіз терлеп, бойындағы соңғы күшін де жұмсайды да, төсегіне жүгіріп барады.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'Қауымдастықтан күш алу 💬', 'Шыдам таусылғанда, Anacan қауымдастығына кіріңіз. Ондағы аналардың да дәл осындай бейберекет кезеңді бастан өткеріп жүргенін көргенде, көңіліңіз жайланып, жалғыз емес екеніңізді сезінесіз.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'Мұны да еңсердік! 🚀', 'Бүкіл үй ұйқыда. Келесі айдағы жаңа қарбаласқа дайынсыз — Сіз бұл істің нағыз шеберісіз. Жарықты өшіріп, бүгін жасаған барлық кішкентай ғажайыптарыңыз үшін өзіңізге алғыс айтыңыз.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'Мына көлеңке менікі 👻', 'Өз көлеңкесін меншіктеп алып, онымен сөйлесіп, оған нұсқау бере ме? Оның қиялында шек жоқ.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'Менің цифрлық терапиям 🤫', 'Үйдегілер ұйықтап қалды, ал миыңыз әлі де у-шуға толы ма? Дыбыс өлшегішті қосыңыз. Бөлмедегі 0 децибел деген жазуға қарау Сізді психолог сеансынан да жақсы тыныштандырады, байқап көріңіз.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'Ойыншықтарын ұйықтату 🧸', 'Өзі ұйықтамай, ойыншықтарын бір-бірлеп төсекке жатқызып, үстін жауып жүр ме? Бұл рөлдік ойын шын мәнінде оны психологиялық тұрғыдан өз ұйқысына біртіндеп дайындайды, араласпаңыз.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'Неге есікті Сіз аштыңыз? 🚪', 'Есікті Сіз ашқаныңыз үшін жылап, өзі ашу үшін қайта жапқызғысы келе ме? Оған 1 минут жұмсалса да, рұқсат етіңіз. Есесіне үйде болатын 20 минуттық айқай мен бүліктің алдын бейбіт жолмен аласыз.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'Тек жасыл түс! 🥦', 'Тәрелкеден тек жасыл тағамдарды іздей ме? Тамақтану жоспарын қарап, көк шөптерден тәтті пішіндегі жасыл көкөніс түйіршіктерін жасауды үйреніңіз және оның осы бір қызық әуестігін қанағаттандырыңыз.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'Аспан қайда кетті? ☁️', 'Тұманды күні оның кенеттен қойған философиялық сұрағы Сізді тығырыққа тіреді ме? «Аспан тоңып қалмасын деп, бұлттар оны жауып қойды» деңіз. Оның санасы ғылыми түсіндірмеге әлі дайын емес, оған қазір жай ғана ертегі керек.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'Дүкеннің ортасында жүгіру 🛒', 'Касса алдында кенет жүгіріп кетіп, сөрелердің артына тығыла ма? Осындай абыр-сабыр сәттерде не сатып алмағаныңызды ұмытып, үйге құр қол қайтпау үшін сатып алу тізімін цифрлық түрде жүргізіңіз.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'Сыбырлау ойыны 🤫', 'Айқайлап жүгіріп, ұйықтағысы келмей ме? Кенет даусыңызды мүлде бәсеңдетіңіз. Өте ақырын сыбырлап сөйлей бастаңыз. Ол Сізді есту үшін бар назарын жинақтап, біртіндеп ұйқысы келе бастайды.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'Мен мінсіз ана емеспін 🛑', 'Бүгін бәрі астан-кестен болып, айқайлап жібердіңіз бе? Өзіңізді жазғырмаңыз. Көңіл күй күнделігіне жай ғана былай жазыңыз: Бүгін күнім сәтсіз өтті, бірақ мен жақсы анамын және ертең қайтадан тырысамын.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'Әке ойлап тапқан қаһарман 🦸‍♂️', 'Сөйлеуге зауқыңыз жоқ, кітап оқуға да деміңіз жетпей тұр ма? Бұл істі әкесіне тапсырыңыз. Әкесі басты кейіпкері баланың өзі болатын ойдан шығарылған, қисынсыз бір оқиға айтып берсін. Ал Сіз диванға жайғасып, бөлмеден естілген сыңғырлаған күлкіні тыңдаңыз.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'Шұлықты теріс кию қырсықтығы 🧦', 'Шұлықтың өкшесін аяғының үстіне келтіріп киіп алды да, түзетуге мүлде жол бермей ме? Солай қалдырыңыз. Оның «мұны өзім істедім» деген мақтанышы шұлықты дұрыс киюден миллион есе құнды.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'Тағы бір жұтым су деген сылтау 💧', 'Енді ұйықтап бара жатқанда «Қатты шөлдедім» деп төсектен атып тұра ма? Мақсаты су ішу емес, Сізбен тағы біраз уақыт өткізу. Төсегінің жанына алдын ала төгілмейтін су құтысын қойып, осы әйгілі айланың алдын алыңыз.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'Шаршадым, бірақ айтпаймын 📝', 'Бүгін қаншалықты күйзеліске түскеніңізді ешкім байқамай, ал бәріне күлімсіреу жаныңызды қысып жүр ме? Көңіл күй күнделігін ашыңыз. Ішіңіздегі бар уыт пен ашуды экранға төгіңіз. Осылайша цифрлық түрде ішіңіздегіні ақтару психологке барғаннан да тезірек жеңілдетеді.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'Күртеше үшін күрес 🧥', 'Сыртта күн ашық, бірақ ол күртешесін кигісі келмейді. Терезеден қарап алданып қалмаңыз: оған «Ауа райы және киім» құралындағы нақты температураны және бірнеше қабат киінген баланың суретін көрсетіңіз. Ережені түсіндіруді телефонға тапсырыңыз.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'Құс неге маған қарамады? 🐦', 'Саябақта бір көгершін ұшып кеткені үшін өксіп жылады ма? Мұндай сәтте қисын іздемеңіз. Бұл ол үшін шынымен де үлкен көңіл қалу. «Ол да сені қатты сағынатын болады» деп, оның сезімін сүйіспеншілікпен қабылдаңыз.'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'Ертегіде менің атым болсын 🪄', 'Классикалық кітаптардағы кейіпкерлерден жалықты ма? Ақылды ертегілердегі басты кейіпкердің атын оның атымен ауыстырыңыз. Өзінің қалай батыл ұйықтағанын естігенде, бөлмеде еш қарсылықсыз тәтті ұйқыға кетеді.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'Бүгін мен көлікпін 🚗', 'Таңертең Сізге «Мен бала емеспін, көлікпін» дей ме? Қатаң ереже қоймаңыз. «Онда жылдам жүгіруің үшін жанармайыңды (ботқаңды) құйып алайық» деңіз. Мұндай күлкілі рөлдік ойындар айқайлағаннан әлдеқайда оңай.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'Құмнан пісірілген торт 🏖️', 'Саябақта су мен топырақты араластырып, үсті-басын балшық қылып, Сізге торт дайындады ма? Тазалықты қоя тұрыңыз. Бұл — ұсақ моторика мен шығармашылықтың дамуы.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'Кірпік қақпау жарысы 👀', 'Ұйықтағысы келмей, көзін әдейі бақырайтып Сізге қарап жатыр ма? «Кім көзін бірінші жұмса, сол жеңіледі» ойынын ойнаңыз. Көзі жасаурап, бәрібір шаршайды да, 2 минуттан кейін өзінен-өзі жұмылады. Байқап көріңіз!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'Төсектегі жасырын ойыншықтар 🧸', 'Төсегіне жатқанда астынан 3 қатты ойыншық мәшине шықты ма? Ол оларды қорғап, бірге ұйықтап жатыр. Уайымдамаңыз, ұйықтап кеткеннен кейін 10 минуттан соң сол батып жатқан заттарды білдірмей алып тастап, жайлы ұйықтауына жағдай жасайсыз.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'Қауымдастықтағы үнсіз жұбаныш 💬', 'Қатты шаршағаныңыз сонша, тіпті ешкімге ішіңіздегіні айтқыңыз келмей ме? Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың дәл сондай қисынсыз дағдарыстарды қалай еңсеріп жүргенін көру Сізге ең күшті үнсіз жұбаныш болады.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'Дұрыс емес қасық дағдарысы 🥄', 'Сорпаны үлкен қасықпен бергеніңіз үшін төңкеріс бола жаздады ма? 4 жасқа таяғанда тағам бірдей болса да, баланың түсінігінде ыдыстың көлемі оның дәмін өзгертіп жібереді. Дауласпай-ақ, қасықты бірден ауыстырып, күшіңізді сақтаңыз.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'Диванға үнсіз жайғасу 🥂', 'Бала ұйықтады, үй жиналды. Жұбайыңызбен диванға қатар отырыңыздар, тіпті теледидарды да қоспаңыздар. Бір-біріңізге жай ғана «Мұны да еңсердік, аман қалдық» деген көзқараспен қараңыздар. Сеніңіз, ата-ана болудың ең романтикалық әрі шынайы сәті — осы.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'Жасыл түске деген сүйіспеншілік 🥦', 'Тәрелкеден тек жасыл тағамдарды іздеп, басқа түстегілерін ысырып қоя ма? Пайдалы рецепттерді қарап, көкөніктерден тәтті пішінді жасыл түйіршіктер жасауды үйреніңіз.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'Есікті неге Сіз жаптыңыз? 🚪', 'Үйден шығарда есікті Сіз жапқаныңыз үшін айқайлап жылап, оны қайта ашқызды ма? Бәрін өзі бақылап отырғанын сезіну — оның ең үлкен қажеттілігі. Сізге 1 минут жоғалттырса да, есікті өзі жапсын. Осылайша көшеде болатын 30 минуттық жылау дағдарысының алдын аласыз.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'Асфальттағы сызықтар — заң 🛣️', 'Көшеде келе жатып, тас арасындағы сызықтарды баспау үшін оғаш қимылдар жасай ма? Бұл кезде ірі моторикасы мен зейіні қатар жұмыс істейді. Асықтырмаңыз, қолынан ұстап, сол сызықтардан бірге секіріп өтіңіз.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'Су ағатын тесіктен қорқу 🛁', 'Ваннадан шыққанда су ағып кететін тесіктен қорқа ма? Оның қиялы ақылға сыймайтын нәрселерді елестетуі мүмкін. Сол жерге пластик ойыншық кеме қойып: «Қарашы, бұл — қорғаушы, ол ештеңені тартып әкетпейді», — деңіз. Сол сәтте қорқыныш ойынға айналады.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'Таңғы сағат 6-да басталатын концерт 🎤', 'Көзін аша сала ойдан шығарған әнін бар даусымен айта ма? «Тыныш, көршілер оянады», — деп сол тасыған қуатын баспаңыз. Сіз де қосылыңыз. Таңын әнмен бастаған бала күні бойы азырақ ашуланады.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'Тыныштықтың 0 децибелдік биі 🤫', 'Ақыры бөлме қараңғы, ал бөпеңіз ұйықтап қалды. Үйде құлақ тұнатындай тыныштық орнады. Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы көрсеткіштің 0 децибелге түскенін бақылау — шуылдан шаршаған миыңызға жасалған нағыз цифрлық массаж.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'Менің ойыншығым Сізге ренжіді 🧸', 'Сіз айқайлаған соң қасыңызға келіп: «Аюым Сізге ренжіді», — деді ме? Ол өз сезімдерін заттарға теліп, Сізге осылай жеткізіп тұр. Аюдан барынша байыппен кешірім сұрап, оны құшақтаңыз. Балаңыздың қалай тынышталғанын көресіз.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'Шай неге бу шығарады? ☕', 'Кесеңізден көтерілген буға қарап, Сізден түсініктеме сұрай ма немесе одан қорқа ма? Ғылыми тұрғыда түсіндіре алмайсыз ба? Anacan AI-дан 4 жастағы балаға лайық философиялық әрі сүйкімді түсініктеме алыңыз: «Ол бұлттарға қосылу үшін ұшып барады».'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'Тізімге жасырын шабуыл 🛒', 'Дүкенге барар алдында қолданбадағы Сатып алу тізімін ашып, онда 5 шоколад жазылғанын көрдіңіз бе? Иә, ол телефоныңызға кіруді және цифрлық әлемдегі әрекеттеріңізді қайталауды әлдеқашан үйреніп алған.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'Бүтін алма драмасы 🍏', 'Алманы турап бергеніңіз үшін бөлмеде айқай-шу басталды ма? «Мен оны бүтіндей қаладым!» — деп жылай ма? Бұдан қисын іздемеңіз. Тілімдерді бір-біріне қосып: «Қарашы, қайтадан бүтіндедім», — деңіз де, осы мағынасыз драмадан дипломатиялық жолмен шығып кетіңіз.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'Айнадағы анау бала кім? 🪞', 'Айна алдында тұрып, өзіне-өзі қабағын түйіп, ашулы әрі қызық кейіп танытып жүр ме? Ол эмоциялардың жүзінде қалай көрінетінін зерттеп жатыр. Дыбыс шығармай, осы кішкентай театр әртісінің жаттығуын сүйсіне тамашалаңыз.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'Жарықты өшіріп, көлеңкені табыңыз 🔦', 'Қараңғыдан қорқып, төсекке жатқысы келмей жүр ме? Бөлменің жарығын толық өшіріп, кішкентай қолшамды жағыңыз. Қолыңызбен қабырғаға иттің, құстың көлеңкесін түсіріңіз. Қорқынышты қараңғылықты ол үшін театрға айналдырсаңыз, ұйықтауы жеңілдейді.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'Қабырғаға салынған жауһар 🖍️', 'Бірнеше секундтық тыныштықтан кейін оның қабырғаға фломастермен өнер туындысын салып жатқанын көрдіңіз бе? Терең тыныс алыңыз. Ұсақ моторикасы дамып жатыр, ал қабырғаны бәрібір тазалауға болады. Бұл жауһарды өшірмес бұрын міндетті түрде суретке түсіріп алыңыз.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'Әкенің арқасындағы ат ойыны 🐴', 'Күш-қуатын толық шығара алмай, төсекке жатуға қарсыласып жүр ме? Әкесін көмекке шақырыңыз. Әкесі баланы арқасына мінгізіп, ат болып шапқанда, бөлме күлкіге толып, жиналған дене ширығуы бірнеше секундта термен бірге басылады.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'Дәретханаға 5 минутқа қашу 🚪', 'У-шу миыңызды тесіп бара жатқандай болып, бәріне айқайлағыңыз келе ме? Оны қауіпсіз жерге қалдырып, дәретханаға кіріңіз де, есікті жабыңыз. Бар болғаны 5 минут қабырғаға қарап, ештеңе істемеңіз. Осы қысқа тыныштық өзіңізді қайтадан қалыпты адамдай сезінуге көмектеседі.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'Ботқа тым дөңгелек 🥣', 'Тамақтың пішініне ашуланып, жеуден бас тартып жүр ме? Логика іздемей-ақ, ботқаны қасықпен араластырып: «Қараңыз, түзеттім», — деңіз. Иллюзия өнері ана болғанда Сізге әрдайым қажет болады.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'Себепсіз көз жасы 😭', 'Саябақтан қайтып келе жатып, жолдағы бір тасты тебе алмағаны үшін ақырзаман орнағандай болды ма? Мұнда логика жоқ, ол жай ғана шаршады. Дауласпай, құшағыңызға алыңыз, сезімін мойындап, назарын басқа жаққа аударыңыз.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'Сыбырлап айтылған ертегі сырлары 🤫', 'Төсекке жатпау үшін түрлі сылтау ойлап тауып жүр ме? Даусыңызды барынша бәсеңдетіп, тек сыбырлап сөйлей бастаңыз. Сізді түсіну үшін ол бар назарын аударуға мәжбүр болады да, миы көп ұзамай ұйқыға көшеді.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'Дүкен ортасында абдырап қалу 🛒', 'Дүкенге кіріп, не алатыныңызды ұмытып қалдыңыз ба? Сатып алатын заттар тізімін цифрлық түрде сақтамасаңыз, сол қарбаласта бәрін ұмытасыз. Үйге құр қол қайтпау үшін қолданбадағы цифрлық жадыңызға әрдайым сеніңіз.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'Сіз менімен ойнамайсыз! 😤', 'Сіз тамақ араластырып жатқанда, ол келіп, бетіңізді қолымен өзіне бұрады: Маған қараңызшы!? Ол дұрыс айтады. Оған сіздің қасында болғаныңыз ғана емес, бар назарыңыз қажет. Жұмысыңызды қоя тұрып, небәрі 2 минут бойы көзіне қарап, мұқият тыңдаңыз.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'Жаңбыр үні естілетін бөлме 🌧️', 'Даусыңыз шықпай, ертегі оқуға шамаңыз жоқ па? Ақылды ертегілерден тек жаңбыр мен орман дыбысын фон ретінде қосыңыз. Табиғаттың бірқалыпты тыныштығы кейде ең жақсы ертегіден де тезірек ұйықтатады.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'Өзі ойлап тапқан есіммен атау 🦇', 'Таңертең оянып, өз есімінен бас тартып, Мені Бэтмен деп атаңыз деп талап қойды ма? Ойынға қосылыңыз! 5 минут бойы Мә, Бэтмен, ботқаңды же деп, бөлмедегі шиеленісті әп-сәтте күлкіге айналдырыңыз.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Instagram-дағы аналардан шаршау 📱', 'Instagram-ды ашқан бойда бәрінің мінсіз баласын көріп, көңіліңіз түспесін! Ол қолданбаны жауып, Anacan қауымдастығына кіріңіз. Басқалардың да үйі сіздікіндей астан-кестен болып жатқанын көріп, терең тыныс алыңыз — сіз жалғыз емессіз.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'Барлық күйзелісті сумен шайып жіберу 🛀', 'Кейде ештеңе көмектеспейді, бөпе бәріне жылай береді. Оны жылы су толтырылған ваннаға түсіріңіз. Судың сол бір тылсым, ширығуды басатын әсері бүкіл бөлмеге де, оның жүйке жүйесіне де бірден мол тыныштық сыйлайды.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'Кетіңіз, сізді қаламаймын 💔', 'Өтінішін орындамағаныңыз үшін ол сізге Жаман анасыз, кетіңіз! деді ме? Жүрегіңіз сыздап кетті. Бірақ ол әлі ашуын сөзбен жеткізе алмайды, шын мәнінде Көңілім қалды деп тұр. Мұны өзіңізге қабылдамаңыз, жай ғана мейіріммен құшақтаңыз.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'Көрінбейтін досымен шай ішу 🫖', 'Бөлменің бұрышында бос кеңістікке шай құйып, күліп отыр ма? Қиялдағы дос кезеңі басталды!'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'Неге ән айтуыма кедергі жасадың? 🎶', 'Фонда ойнап тұрған балалар әніне ыңылдап қосылып едіңіз, ол бірден: Ән айтпа!? деп айқайлады. Бөлмедегі жалғыз әнші — өзі, ал Сіздің вокалдық талпыныстарыңыз оның сахнасына кедергі келтіреді. Ренжімеңіз, сахнаны осы кішкентай өзімшілге бере салыңыз.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'Киімін өзі таңдайды 👗', 'Қызыл шалбар, спорттық аяқ киім және қысқы бас киім... Саябаққа дәл осылай барамын деп қасарысады. Жұрт не дейді деп уайымдамаңыз. Өз таңдаған киімімен шыға берсін, ол үшін бұл еркіндік сыртқы үйлесімнен маңыздырақ.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'Таймермен ұйықтау келісімі ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен шөлдеп немесе қабырғамен қоштаса бастай ма? Таймер қойыңыз. Қоңырау соғылғанда бәрі ұйықтайды деген ереже енгізіңіз. Сыртқы бір беделге бағыну оларға әрдайым оңайырақ.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'Ай неге әлі кетпеген? 🌙', 'Таңертең аспандағы айды көріп, Ай неге ұйықтамаған? деп сұрады ма? Ғылыми терминдермен басын қатырмаңыз. Anacan AI-ды ашыңыз, ол осы жасқа лайық сүйкімді астрономиялық ертегіні тауып береді. Оны оқып беріп, бөпеңіздің қызығушылығын қанағаттандырыңыз.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'Нанның тек шетін жейді 🍞', 'Нанның тек қабығын жеп, жұмсағын тастай ма? Тамаққа қатысты мұндай кереғар талғам Сізге таныс болар. Нан қабығы үшін күреспеңіз. Тамақтану жоспарынан нанды қалыптармен кесіп, оған әртүрлі жиек жасауды үйреніңіз.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'Мелатонин үшін қараңғылық 🌌', 'Тезірек ұйықтауы үшін ұйықтардан 1 сағат бұрын бөлмедегі барлық теледидар мен телефон экрандарын өшіріңіз. Мелатонин (ұйқы гормоны) қараңғы ортада ғана жылдам бөлінеді, табиғи үдеріске сеніңіз.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'Ойыншықтар неге ұйықтамайды? 🧸', 'Өзі ұйықтамайды, бірақ барлық ойыншығын бір-бірлеп төсекке жатқызып, үстін жауып шыға ма? Бұл рөлдік ойын шын мәнінде оны психологиялық тұрғыдан өз ұйқысына біртіндеп дайындайды, еш кедергі жасамаңыз.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'Тек иісін терең жұтыңыз 🫂', 'Бүгін Сізді шынымен есіңізден тандырып, бар күшіңізді сарқып жіберді ме? Бірақ төсекте сондай бейкүнә ұйықтап жатыр... Жарықты өшіріңіз. Жанына жатып, сәбиге тән сол жұпар иісті терең жұтыңыз да, қараңғыда оны жақсы көретініңізді сыбырлаңыз.'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'Әкесі қате оқыған ертегі 📖', 'Бүгін кешке ертегі кітабын әкесіне беріңіз. Әкесі оқиғаны әдейі бұрмалап, күлкілі әрі қисынсыз етіп айтып берсін. Балаңыздың оны түзеткеніне мәз болып, қарқылдап күлгенін сырттай сүйсіне бақылаңыз.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'Таңғы қуаласпақ 🏃‍♂️', 'Таңғы сағат 7-де дивандардың үстімен жүгіріп жүр ме? Айқайламаңыз. Шаруаңызды 2 минутқа қоя тұрып, өзіңіз де секіріп, оған қосылыңыз. Баланың қиял әлеміне ену — өзіңіз үшін де күйзелістен арылудың ерекше бір тәсілі.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'Кенеттен тұтығуға алаңдау 🤖', 'Балаңыздың кенеттен тұтыға бастауы Сізді интернеттен түрлі ауруларды іздеуге итермеледі ме? Тоқтаңыз! Anacan AI-дан мұның 4 жастағы даму секірісі екенін біліп, уайымыңызды басыңыз.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'Экрандағы тыныштық көрсеткіші 📉', 'Ақыры ұйықтады. Үйдің тынышталып кеткені сонша, құлағыңыз шыңылдап тұр ма? Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 desibel деген жазуға қарау шаршаған, шудан қажыған миыңыз үшін әлемдегі ең жақсы визуалды массаж болады.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'Бананды Сіз аршығаннан туған жанжал 🍌', 'Бананды Сіз аршып қойғаныңыз үшін бөлмеде төңкеріс басталды ма? Бұл жастың алтын ережесі: бәрін өзі шешуі керек. Бананның қабығын қайта жабыстыра алмайсыз, сондықтан жаңасын беріп, өзі қалағандай аршысын — дербестік сезіміне нұқсан келмесін.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'Жиекжол үстіндегі арқанмен жүруші 🧱', 'Саябаққа барарда тегіс жолмен емес, міндетті түрде жиектастың ең жіңішке тұсымен жүргісі келе ме? Қолынан ұстап, қауіпсіздігін қамтамасыз етіңіз де, осы кішкентай шыңды бағындыруына мүмкіндік беріңіз. Осылайша тепе-теңдік пен өзіне деген сенімі қатар тамаша дамиды.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'Өзіңізге уақыт бөлу — айып емес 🥗', 'Оны тамақтандыру үшін түрлі мәзір ойлап таптыңыз, ал өзіңіз не жедіңіз? Пайдалы рецептілер арасындағы аналарға арналған оңай 5 минуттық салатты дайындап, өз күш-қуатыңызды толықтыруды да ұмытпаңыз.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'Бір-біріңізге үнсіз қарау 🥂', 'Бала ұйықтады. Сіз бен жұбайыңыз диванда бір-біріңізге үнсіз қарап отырсыздар. Ештеңе айтпайсыздар. Шын мәнінде, бұл тыныштық — «Мұны да еңсердік, біз керемет командамыз» деудің ең романтикалық әрі шынайы жолы.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'Суды кептіруді талап ету 💧', 'Стақандағы суды ішудің орнына: «Бұл тым су, кептіріп бер!» деп айқайлай ма? Логика іздемей-ақ, суды басқа түсті стақанға құйып: «Міне, құрғақ су әкелдім», — деңіз. Иллюзия өнері — ана ретіндегі ең мықты қаруыңыз.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'Табиғатқа міндетті түрде шығу ⛅', 'Төрт қабырғаның арасында энергиясы агрессияға айналып, әр сөйлемін «жоқ» деп бастай ма? Ауа райына сай киіндіріп, міндетті түрде далаға алып шығыңыз. Топырақты ұстау оның жүйке жүйесін бірден тыныштандырады.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'Қоңырау үнімен автоматты түрде ұйықтау ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен дәретханаға барғысы келе ме? Таймер қойыңыз. «Қоңырау соғылғанда бәрі жарықты өшіреді» деген ережені енгізіп, осы бітпейтін қоштасу мен шебер айла-шарғыдан даусыз құтылыңыз.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'Есіктің артына тығылып ойнау 🙈', 'Балабақшаға кешігіп барасыздар, ал ол перденің артына тығылып: «Мені тап!» — дей ме? Айқайлау бәрін одан әрі созады. «Менің бөпем қайда екен?» — деп, 2 минуттық ойынға қосылыңыз да, оны жасырынған жерінен күліп шығарыңыз.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'Ақылды ертегідегі ерекше дыбыс әсерлері 🪄', 'Ақылды ертегілерді қосыңыз. Оқиғаны оқығанда есіктің сықырын, желдің гуілін және сыбырды салып, бөлмеде дыбыс театрын ұйымдастырыңыз. Бұл ерекше дыбыстар оның назарын бірден ертегі әлеміне тартады.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'Экран үшін өзіңізді кінәламаңыз 📺', 'Бүгін шаруаңыз көп болып, ол теледидар алдында ұзақ отырды ма? Өзіңізді кінәлі сезініп жүрсіз бе? Күн сайын мінсіз болу мүмкін емес. Кейде экрандар бізді үлкен бейберекеттіктен құтқаратын ең зиянсыз күтуші болады, алаңдамаңыз.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'Өз туындысын жыртқан суретші 🖍️', 'Салған сызығы ұнамай, «Жаман болып қалды», — деп қағазды жыртып тастай ма? Бұл өзін-өзі сынау мен мінсіздікке ұмтылу сезімі қалыптасып келе жатқанын білдіреді! «Келесі жолы басқа түсті қолданып көрейік», — деп, оның көңілсіздігін жаңа ізденіске айналдырыңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('bcac5731-4815-4adc-beb4-861e3ff078b1'::uuid, 'Мысық сияқты үйкелу 🐾', 'Бүгін таңертең ол төрт аяқтап жүріп, аяғыңызға үйкеліп, тек «мияу» деп қана айта ма? Оған ереже түсіндірудің орнына, қиялыңыздағы сүт құйылған ыдысты ұсыныңыз. Ойнау әрдайым ұрысқаннан оңай әрі қызығырақ.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'Күртеше киюден бас тарту 🧥', 'Далада күн ашық болғандықтан, қыстық күртешесін кигісі келмей ме? Ауа райы мен киім бөлімін ашып, телефоннан қыстық киім киген бала белгісін көрсетіңіз. Ережені цифрлық экранға тапсырып, өзіңіз шетке шығыңыз — ол күртешесін тыныш қана киеді.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'Қараңғыда сыбырлап сырласу 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды немесе оның мінезіндегі өзіңізге ең ұнайтын қасиетін өте бәсең дауыспен құлағына сыбырлаңыз. Сыбырлау — миды ұйқыға дайындайтын ең сиқырлы тәсілдердің бірі.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', '«Бұл менің кінәм емес» деген өтірік 🤥', 'Суды әдейі жерге төгіп, саусағымен ойыншық мәшинесін көрсетіп, «Ол итерді» деді ме? Бұл өтірік айту емес, қорғану механизмі. «Кәне, мына мәшинеге де қалай тазалау керегін үйретейік», — деп, оның миын шебер түрде алдап көріңіз.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'Саябақтағы сырғанақ саясаты 🤝', 'Сырғанақта басқа баланы итеріп, өзі бірінші сырғанағысы келді ме? Ұялғаныңыздан балаңызды ұрмаңыз. «Қазір оның кезегі, содан кейін сен сырғанайсың», — деп, ережені жұмсақ, бірақ нық дауыспен еске салыңыз. Ол әлеуметтік ережелерді осылай үйренеді.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'Жұмыртқа жыламасын 🍳', 'Жұмыртқаны жарғанда оны аяп, жегісі келмей қалды ма? Оның жанашырлығында шек жоқ. «Ол енді сенің бұлшықеттеріңде өмір сүріп, сені күшті етеді» деген сияқты сүйкімді әңгімелермен жағдайды бірден реттеңіз.'),
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1', 'Жастықтарды орналастыру тәртібі 🛏️', 'Жастығын миллиметріне дейін түзету үшін жылап жатыр ма? Ұйықтар алдындағы ерекше әдеттері қалыптаса бастаған. Оның тәртібіне бағынып, жастықты сызғышпен өлшегендей етіп түзетіңіз де, жарықты нық қимылмен өшіріп, оған сенімділік сыйлаңыз.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'Тастаған қоқысымды қайтар! 🗑️', 'Сақтап жүрген ескі шоколад қағазын қоқысқа тастағаныңыз үшін айқай-шу шығарды ма? Сіз үшін ол қоқыс, ал ол үшін қазына. Назарын басқа бір жарқыраған ойыншыққа аударыңыз.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'Үйдің диктаторы дастарқан басында 👑', 'Таңғы ас кезінде «Сен ол жерге емес, мұнда отыр» деп, бәрін өзі басқарғысы келе ме? Оның ерік-жігерін күрт баспай, «Жарайды, сен айтқандай болсын», — деп, тепе-теңдік пен үйдегі тыныштықты жылы жымиыспен сақтаңыз.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'Ешкімге ештеңе түсіндірмеу 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай, бұл ашуыңызды келтіре ме? Көңіл күй күнделігін ашыңыз. Бүгін жүйкеңізге тигеннің бәрін сонда жазыңыз. Эмоцияңызды қабылдап, қағазға түсіру өзіңізді жақсырақ сезінуге көмектеседі.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'Үнсіз кітап оқу сағаты 📖', 'Бүгін кешке дауыстап оқымайсыз. Ақылды ертегілерден жайлы әуенді фонға қосып, суреттерді үнсіз ғана тамашалаңыздар. Миы көргендерінен шаршап, Сіз бір ауыз сөз айтпай-ақ, ол ұйқыға кетеді.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'Дүкен кассасындағы сынақ 🛒', 'Кассаның дәл алдында шоколад сұрап айқайлап тұр ма? Артыңыздағылардың көзқарасына қарамастан, райыңыздан қайтпаңыз. Сатып алу тізімін ашып, «Бұл мұнда жоқ, касса оны өткізбейді» деңіз. Сіз шешіміңізде нық тұрсаңыз, ол да талабынан бас тартады.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'Қолмен емес, ауызбен жеу 🐶', 'Тәрелкедегі тамақты қолын пайдаланбай, мысық сияқты жегісі келе ме? Тыйым салмаңыз. Асүй бәрібір былғанады, 5 минутқа мысық бола тұрсын. Бұл күлкілі рөлдік ойын — тәбетсіздікті жеңудің ең көңілді жолы.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'Әкеден иық массажы 💆‍♂️', 'Бүгін көп уақыт аяқтан тік тұрдыңыз, оның соңынан жүгіріп, жердегі ойыншықтарды жинаудан беліңіз ауырып кетті. Бала ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — үйдің қозғаушы күшісіз, сондықтан міндетті түрде күш жинауыңыз керек.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'Бөлменің тас қараңғы болуы 🌌', 'Дәлізден түскен жарықтан ұйықтай алмай жүр ме? Ол мінсіз жағдайды іздейді. Есікті мықтап жауып, бөлмені толық қараңғылаңыз. Мелатонин табиғи жұмысын атқарып, оның тез ұйықтауына көмектессін.'),
  ('e268e86b-b622-447e-800e-69d444728521', '«Бұл менікі!» дағдарысы 🧸', 'Үйдегі пультті құшақтап алып, «Бұл менікі!» деп тұр ма? Ол меншік шекарасын тексеріп жүр. Оны өзімшіл деп атамаңыз. «Мен үшін тауып бергеніңе рақмет» деп, назарын басқа ойынға аударыңыз да, пультті қайтарып алыңыз.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'Аяқталмаған сөйлемдердің мәні 🗣️', 'Бір сөзді ұмытып қалғанда қолымен ымдап, Сіздің тауып айтуыңызды күте ме? Оның сөйлемін сабырмен аяқтап бергенде, жүзіндегі жеңілдікті байқаңыз. Ол сөздік қорын және өзіне деген сенімін дәл осылай, Сіздің қолдауыңызбен қалыптастырады.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'Ваннадағы шағын зертхана 🛀', 'Суға түрлі түсті сабындарды араластырып, сиқырлы сусын жасап жатыр ма? Жуынатын бөлме былғанады, әрине. Бірақ ол еріткіштердің қасиеттерін зерттеп жүр. Осындай ғылыми ізденіс кешкі шаршауды басып, оны тыныш ұйқыға дайындаудың ең жақсы тәсілі болады.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', '«Сен кімсің?» қойылымы 🎭', 'Сізге бейтаныс адамдай қарап: «Сен кімсің? Менің анам қайда?» — дей ме? Бұл — жаңа рөлдік ойын. «Мен дәрігер апаймын, сенің жүрегіңді тыңдауға келдім», — деп, қытықтап жіберіңіз. Таңертең бөлме күлкіге толсын.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'Дәретхана қағазынан өнер туындысы 🧻', 'Бөлмеге кіргенде, дәретхана қағазының бәрі тарқатылып, үйге жайылып жатқанын көрдіңіз бе? Ашуланудың орнына қағаздарды жинап, бірге доп жасаңыздар. Бейберекетті айқаймен емес, шығармашылықпен және күлкімен жеңіңіз.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'Тыныштықтың рақаты 🤫', 'Ақыры ұйықтады. Үйде құлағыңыз шыңылдайтындай тыныштық орнады ма? Қосымшадағы дыбыс өлшегішті ашыңыз. Экрандағы 0 децибел деген жазуға қарау шуылдан қажып, шаршаған миыңыз үшін әлемдегі ең керемет визуалды массаж болады.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'Кесенің түсі дұрыс емес 🥤', 'Суды сары кесеге құйып бергеніңіз үшін бөлмеде ақырзаман орнады ма? Мұны көңіліңізге алмаңыз, ол бүгін таңертең Сіздің шегіңізді тексеріп жүр. Суды дереу көк кесеге құйып, бөлмеде тыныштық орнатыңыз да, күшіңізді сақтаңыз.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'Жай ғана бауырыңызға басыңыз 🫂', 'Бүгін ол Сізді шынымен есіңізден тандырып, бар күшіңізді сарқып қойды ма? Бірақ төсекте сондай бейкүнә болып ұйықтап жатыр... Жарықты өшіріңіз, ертегі оқымаңыз. Жанына жатып, баланың жұпар иісін терең жұтыңыз да, шүкіршілік етіңіз.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'Басқа аналардың оқиғалары 💬', 'Инстаграмды аша сала жұрттың мінсіз балаларын көріп, көңіліңізді түсірмеңіз! Ол қолданбаны жауып, Anacan қауымдастығына кіріңіз. Басқалардың да үйі Сіздікіндей астан-кестен болып жатқанын көріп, терең тыныс алыңыз.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', '«Қолымнан ұстама!» дербестігі 🚶‍♂️', 'Жолда қолыңызды жіберіп, өзі еркін жүргісі келе ме? Қауіпсіз жерде болсаңыздар, өз дербестігін сынап көрсін. Сіз осы кішкентай еркін бүлікшіні екі қадам артынан мақтанышпен бақылап жүріңіз.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'Асүйдегі апатты көмек 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол орындығын әкеліп қойып, ұнды міндетті түрде өзі төккісі келді ме? Рұқсат бермесеңіз, жылайды. Оған кішкентай пластик ыдыс пен аздап ұн беріңіз. Асүйдің астан-кестені шығады, есесіне оның көңілі тоқ болады.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'Ай артымыздан жүгіріп келеді 🌕', 'Кешке көлікпен қайтып келе жатқанда, терезеден қарап, Ай бізді аңдып келеді дей ме? Ол бүкіл ғалам өзін айналып жүреді деп ойлайды. Қиялын бұзбай, «Қызық, ол бізбен бірге қайда бара жатыр екен?» деп ойынға қосылыңыз.'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'Кір жейдеге деген махаббат 👕', 'Үш күннен бері бір жейдені киіп, жууға бермей жүр ме? Бұл жаста кейбір заттар балаға сенімділік сезімін сыйлайды. Дауласпай-ақ, «Жейдеңді кір жуғыш машинадағы сиқырлы шытырман оқиғаға жібердім, күшейіп қайтып келеді» деген ертегі айтып, қолынан алыңыз. Ол бұл қиялға сенеді.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'Құмырсқаны жоқтау рәсімі 🐜', 'Саябақта жерде жүрген құмырсқаны көріп, орнынан қозғалмай, «Ол адасып кетті» деп жылап тұр ма? Оның жанашырлығында шек жоқ. «Қазір анасы келіп, алып кетеді» деп айтыңыз.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'Батпақтағы ақ шу 🌊', 'Бөлмесінде ұйықтаудың орнына ары-бері секіріп жүр ме? Дыбыс өлшегіштің фонынан қуатты теңіз толқынының немесе ақ шудың дыбысын қосыңыз. Бірсарынды жиілік миындағы алапат энергияны басып, 10 минуттан кейін көздері жұмылады.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'Сыпырғышпен жасалған апатты көмек 🧹', 'Сіз үй жинап жатқанда, ол келіп, «Мен істеймін» деп қоқысты бөлмеге одан сайын шашып жібере ме? Рұқсат бермесеңіз, айқай-шу басталады. Қолына дымқыл майлық беріп, «Сен тек мына үстелдің бұрышына жауаптысың» деңіз. Сіз де жұмысыңызды бітіресіз, ол да өзін маңызды сезінеді.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'Бос қабырғаға қарайтын уақыт 🛋️', 'Ол бөлмеде өз бетімен ойнап отыр ма? Айналайын, бұл сәтті ыдыс жууға жұмсамаңыз! Диванға жайғасып, қолыңызға шайыңызды алып, қабырғаға үнсіз қарап отырыңыз. Иә, ештеңе ойламай. Көңіл күй күнделігіне 5 минуттық тыныштық деп жазыңыз. Бұл Сізге қажет.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', '«Шашым сынып қалды!» драмасы 🪮', 'Тарақты көре сала, «Шашым ауырып тұр» деп қаша ма? Сенсорлық сезімталдық оны қорқытады. Назарын басқаға аударыңыз. Қолына айна беріп, «Қане, айнаға қарап, кім тілімен күлкілірек қимыл жасайды екен?» деңіз де, назары ауып тұрғанда шашын жылдам тарап бітіріңіз.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'Тыныштықтың экрандағы дәлелі 📉', 'Ақыры ұйықтады. Құлағыңызда әлі де айқайдың жаңғырығы естіліп тұр ма? Дыбыс өлшегішті қосыңыз. Бөлмедегі дыбыс деңгейінің 0 децибелге дейін түскенін көрсететін сызықты бақылау шаршаған әрі ісініп кеткен миыңыз үшін әлемдегі ең керемет визуалды массаж болады.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'Әкенің ойдан шығарған ертегісі 🦸‍♂️', 'Даусыңыз шықпай, кітап оқығыңыз келмей тұр ма? Ертегіні әкесіне тапсырыңыз. Әкесі басты кейіпкері баланың өзі болатын ойдан шығарылған, қисынсыз бір оқиғаны айтып берсін. Қабырғаға сүйеніп демалып жатып, баланың әкесіне қалай қарқылдап күлетінін тамашалаңыз.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'Бұл тағамның пішіні дұрыс емес 🥒', 'Қиярды дөңгелектеп емес, ұзынша турағаныңыз үшін тәрелкені итеріп жіберді ме? Тағамға қатысты эстетикалық талғамы енді қалыптасып келеді. Сол көкөністі қызықты пішіндерге айналдырып ұсынуды үйреніңіз. Бұл дизайн ойынында Сіз жеңіске жетесіз.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'Жалғыз қалу үшін жуынатын бөлмеге қашу 🛀', 'Күні бойы аяғыңызға оратылып, біреудің қайта-қайта жанасуынан әбден қажыдыңыз ба? Жанасудан шаршау — шынайы сезім. Оны бөлмеде қалдырып, жуынатын бөлмеге 5 минутқа кіріңіз де, есікті жауып, жай ғана тыныс алыңыз. Сізге күш жинау қажет.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'Өзі ойлап тапқан әндер 🎤', 'Күн әлі шықпаса да, ол секіріп жүріп, мағынасыз сөздермен бар даусына салып ән айтып жүр ме? Айқайлап, үнін өшірмеңіз. Таңын әнмен бастаған бала бойындағы агрессиясын шығарады. Сол тасыған энергияға Сіз де 1 минутқа қосылыңыз — ұйқыңыз бірден ашылады.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Instagram-дағы мінсіз аналар 📱', 'Instagram-ды аша сала, жұрттың жинақы үйі мен ақылды баласын көріп, еңсеңіз түсіп кетті ме? Сол қолданбаны өшіріңіз! Anacan қауымдастығына қосылыңыз. Үйі Сіздікіндей шашылып жататын, баласы қырсық шынайы аналардың хикаяларын оқып, көңіліңізді орнына түсіріңіз.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'Сыбырмен келген ұйқы 🤫', 'Төсектен қашып, бір жерден екінші жерге секіріп жүр ме? Даусыңызды кенеттен мүлде бәсеңдетіңіз. Өте ақырын сыбырлап сөйлей бастаңыз. Сізді түсіну үшін ол бар зейінін жинауға мәжбүр болады, ал миы 5 минут ішінде шаршап, ұйқы режиміне көшеді. Байқап көріңіз!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'Тоңазытқыштан табылған ойыншық 🧊', 'Тоңазытқышты ашқанда, ішінен резеңке мәшине шықты ма? Бұл — есте сақтау қабілетін және затты басқа кеңістікке орналастырып көруді сынайтын ойын. Ашуланбаңыз, мұндай қисынсыз әрекет — оның дамуының бір бөлігі.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'Кенеттен келген философиялық сұрақ 🤔', '«Теңіздің түбі неге қараңғы?» деп кенет ғылыми сұрақ қойды ма? Абыржымаңыз! Anacan AI-ды ашып, осы жастағы бала түсінетіндей ең сүйкімді, педиатр мен психолог мақұлдаған ертегіге ұқсас жауапты алып, оған оқып беріңіз. Сіз әрдайым бәрін білетін анасыз!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'Қараңғы бөлмедегі қуаласпақ 🔦', 'Ұйықтайтын уақыт болды, бірақ оның энергиясы әлі таусылмады ма? Бөлмедегі барлық жарықты өшіріңіз. Қолыңызға кішкентай қолшам алып, «Жарық қабырғада кімді ұстайды екен?» ойынын ойнаңыз. Қараңғыда ойнау мелатониннің бөлінуін жылдамдатып қана қоймай, оны шаршатады да.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'Көрінбейтін жараның азабы 🩹', 'Саусағында ештеңе жоқ, бірақ «жараланды» деп жылап, жапсырма таңғыш сұрай ма? Бұл физикалық ауырсыну емес, оған Сіздің мейіріміңіз қажет. Таңғышты жапсырып, сүйіп қойыңыз да, «Сиқырлы сүйіспен емдеп қойдым» деңіз. Осылайша күніңіз сәтті жалғасады.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'Есікті жабу және жеке кеңістік 🚪', 'Өз бөлмесіне кіріп, есікті жауып алды да, «Келме» деді ме? Ренжімеңіз. Ол жай ғана шу мен қарбаластан оқшауланып, тыныққысы келеді. Егер қауіпсіздігіне алаңдайтын себеп болмаса, жеке кеңістігінен ләззат алуына мүмкіндік беріңіз. Ол өсіп келеді!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'Түнгі таусылмайтын сылтаулар 🚰', 'Көзі жұмылып бара жатса да, кенет «Аяғым қышып кетті», «Су ішкім келеді» деп атып тұра ма? Ол ұйқыны кейінге қалдырудың нағыз профессоры. Таймер орнатыңыз. «Телефон шырылдағанда, барлық сылтау да ұйықтайды» деңіз. Билікті телефонға тапсырып, өзіңіз шетке шығыңыз.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'Бұл менің атым емес 📛', '«Мені өз атыммен атама, мен Өрмекші адаммын» дей ме? Бұл — өзіндік болмысын іздеу кезеңі. Ойынға қосылыңыз! Таңғы асын «Алыңыз, Өрмекші мырза» деп ұсыныңыз. Бөлмедегі шиеленісті әп-сәтте күлкіге айналдыру Сіздің қолыңызда.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'Дүкендегі тізіммен тойтарыс беру 🛒', 'Кассаның алдында кенет кәмпит талап етті ме? Айналадағы адамдардың «Бұл қандай ана?» дегендей көзқарасына мүлде мән бермеңіз. Сатып алу тізімін ашып, «Бұл тізімде жоқ, сондықтан касса бізге оны сатпайды» деңіз де, шешіміңізден таймаңыз.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'Бояу қабырғаға жайылып кетті 🖍️', 'Бөлмеге кіріп, қабырғадан жаңа фреска көрдіңіз бе? Терең тыныс алыңыз. Ол қағаздың шекарасынан шығып, ірі ауқымда қимыл-қозғалыс дағдыларын сынап жүр. Өшірмес бұрын, болашақта өзіне көрсетіп, бірге күлу үшін бұл жауһарды міндетті түрде суретке түсіріп алыңыз.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'Үйден шыққысы келмейді ⛅', 'Үй астан-кестен, ал ол диванда жылап, бармаймын деп отыр ма? Ауа райы мен киім бөлімін ашып, сырттағы нақты температураны тексеріңіз, соған сай киіндіріп, қарсылық білдірсе де, саябаққа алып барыңыз. Таза ауа бетіне тиген сәтте-ақ бүкіл ашуы басылады.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'Ертегінің кейіпкеріне айналғанда 🪄', 'Ақылды ертегілерді ашыңыз. Ондағы кейіпкердің атын балаңыздың атымен ауыстырыңыз. Ертегі бойы сол кейіпкердің қалай батыл әрі тілалғыш болып ұйықтағанын оқыңыз. Ертегіден өз атын естігенде, еш қарсылықсыз көзін жұмады.'),
  ('139226ae-9370-42b4-954a-012623528599', 'Түн ортасындағы түсініксіз жылау 😭', 'Түн ортасында көзі жұмулы күйде жылап оянып, Сізді естімей жатыр ма? Жылауды талдау арқылы тексеріңіз; бұл түнгі қорқыныш болуы ықтимал. Оятуға тырыспай, жанында болып, қолынан ұстаңыз. Ол өздігінен тынышталып, қайта ұйықтап қалады.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'Ананың жасырын шоколад сағаты 🍫', 'Шкафтың тасасында одан жасырынып шоколад жеп отырсыз ба? Ас болсын! Таусылмайтын «негелерге», айқайға төтеп беріп, күш-қуатыңызды қалпына келтіру үшін бұл глюкозаға толық құқығыңыз бар. Бұл үшін өзіңізді ешқашан кінәламаңыз.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'Көлеңкемен қуаласпақ 🏃‍♂️', 'Көшеде келе жатып, кенет жүгіріп, өз көлеңкесін ұстауға тырыса ма? Оның қиялы логикасынан басым түсіп тұр. Оны тоқтатпаңыз, Сіз де өз көлеңкеңізді ұстауға тырысып, көше ортасындағы осы ессіз әрі көңілді ойынға қосылыңыз. Өмір оны тым байыппен қабылдайтындай ұзақ емес.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'Аяқкиімді теріс кию синдромы 👟', 'Оң аяқкиімді сол аяғына, сол аяқкиімді оң аяғына киіп алып, түзетуге рұқсат бермей ме? Солай қала берсін! Оның «өзім кидім» деген мақтанышы мен дербестік сезімі аяқкиімнің дұрыс киілуінен миллион есе құнды.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'Іштегі ашуды экранға шығару 📝', 'Бүгін қаншалықты шаршағаныңызды ешкім байқамай, күлімсіреу Сізге ауыр тиіп жүр ме? Көңіл күй күнделігін ашыңыз. Ішіңіздегі бар ашу мен шаршауды экранға төгіңіз. «Менің күшім таусылды» деп жазу жалған мінсіздікке ұмтылғаннан әлдеқайда тезірек жеңілдік сыйлайды.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'Әкенің иыққа жасайтын массажы 💆‍♂️', 'Бүгін көп уақыт аяғыңыздан тік тұрып, оның артынан жүгіріп, жердегі ойыншықтарды жинаудан беліңіз ауырып кетті. Бала ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — осы үйдің қозғалтқышысыз, ал қозғалтқыш міндетті түрде демалып, қалпына келуі керек.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'Көкөністерді жасыру өнері 🥦', 'Сорпаның ішіндегі жалғыз сәбізді тауып алып, «Мынаны жемеймін» деді ме? Көкөністерді езіп, тұздықтарға қосыңыз — енді қалай табар екен! Оның аспаздық тапқырлығын шеберлікпен жеңіңіз.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'Мен ұшқым келеді! 🕊️', 'Диваннан секіріп, қолдарын қағып, ұша алмағаны үшін Сізге ашулана ма? Оған физика заңдарын түсіндіруге әлі ерте. «Сен ұша алмайсың, өйткені қанаттарың әлі өсіп жатыр» деп, назарын жұмсақ жерге секіруге аударыңыз.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'Өз суретін сынау 🖍️', 'Салған сызығы ұнамай, «Жаман болып қалды» деп қағазды жыртып тастай ма? Бұл — өзін сынау мен мінсіздікке ұмтылудың қалыптаса бастағаны! «Келесі жолы басқа түсті қолданып көрейік» деп, оның көңілі қалуын қолдау көрсететін жаңа ізденіске айналдырыңыз.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'Қауымдастықтағы үнсіз жұбаныш 💬', 'Қатты шаршадыңыз, тіпті ешкіммен сырласқыңыз келмей ме? Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың дәл сондай қисынсыз дағдарыстармен қалай күресіп жүргенін көру Сізге ең күшті үнсіз жұбаныш болады.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'Ваннадағы мұхит дауылы 🌊', 'Шомылу — жай ғана сылтау, ал ваннада мұхит жасап, толқындармен ойнап жүр ме? Ойнай берсін. Судың шуы мен шашыраған тамшылары бойындағы сарқылмас тентек қуатты жуып әкетеді. Кешке еш қарсылықсыз төсегіне жатады.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'Таңғы тосын философия 🤔', 'Кенеттен «Жел неге көрінбейді?» деген ғылыми сұрақ қойды ма? Абыржымаңыз! Anacan AI-ды ашып, осы жастағы бала түсіне алатын, педиатр мен психолог мақұлдаған ең сүйкімді ертегі іспетті жауапты алып, оған оқып беріңіз. Сіз — әрқашан бәрін білетін анасыз!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'Жай ғана тыныш жата тұру 🛋️', 'Ол өз бетінше пазл құрастырып, үй іші кенет тыныштала қалды ма? Сол сәтті үй сыпыруға жұмсамаңызшы! Диванға жатыңыз. Кешке дейін осы қарқынға төтеп беру үшін Сіздің де қуатыңыз толуы керек. Міндетті түрде демалыңыз.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'Қалтадан шыққан қазыналар 🪨', 'Шалбарын жуып жатқанда қалтасынан кепкен жапырақ немесе тас шықты ма? Бұл дүниеқоңыздық емес, балалық зерттеушілік. Оны байсалды кейіппен қоқысқа тастаңыз, бірақ әлемді танып жүрген осы кішкентай жинаушыға іштей жымиып қойыңыз.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'Бананды неге Сіз аршыдыңыз?! 🍌', 'Бананды Сіз аршығаныңыз үшін бөлмеде төңкеріс басталды ма? Бұл жастың алтын ережесі: бәрін өзі шешуі керек. Бананды қайта жабыстыра алмайсыз, сондықтан бірден жаңасын беріп, өзі қалағандай аршуға мүмкіндік беріңіз. Қырсықтасу тек уақытыңызды алады.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'Екеуіңіз үнсіз отырған сәт 🥂', 'Бөпе ұйықтады, үй жиналды. Жұбайыңызбен диванға қатар отырыңыз да, тіпті теледидарды қоспаңыз. Бір-біріңізге жай ғана «Мұны да еңсердік, аман қалдық» деген көзқараспен қараңыздар. Ата-ана болудың ең романтикалық әрі шынайы командалық сәті — дәл осы.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'Үстел астындағы кішкентай үй ⛺', 'Ас үстелінің астына кіріп, өзіне үй жасап алды да, түскі асын сонда ішкісі келе ме? Ережелерді сәл жұмсартыңыз. Сорпаны сол қараңғы жерге ұсыныңыз. Орынды ауыстыру тіпті тәбеті жоқ баланың өзін қызықты оқиғаға еліктіріп, тамақтандыруға көмектеседі.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'Сіз менімен ойнамайсыз! 😠', 'Сіз телефонға қарап отырғанда, ол келіп, бетіңізді қолымен өзіне бұрып: «Маған қараңызшы!» деді ме? Ол дұрыс айтады. Оған Сіздің қасында болғаныңыз ғана емес, бар назарыңызды бөлмей аударғаныңыз қажет. Телефонды шетке қойып, 3 минут бойы көзіне тіке қараңыз — ол бірден тынышталады.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'Жиекжолдағы арқанмен жүруші 🧱', 'Саябаққа бара жатқанда түзу жолмен емес, міндетті түрде жиекжолдың ең тар шетімен жүргісі келе ме? Қолынан ұстап, қауіпсіздігін қамтамасыз етіңіз де, осы кішкентай шыңды бағындыруына мүмкіндік беріңіз. Осылайша тепе-теңдік сақтау қабілеті мен өзіне деген сенімі қатар дамиды, оған кедергі жасамаңыз.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'Бөлмедегі дыбыс әсерлері 🪄', 'Бүгін кешке оқып беруден шаршадыңыз ба? Ақылды ертегілерді қосыңыз. Ертегі оқылып жатқанда, есіктің сықырын, желдің гуілін және сыбырлаған дауысты салып, бөлмеде дыбыс театрын ұйымдастырыңыз. Бұл ерекше дыбыстар оның назарын бірден ертегі әлеміне жетелейді.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'Саябақтан қайтуға арналған жарыс тәсілі 🌳', 'Саябақтан қайтатын уақыт келді, ал жылау мен қырсығу басталды. Оны сүйреп әкету көмектеспейді. «Көлікке дейін кім қоян сияқты тезірек секіріп жетеді екен?» деп, назарын бірден көңілді жарысқа аударыңыз. Ол міндетті түрде жарысқа кіріседі.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'Жай ғана иісін терең жұтыңыз 🫂', 'Бүгін ол Сізді шынымен ашуландырып, бар қуатыңызды сарқып жіберді ме? Бірақ төсекте сондай пәк кейіппен ұйықтап жатыр... Жарықты өшіріңіз. Жанына жатып, баланың сол жұпар иісін терең жұтыңыз да, оның Сіз үшін қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'Суды басқа стақанмен беріңіз! 🥤', 'Суды сары стақанға құйып бергеніңіз үшін бөлмеде ақырзаман орнады ма? «Мен көк стақанды қаладым!» дейді. Бұған бола мәселені ушықтырмаңыз, ол тек өз шекарасын тексеріп жүр. Суды бірден көк стақанға құйып, бөлмеде тыныштық орнатыңыз да, күшіңізді үнемдеңіз.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'Динозаврлар ботқа жемейді! 🦖', 'Таңертең ешбір сұраққа жауап бермей, тек ақырып жүр ме? Демек, ол бүгін — тираннозавр. «Ал тираннозаврлар таңғы ас іше ме?» деп, оның өзі ойлап тапқан кейпіне еніңіз. Осылайша оны үстел басына жыламай-ақ жаймен отырғыза аласыз.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'Дүкеннің ортасында абдырап қалмаңыз 🛒', 'Дүкенге кіріп, не алатыныңызды ұмытып қалдыңыз ба? Ана болғаннан кейін мида ой көбейетіні рас. Қолданбадағы Сатып алу тізімін ашып, сол цифрлық жадыңызға сеніңіз — сонда үйге құр қол қайтпайсыз.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Бөпеңіздің тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық теледидар мен телефон экранын өшіріңіз. Қараңғы ортада мелатонин жылдам бөлінеді, табиғи үдеріс Сіздің орныңызға жұмыс істесін.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'Бұл қоқыс емес, өнер туындысы 🎨', 'Бөлменің ортасында құрғақ макарон мен қағаз қиындыларынан үлкен өнер туындысын жасап қойды ма? Тазалыққа тым қатты мән бермеңіз. Бұл — Даму трекеріне қосуға тұрарлықтай керемет ірі моторика жұмысы. Үй мұражай емес.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'Тыныштықтың экрандағы көрсеткіші 📉', 'Ақыры ұйықтады. Үйдің іші тынышталып, тіпті құлағыңыз шыңылдап тұр ма? Қолданбадағы Дыбыс өлшегішті ашыңыз. Экрандағы 0 децибел жазуына қарау шаршаған, шудан қажыған миыңыз үшін әлемдегі ең жақсы визуалды массаж болады.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'Аяқталмаған сөйлемдерді толықтырыңыз 🗣️', 'Бір сөзді ұмытып қалғанда қолымен ымдап, Сіздің тауып беруіңізді күте ме? Оның сөздік қоры өсіп келеді, бірақ миы тілінен жылдамырақ жұмыс істейді. Сөйлемін сабырмен толықтырған кезде жүзінен байқалатын «Иә, дәл соны айтқым келген» деген жеңілдікті тамашалаңыз.'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'Әкесімен диванда күресу 🤼‍♂️', 'Төсекке жатпау үшін қашып, тығылып қалды ма? Кезекті әкесіне беріңіз. Екеуі диванда өтірік күрессін. Сол шулы, терлететін әкелі-балалы ойын баланың бойындағы соңғы тентек қуатты да сарқып, оның ұйқыға оңай берілуіне көмектеседі.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', '«Бұл менікі!» деген қырғын 🧸', 'Үйдегі пультті құшақтап алып: «Бұл менікі!» дей ме? Ол меншік шекараларын тексеріп жүр. Оны өзімшіл деп атамаңыз. «Маған тауып бергеніңе рақмет» деп, назарын басқа ойынға аударыңыз да, пультті ақырын қайтарып алыңыз.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'Қоңырау соғылғанда ұйықтаймыз ⏱️', 'Ұйықтау уақыты созылып кете бере ме? Су ішу, дәретханаға бару, қабырғамен қоштасу... Телефонға таймер қойыңыз. «Қоңырау үнін естігенде, бәріміз жарықты өшіреміз» деген ереже енгізіңіз. Сырттан қойылған талапқа бағыну оларға әрдайым оңайырақ.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'Ешкімге есеп бермеңіз 🛑', 'Бүгін шыдамыңыз таусылып, даусыңызды көтеріп қойдыңыз ба? Өзіңізді жазғырмаңыз. Көңіл күй күнделігіне: «Мен жақсы анамын, тек бүгін қатты шаршадым», — деп жазыңыз. Өзіңізге жанашыр болыңыз, ешкім Сізден мінсіз болуды күтпейді.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'Ананың қуат батончигі 🥗', 'Оны тамақтандыру үшін түрлі мәзір ойластырдыңыз, ал өзіңіз не жедіңіз? Пайдалы рецептер бөліміндегі аналарға арналған, небәрі 5 минутта дайын болатын оңай салатты жасап көріңіз.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'Тыныштықтағы ыстық шай ☕', 'Бала ақыры ұйықтады. Бөлменің ортасында шашылып жатқан ойыншықтарға қарап, терең тыныс алыңыз. Оларды қазір жинамаңыз! Өзіңізге ыстық шай құйып, диванға жайғасыңыз да, осы тыныштық сыйлаған мамыражай сәттен ләззат алыңыз.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'Жансыз заттармен ұзақ әңгімелесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа бар ықыласымен бірдеңе айтып жүр ме? Ол ойын арқылы ережелерді және қоршаған әлемді танып-біліп жүр.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'Күртешеден бас тарту 🧥', 'Далада күн ашық болғандықтан қысқы күртешесін кигісі келмей ме? Терезеден қарап алданып қалмаңыз. «Ауа райы және киім» бөлімін ашып, телефоннан қысқы киім киген бала белгісін көрсетіңіз. Ережені цифрлық экранға тапсырып, өзіңіз даудан шет қалыңыз.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'Кереует астындағы жасырынбақ 🛏️', 'Кереуетінде емес, міндетті түрде оның астында ұйықтағысы келе ме? Осындай шағын әрі тұйық кеңістік оған ана құрсағындағыдай қауіпсіздік сезімін береді. Рұқсат етіңіз, ұйықтап қалған соң ақырын кереуетіне жатқызарсыз. Күшіңізді үнемдеңіз.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'Түн ортасындағы кенет айқай 😭', 'Түнде көзін ашпастан жылап оянып, Сізді естімей ме? Жылауын талдап көріңіз: бұл — түнгі қорқыныш. Оятуға тырыспаңыз, тек жанында болып, қолынан ұстап, сипаңыз. Ол өздігінен тынышталып, қайтадан терең ұйқыға кетеді.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Anacan-нан Сізге хат келді 💌', 'Пайдалы тағамдарға білдіртпей қосылған көкөністер, Көңіл күй күнделігіне төгілген көз жасы және әбден қажыған сәттер... Осы 4 жылда Сіз әлемдегі ең қиын мамандықты меңгердіңіз. Енді Сізге ешбір қолданба қажет емес: өз түйсігіңізге сеніп, бейберекеттікті басқара алатын қаһармансыз. Біз тек сырттай бағыт-бағдар бердік, ал ең маңызды істің бәрін атқарған — Сіз!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', '1460-күн: Біздің қолымыздан келді! 🚀', 'Таңертең оянып, оған қарайсыз... Ол енді тура 4 жаста! Сіз дәл 1460 күн бойы ұйқысыздықпен, ашу ұстамаларымен және қырсықтықпен күресіп, осы кішкентай адамды өсірдіңіз. Осы жылдар ішінде Сіз тек бала өсіріп қана қоймай, өз бойыңызда күшті, жеңілмейтін жаңа ананы қалыптастырдыңыз. Бүгін ешқандай ереже жоқ, оны жай ғана құшақтап, өзіңіз жасаған осы ғажайыпқа мақтанышпен қараңыз.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'Соңғы хабарландыру, соңғы тыныштық 🌌', 'Ол ұйықтап қалды. Жарықты өшіріңіз. Бұл — қолданбадан Сізге келетін соңғы хабарландыру. 1460 күн бойы шаршағаныңызда, жылағаныңызда және тығырыққа тірелгеніңізде Сізді түсініп, үнсіз жаныңыздан табылуға тырыстық. Енді телефонды шетке қойыңыз. Сіз мінсізсіз, Сіз жеткіліктісіз. Бұдан кейінгі ғажайып хикаяны өзіңіз, ешкімнің көмегінсіз жазасыз. Сізбен бірге осы жолдан өту біз үшін үлкен мәртебе болды. Кездескенше, Anacan! ❤️'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'Мұздай қисынсыздық 🥶', 'Ыстық шайды үрлеп ішудің орнына, ішіне міндетті түрде мұз салуды талап ете ме? Ол ыстық пен суықтың айырмашылығын танып жатыр. Мұзды беріңіз де, оның еруін бақылауына мүмкіндік беріңіз. Таңғы ас кешіксе де, ол өзінің ғылыми жаңалығын ашып үлгереді.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'Жаңбыр үніне толы ертегі бөлмесі 🌧️', 'Даусыңыз шықпай, ертегі оқуға күшіңіз жоқ па? Ақылды ертегілерден фон ретінде тек жаңбыр мен орман дыбысын қосыңыз. Табиғаттың осындай бірқалыпты тыныштығы кейде ең қызықты, шытырман оқиғалы ертегіден де тез әлдилеп, ұйқыға батырады.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'Айнадағы өзіне ашуланады 🪞', 'Айна алдына тұрып, түрлі дыбыс шығарып, бет-әлпетін өзгерте ме? Бұл — өзіндік санасының қалыптасып келе жатқанының белгісі. Ол өз денесін және эмоцияларының сырт көзге қалай көрінетінін зерттеп жүр. Үндемей сырттай бақылаңыз.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'Жанасудан шаршау төңкерісі 🔋', 'Күні бойы аяғыңызға жармасып, құшақтауды сұрай ма? Сіз физикалық тұрғыдан әбден қажыдыңыз. Жанасудан шаршауды сезініп жүрсіз. Оны бөлмеде ойыншықтарымен қалдырып, 5 минутқа жуынатын бөлмеге кіріп, есікті жабыңыз. Сол оңашалықты жай ғана сезініңіз.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'Саябақтан қайтардағы айқас 🤝', 'Сырғанақта басқа баланы итеріп, өзі сырғанағысы келді ме? Жұрттың бәрі Сізге қарап тұр. Ұялып, балаңызды ұрмаңыз. «Қазір оның кезегі, содан кейін біз сырғанаймыз» деп, ережені жұмсақ, бірақ нық дауыспен еске салыңыз. Тәртіп осылай орнайды.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'Таң атпай қуаласпақ 🏃‍♂️', 'Таңғы сағат 7-де дивандардың үстінде жүгіріп жүр ме? Айқайламаңыз. Істеріңізді 2 минутқа қоя тұрып, Сіз де секіріп, оған қосылыңыз. Баланың қиял әлеміне ену — Сіз үшін де біртүрлі көрінгенімен, күйзелістен арылудың өте тиімді тәсілі.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'Түнгі қорқыныштың ғылыми шешімі 🔦', 'Жатын бөлмедегі көлеңкелерден қорқа ма? Бөлмені тас қараңғы етпей, жылы түсті кішкентай түнгі шам қойыңыз. Бұл мелатониннің бөлінуіне кедергі келтірмейді әрі балаға көзбен көретін қауіпсіздік сезімін сыйлап, қорқынышын басады.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'Кенеттен «Сені жақсы көремін» 💖', 'Бөлменің ортасында ойнап жүріп, кенет Сізге қарап, жүгіріп келіп, мойныңыздан құшақтайды. Барлық ұйқысыз түн мен шаршауға тұрарлық сәт! Осы сәт сыйлаған терең әрі ерекше тыныштықтан ләззат алып, айналадағы аласапыранды ұмытыңыз.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'Сыбырдың тылсым күші 🤫', 'Төсектен қашып шығып, әр жерге секіріп жүр ме? Даусыңызды кенеттен мүлде бәсеңдетіңіз. Өте ақырын сыбырлап сөйлей бастаңыз. Сізді түсіну үшін бар зейінін жинайды, ал миы 5 минутта шаршап, ұйқы режиміне ауысады. Байқап көріңіз!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Instagram аналарының иллюзиясы 📱', 'Instagram-ды ашқан сайын жұрттың жинақы үйі мен тілалғыш баласын көріп, көңіліңіз түсіп кете ме? Ол қолданбаны өшіріңіз! Anacan қауымдастығына қосылыңыз. Үйі Сіздікіндей шашылып жататын, баласы қырсық мінез көрсететін шынайы аналардың оқиғаларын оқыңыз.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'Әкенің ұйықтататын ертегісі 📖', 'Даусыңыз қарлығып, ертегі оқуға шамаңыз жоқ па? Бұл жолы әкесіне тапсырыңыз. Әкесінің өзгеше қоңыр даусы мен өзі ойдан қосатын қисынсыз оқиғалары баланың миын Сіздің үйреншікті даусыңыздан да тезірек баурап, ұйқыға жетелейді.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', '«Сен кімсің?» қойылымы 🎭', 'Таңертең Сізге бөтен адамдай қарап: «Сен кімсің? Анам қайда?» — деді ме? Бұл — жаңа рөлдік ойын. «Мен көрші апаймын, анаң қазір келеді», — деңіз. Таңғы бөлме күлкіге толсын: бұл қырсықтасудан әлдеқайда аз күш жұмсатады.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'Өз тамағын Сізге бермейді 🍳', 'Өз тәрелкесіндегіні Сізге бермейді, бірақ келіп, Сіздің тәрелкеңізден жегісі келіп тұрып ала ма? Балалар ата-анасының таңдауына әрдайым толық сенеді. Таласпаңыз, бір үзімін сүйіспеншілікпен бере салыңыз да, осы күлкілі өзімшілдікке жай ғана жымиыңыз.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'Мен ұшқым келеді! 🕊️', 'Диваннан секіріп, қолдарын қанатша қағады да, ұша алмағаны үшін Сізге ашулана ма? Оған физика заңдарын үйретуге әлі ерте. «Сен ұша алмайсың, өйткені қанаттарың әлі өсіп жатыр», — деп, назарын жұмсақ жерге секіруге аударыңыз.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'Телефон ұрысы 📱', 'Өзіңізге шай құйып жатқанда телефоныңыздың жоғалғанын, ал оның диванның артында Сіз сияқты «Алло» деп тұрғанын көрдіңіз бе? Ол Сіздің цифрлық әдеттеріңізді қайталап жүр. Құрылғыны аларда: «Телефоным да сенімен сөйлескісі келіп тұр екен», — деп, күле отырып қолынан алыңыз.'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'Екеуіңіз үнсіздікте 🥂', 'Бала ұйықтады, үй жиналды. Жұбайыңызбен диванға қатар отырыңыздар, тіпті теледидарды да қоспаңыздар. Бір-біріңізге жай ғана «Мұны да еңсердік, аман қалдық» деген көзқараспен қараңыздар. Сеніңіз, қалжыраған ата-ана үшін нағыз командалық сәт — дәл осы.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'Ертегі оқымай-ақ ұйықтату 🪄', 'Бүгін кешке ертегі оқуға шамаңыз жоқ па? Ақылды ертегілерді қосыңыз. Фонға тек сыбдырлаған орман мен желдің дыбысын қойыңыз. Қараңғыда табиғат үндерін тыңдап, екеуіңіз де күнделікті шудан тынығыңыздар. Көздің шаршауы әп-сәтте басылады.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'Ішімдегі ашуды жазып шығару 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай, бұл ашуыңызды тудыра ма? Көңіл күй күнделігін ашыңыз. Бүгін жаныңызға тигеннің бәрін сонда жазыңыз. Жалған күлімсірегеннен гөрі, сезіміңізді қабылдап, қағазға түсіру Сізге көбірек көмектеседі.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'Мен білемін, Сізге де үйретейін ☝️', 'Өзіңіз білетін нәрсені Сізге өте байсалды әрі ақылды кейіппен түсіндіріп жүр ме? Ол өз білімін сынап жатыр. Күліп жібермеу үшін ерніңізді тістей тұрыңыз да, оны өте мұқият тыңдап: Шынымен бе? Көп рақмет, деңіз. Көңілін бір өсіріп қойыңыз.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'Ваннадағы су тасқыны 🌊', 'Шомылу — жай ғана сылтау, ал ваннада нағыз мұхит жасап, толқындармен ойнап жүр ме? Ойнай берсін. Судың шуы мен шашыраған тамшылар ішіндегі таусылмас тентек қуатын жуып әкетеді. Кешке еш қарсылықсыз төсегіне жатады.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'Асүйде Сізге көмектеседі 🧑‍🍳', 'Сіз қамыр жайып жатқанда, орындығын әкеліп қойып, ұнды міндетті түрде өзі сепкісі келді ме? Рұқсат бермесеңіз, жылайды. Оған кішкентай пластик ыдыс пен аздап ұн беріңіз. Асүй астан-кестен болады, бірақ оның байыпты аспаз кейпін көру үшін жинап-тазалауға да болады.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'Дүкеннің ортасында не үшін келгеніңізді ұмыту 🛒', 'Дүкеннің ортасында тұрып: Мен не алуға келіп едім? деп ойланып қалдыңыз ба? Ананың миы шынымен де сан түрлі ойға толы. Қолданбадағы Сатып алу тізімін ашып, сол цифрлық жадқа сену Сізді мұндай әбігерден әрдайым құтқарады.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'Көйлектің жапсырмасы батып тұр! 🏷️', 'Артындағы кішкентай жапсырма ине сияқты батқандықтан, оны кимеймін деп тұр ма? Бұл жастағы сенсорлық сезімталдық адамды әбден шаршатады. Дауласпай-ақ қойыңыз, қайшыны алып, жапсырманы түбінен қиып тастаңыз да, осы шағын дағдарысты әп-сәтте тоқтатыңыз.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'Мінсіз тыныштық сәті 🛋️', 'Пазлдарымен беріліп ойнағаны сонша, үй іші кенеттен тып-тыныш болып қалды ма? Күмәнданбаңыз, бірден өзіңізге кофе құйып алыңыз. Осындай сирек әрі алтынға бергісіз минуттарды үй жинауға немесе кір жууға емес, жаныңызды тынықтырып, төбеге қарап жатуға арнаңыз. Сіз робот емессіз.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'Аналардың жабық тобы 💬', 'Күрделі шешім қабылдауыңыз керек пе? (Мысалы, балабақша таңдау). Anacan қауымдастығындағы тәжірибелі аналардың кеңестері — ешбір кітапта жазылмаған, іс жүзінде сыналған ең тиімді шешімдер.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'Қараңызшы, мен не істей аламын! 🤸‍♂️', 'Бір аяғымен тұруға немесе секіруге тырысып, назарыңызды аударып жүр ме? Ол Сіздің мақұлдауыңызды қалайды. Даму трекеріне осы тепе-теңдік сақтау дағдысын белгілеп, оны қолпаштаңыз.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'Дүкендегі сол қорқынышты «Қалаймын!» 🛒', 'Кассаның дәл алдында шоколад сұрап айқайлап тұр ма? Артыңыздағылардың көзқарасына қарамастан, беріле салмаңыз. Сатып алу тізімін ашып: «Бұл тізімде жоқ, касса мұны өткізбейді», — деңіз. Сыртқы бір ереже оларға әрдайым сенімдірек көрінеді.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (10 boş-mənbə sətri istisna olmaqla)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_kk IS NULL) AS preg_kk_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_kk IS NULL) AS mommy_kk_bos;
